insert into public.email_automations(id,key,name,trigger_type,is_active) values('1dfe9e9e-a458-5a4a-b8ce-0b90014a21a1','course_intensive-pleasure','Интенсив «Наслаждения»','course',false) on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('4a5a18cc-7153-5b54-b233-410af5793c50','1dfe9e9e-a458-5a4a-b8ce-0b90014a21a1','Вводное письмо',1,0,'{Интенсив Наслаждения} Добро пожаловать!','{"ru":"{Интенсив Наслаждения} Добро пожаловать!","en":"{Pleasures Intensive} Welcome!","de":"{Интенсив Наслаждения} Willkommen!","fr":"{Интенсив Наслаждения} Bienvenue !","it":"{Intensivo Piacere} Benvenuti!","es":"{Интенсив Наслаждения} ¡Bienvenido!","pt":"{Intensivo Prazeres} Boas-vindas!","nl":"{Интенсив Наслаждения} Welkom!"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png" alt="Интенсив «Наслаждения»" width="504" height="128" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!<br> <br>Я рад, что вы решились в течение месяца направить своё внимание и целенаправленно поработать над темой, объединяющей такие состояния, как: наслаждения, расслабленность, кайфушность, игривость, привлекательность, сексуальность... Вроде бы как это простые, доступные каждому состояния. Однако, в социуме действует множество как побудительных, так и запретительных сценариев, которые управляют нашим поведением. Выполняя практики на йоговском коврике и в жизни, размышляя, корректируя свои мысли и поступки, в течение месяца можно получить важные результаты, которые проявятся как на уровне тела (оздоравливание), так и на уровне психологического фона (удовлетворённость и счастье).</p><p></p><p></p><p> В течение этого месяца вы получите 30 практик, направленных на гармонизацию второй чакры. Внимательно прочитайте это письмо, чтобы понимать, что и как будет происходить. <br> <br><strong>1. Самая суть</strong><br> Это не учебный курс, а интенсивный практикум, ядром которого являются ежедневные практики йоги. Данные практики я проводил по утрам в прямом эфире, синхронизируя направление каждой практики с планетными ритмами в тот день. В этом интенсиве я собрал видеозаписи лучших практик, которые были направлены именно на первую чакру (иногда во взаимодействии с какой-нибудь ещё чакрой), дополнил их поведенческими (психологическими) практиками. В результате получился мощнейший заряд для гармонизации сферы здоровья. </p><p></p><p></p><p>Если вы не проходили моих курсов и не понимаете при чём здесь какая-то там «вторая чакра», я рекомендую вам совместить прохождение данного интенсива с практикумом или курсом, в котором я плавно подвожу к пониманию того, чем мы здесь занимаемся. Важно не просто «поверить» мне, а открыть в себе понимание через личный опыт - как на йоговском коврике, так и в жизни. Тогда практики начинают работать гораздо глубже. Иначе получаем физкультуру - так как это базовое понимание (опыт) йоги, которое есть у каждого. </p><p></p><p></p><p>Данный интенсив вы можете дополнить следующими учебными программами:<br> - Практикум «Месяц наслаждений»: <a href="https://zamkovoi.yoga/m2">https://zamkovoi.yoga/m2</a> </p><p></p><p>- Курс «Йога плюс женственность»: <a href="https://zamkovoi.yoga/yoga2">https://zamkovoi.yoga/yoga2</a>  <br>  <br><strong>2. Практики йоги</strong><br> Практики йоги, которые вас ожидают, отличаются от того, что вы можете встретить в фитнес-центре. Я предполагаю, что вам важен результат, а не лицедейство. Мы работаем с внутренними состояниями (то есть с энергиями), соединяя медитацию, пранаяму и асаны в той мере, в которой это необходимо для получения желаемого результата на максимально глубоком уровне. Большинство практик начинаются с небольшого введения, которое необходимо, чтобы ваше сознание переключилось с обыденности на волну практики, вы вошли в соответствующий энергетический поток и активировалось ваше внутреннее намерение. Далее следует сама практика, которая в разные дни имеет разную длительность и состав элементов. После практики я рекомендую вам некоторое время побыть в медитации, а может быть в возникшем состоянии осознанности продолжить выполнять асаны, которые будет просить ваше тело. Средняя продолжительность практик 30-40 минут. Но некоторые практики короче, а некоторые длятся около часа. Важно, чтобы во время практики вас ничто не отвлекало и не торопило. И ещё очень важно - начав практику, не прерывайтесь до её окончания!!! Каждая практика - это живая история, которая проводит вас по определённому пути. Прервав практику, вы можете оказаться в менее ресурсном состоянии, чем были в её начале. Даже если сейчас эти слова вам кажутся мистификацией и пустой эзотерикой, прислушайтесь к моим рекомендациям. <br>  <br><strong>3. Поведенческие практики</strong><br> Каждый день в письме вместе с практикой йоги я буду присылать вам «совет дня». Попробуйте воспринимать его не как ещё одну умную мысль, подобную которой вы уже много раз слышали. У меня нет цели вас удивить, сказав то, что вы ещё не слышали. Воспринимайте этот «совет» как задание, как поведенческую практику! Выполняйте эту практику в данный день. И поверьте - вам станет гораздо интересней, и этот интенсив принесёт вам гораздо больше пользы. Некоторые такие практики могут казаться вам проще, некоторые сложнее. Некоторые прагматичнее, некоторые более психологическими. В любом случае, это не как если бы я предложил вам 20 раз присесть. Тут мы работаем с вашими поведенческими и психологическими шаблонами. И ключ к успеху в том, чтобы не сражаться с собой, не вызывать дополнительное внутреннее напряжение, а как в асанах - дышать и расслабляться. Поэтому практика звучит мягко - как &quot;совет дня&quot; - чтобы не вызывать сигнал тревоги. Прочитайте, примерьте, попробуйте в течение дня мягко следовать этому совету или хотя бы вспоминать его, вновь примеряя и возвращаясь в ощущение, что вы ему следуете. Адаптируйтесь к новым состояниям... В некоторых случаях одна такая практика может растянуться на несколько дней или даже месяцев, потому что вы ощутите её значимость, и начнёте внедрять её в свою жизнь на уровне привычки, то есть корректируя текущий гомеостаз системы. И, хотя я не закладывал чёткую связь между поведенческими практиками и практиками йоги, которые предлагаю в одном письме, тем не менее вы можете выполнять каждую практику йоги в состоянии, возникшем когда вы воспринимаете себя следующим моему совету. Однако, это вовсе не обязательно, так как каждая из этих двух практик самодостаточна.<br>  <br><strong>4. Расписание занятий</strong><br> Каждый день в полночь вам будет открываться новая практика (прошлая при этом будет исчезать, как прошлый день). Благодаря такому подходу, у вас не будет накапливаться снежный ком невыполненных практик. В течение суток вы можете выбрать любое удобное вам время, и позаниматься. Я рекомендую вам заниматься утром, чтобы в полученном в результате практики состоянии проживать день, а не спать лечь. Воспринимайте этот интенсив не как компьютерную иллюзию, а как реальную жизнь - в которой всё важное происходит СЕГОДНЯ, и практика йоги расширяется с коврика на пространство вашей проявленности в том мире, который вы воспринимаете, как наиболее реальный!</p><p></p><p></p><p>Кстати, есть небольшой нюанс с временем получения второй практики. Если вы записались до 18:00, то вторую практику вы получите в ближайшую полночь. Если же вы записались после 18:00, то вторую практику вы получите не в ближайшую, а в следующую полночь. То есть у вас будет запас времени на случай, если вы не успеете выполнить практику в день записи на интенсив. <br>  <br><strong>5. Не насилуйте себя</strong><br> Когда вы покупаете месячный абонемент в фитнес центр, вы ведь понимаете, что вам не обязательно ходить в него каждый день? Более того, взяв слишком быстрый темп, вы можете забросить занятия не дойдя даже до конца месяца... В отношении практик данного интенсива действует то же правило - не жадничайте! Занимайтесь в удобном вам ритме - через день, через два... Конечно, хорошо заниматься каждый день, но ещё лучше - понимать свои долгосрочные задачи, и действовать соответственно. Скорее всего, ваши задачи выходят за рамки одного месяца, и вам необходимо регулярно действовать длительное время. Данный интенсив я задумал так, чтобы вы могли проходить его месяц за месяцем столько раз, сколько потребуется, пока поставленная вами цель не будет достигнута. Эта стратегия эффективней, чем один месяц втопить, а потом забросить практики или рвануть в другом направлении.<br>  <br><strong>6. Техника безопасности</strong><br> Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, которые я буду предлагать, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу контролировать ваше состояние. У вас могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.<br>  <br><strong>7. Ответы на вопросы</strong><br> Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.<br> <br>Желаю вам плодотворных практик!</p><p></p><p>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png\" alt=\"Интенсив «Наслаждения»\" width=\"504\" height=\"128\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!<br> <br>Я рад, что вы решились в течение месяца направить своё внимание и целенаправленно поработать над темой, объединяющей такие состояния, как: наслаждения, расслабленность, кайфушность, игривость, привлекательность, сексуальность... Вроде бы как это простые, доступные каждому состояния. Однако, в социуме действует множество как побудительных, так и запретительных сценариев, которые управляют нашим поведением. Выполняя практики на йоговском коврике и в жизни, размышляя, корректируя свои мысли и поступки, в течение месяца можно получить важные результаты, которые проявятся как на уровне тела (оздоравливание), так и на уровне психологического фона (удовлетворённость и счастье).</p><p></p><p></p><p> В течение этого месяца вы получите 30 практик, направленных на гармонизацию второй чакры. Внимательно прочитайте это письмо, чтобы понимать, что и как будет происходить. <br> <br><strong>1. Самая суть</strong><br> Это не учебный курс, а интенсивный практикум, ядром которого являются ежедневные практики йоги. Данные практики я проводил по утрам в прямом эфире, синхронизируя направление каждой практики с планетными ритмами в тот день. В этом интенсиве я собрал видеозаписи лучших практик, которые были направлены именно на первую чакру (иногда во взаимодействии с какой-нибудь ещё чакрой), дополнил их поведенческими (психологическими) практиками. В результате получился мощнейший заряд для гармонизации сферы здоровья. </p><p></p><p></p><p>Если вы не проходили моих курсов и не понимаете при чём здесь какая-то там «вторая чакра», я рекомендую вам совместить прохождение данного интенсива с практикумом или курсом, в котором я плавно подвожу к пониманию того, чем мы здесь занимаемся. Важно не просто «поверить» мне, а открыть в себе понимание через личный опыт - как на йоговском коврике, так и в жизни. Тогда практики начинают работать гораздо глубже. Иначе получаем физкультуру - так как это базовое понимание (опыт) йоги, которое есть у каждого. </p><p></p><p></p><p>Данный интенсив вы можете дополнить следующими учебными программами:<br> - Практикум «Месяц наслаждений»: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> </p><p></p><p>- Курс «Йога плюс женственность»: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a>  <br>  <br><strong>2. Практики йоги</strong><br> Практики йоги, которые вас ожидают, отличаются от того, что вы можете встретить в фитнес-центре. Я предполагаю, что вам важен результат, а не лицедейство. Мы работаем с внутренними состояниями (то есть с энергиями), соединяя медитацию, пранаяму и асаны в той мере, в которой это необходимо для получения желаемого результата на максимально глубоком уровне. Большинство практик начинаются с небольшого введения, которое необходимо, чтобы ваше сознание переключилось с обыденности на волну практики, вы вошли в соответствующий энергетический поток и активировалось ваше внутреннее намерение. Далее следует сама практика, которая в разные дни имеет разную длительность и состав элементов. После практики я рекомендую вам некоторое время побыть в медитации, а может быть в возникшем состоянии осознанности продолжить выполнять асаны, которые будет просить ваше тело. Средняя продолжительность практик 30-40 минут. Но некоторые практики короче, а некоторые длятся около часа. Важно, чтобы во время практики вас ничто не отвлекало и не торопило. И ещё очень важно - начав практику, не прерывайтесь до её окончания!!! Каждая практика - это живая история, которая проводит вас по определённому пути. Прервав практику, вы можете оказаться в менее ресурсном состоянии, чем были в её начале. Даже если сейчас эти слова вам кажутся мистификацией и пустой эзотерикой, прислушайтесь к моим рекомендациям. <br>  <br><strong>3. Поведенческие практики</strong><br> Каждый день в письме вместе с практикой йоги я буду присылать вам «совет дня». Попробуйте воспринимать его не как ещё одну умную мысль, подобную которой вы уже много раз слышали. У меня нет цели вас удивить, сказав то, что вы ещё не слышали. Воспринимайте этот «совет» как задание, как поведенческую практику! Выполняйте эту практику в данный день. И поверьте - вам станет гораздо интересней, и этот интенсив принесёт вам гораздо больше пользы. Некоторые такие практики могут казаться вам проще, некоторые сложнее. Некоторые прагматичнее, некоторые более психологическими. В любом случае, это не как если бы я предложил вам 20 раз присесть. Тут мы работаем с вашими поведенческими и психологическими шаблонами. И ключ к успеху в том, чтобы не сражаться с собой, не вызывать дополнительное внутреннее напряжение, а как в асанах - дышать и расслабляться. Поэтому практика звучит мягко - как &quot;совет дня&quot; - чтобы не вызывать сигнал тревоги. Прочитайте, примерьте, попробуйте в течение дня мягко следовать этому совету или хотя бы вспоминать его, вновь примеряя и возвращаясь в ощущение, что вы ему следуете. Адаптируйтесь к новым состояниям... В некоторых случаях одна такая практика может растянуться на несколько дней или даже месяцев, потому что вы ощутите её значимость, и начнёте внедрять её в свою жизнь на уровне привычки, то есть корректируя текущий гомеостаз системы. И, хотя я не закладывал чёткую связь между поведенческими практиками и практиками йоги, которые предлагаю в одном письме, тем не менее вы можете выполнять каждую практику йоги в состоянии, возникшем когда вы воспринимаете себя следующим моему совету. Однако, это вовсе не обязательно, так как каждая из этих двух практик самодостаточна.<br>  <br><strong>4. Расписание занятий</strong><br> Каждый день в полночь вам будет открываться новая практика (прошлая при этом будет исчезать, как прошлый день). Благодаря такому подходу, у вас не будет накапливаться снежный ком невыполненных практик. В течение суток вы можете выбрать любое удобное вам время, и позаниматься. Я рекомендую вам заниматься утром, чтобы в полученном в результате практики состоянии проживать день, а не спать лечь. Воспринимайте этот интенсив не как компьютерную иллюзию, а как реальную жизнь - в которой всё важное происходит СЕГОДНЯ, и практика йоги расширяется с коврика на пространство вашей проявленности в том мире, который вы воспринимаете, как наиболее реальный!</p><p></p><p></p><p>Кстати, есть небольшой нюанс с временем получения второй практики. Если вы записались до 18:00, то вторую практику вы получите в ближайшую полночь. Если же вы записались после 18:00, то вторую практику вы получите не в ближайшую, а в следующую полночь. То есть у вас будет запас времени на случай, если вы не успеете выполнить практику в день записи на интенсив. <br>  <br><strong>5. Не насилуйте себя</strong><br> Когда вы покупаете месячный абонемент в фитнес центр, вы ведь понимаете, что вам не обязательно ходить в него каждый день? Более того, взяв слишком быстрый темп, вы можете забросить занятия не дойдя даже до конца месяца... В отношении практик данного интенсива действует то же правило - не жадничайте! Занимайтесь в удобном вам ритме - через день, через два... Конечно, хорошо заниматься каждый день, но ещё лучше - понимать свои долгосрочные задачи, и действовать соответственно. Скорее всего, ваши задачи выходят за рамки одного месяца, и вам необходимо регулярно действовать длительное время. Данный интенсив я задумал так, чтобы вы могли проходить его месяц за месяцем столько раз, сколько потребуется, пока поставленная вами цель не будет достигнута. Эта стратегия эффективней, чем один месяц втопить, а потом забросить практики или рвануть в другом направлении.<br>  <br><strong>6. Техника безопасности</strong><br> Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, которые я буду предлагать, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу контролировать ваше состояние. У вас могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.<br>  <br><strong>7. Ответы на вопросы</strong><br> Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.<br> <br>Желаю вам плодотворных практик!</p><p></p><p>Сергей Замковой</p>","en":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png\" alt=\"Интенсив «Наслаждения»\" width=\"504\" height=\"128\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hello, {{name}}!<br> <br>I am glad that you decided to direct your attention for a month and purposefully work on the theme uniting such states as: pleasures, relaxation, blissfulness, playfulness, attractiveness, sexuality... They seem to be simple states accessible to everyone. However, in society there are many both motivating and prohibitive scenarios that control our behavior. By doing practices on the yoga mat and in life, reflecting, adjusting your thoughts and actions, over the course of a month you can get important results that will manifest both at the level of the body (healing) and at the level of the psychological background (satisfaction and happiness).</p><p></p><p></p><p> During this month you will receive 30 practices aimed at harmonizing the second chakra. Read this letter carefully to understand what and how everything will happen. <br> <br><strong>1. The very essence</strong><br> This is not a training course, but an intensive workshop, the core of which is daily yoga practices. I conducted these practices in the mornings in live broadcasts, synchronizing the direction of each practice with the planetary rhythms on that day. In this intensive I have gathered video recordings of the best practices that were aimed specifically at the first chakra (sometimes in interaction with some other chakra), and supplemented them with behavioral (psychological) practices. The result is a most powerful charge for harmonizing the sphere of health. </p><p></p><p></p><p>If you have not taken my courses and do not understand what some “second chakra” has to do with this, I recommend that you combine going through this intensive with a workshop or course in which I smoothly lead you to an understanding of what we are doing here. It is important not just to “believe” me, but to open understanding within yourself through personal experience—both on the yoga mat and in life. Then the practices begin to work much deeper. Otherwise we get physical exercise—since this is the basic understanding (experience) of yoga that everyone has. </p><p></p><p></p><p>You can supplement this intensive with the following educational programs:<br> - Workshop “A Month of Pleasures”: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> </p><p></p><p>- Course “Yoga Plus Femininity”: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a> <br>  <br><strong>2. Yoga practices</strong><br> The yoga practices that await you differ from what you may encounter in a fitness center. I assume that the result matters to you, not playacting. We work with inner states (that is, with energies), combining meditation, pranayama, and asanas to the extent necessary to obtain the desired result at the deepest possible level. Most practices begin with a short introduction, which is necessary so that your consciousness switches from everydayness to the wave of the practice, you enter the corresponding energy flow, and your inner intention becomes activated. Then comes the practice itself, which on different days has a different duration and composition of elements. After the practice, I recommend that you spend some time in meditation, or perhaps, in the arising state of awareness, continue to perform the asanas that your body will ask for. The average duration of the practices is 30-40 minutes. But some practices are shorter, and some last about an hour. It is important that during the practice nothing distracts you and nothing hurries you. And one more very important thing - having begun the practice, do not interrupt it until it ends!!! Each practice is a living story that takes you along a certain path. If you interrupt the practice, you may end up in a less resourceful state than you were in at its beginning. Even if right now these words seem to you like mystification and empty esotericism, heed my recommendations. <br>  <br><strong>3. Behavioral practices</strong><br> Every day in the email, together with the yoga practice, I will send you a “tip of the day.” Try to perceive it not as yet another clever thought, similar to which you have already heard many times. I have no goal of surprising you by saying something you have not yet heard. Perceive this “tip” as a task, as a behavioral practice! Perform this practice on the given day. And believe me - it will become much more interesting for you, and this intensive will bring you much more benefit. Some such practices may seem easier to you, some harder. Some more pragmatic, some more psychological. In any case, it is not as if I suggested that you do 20 squats. Here we work with your behavioral and psychological patterns. And the key to success is not to fight with yourself, not to create additional inner tension, but, as in asanas, to breathe and relax. That is why the practice sounds soft - like a “tip of the day” - so as not to trigger an alarm signal. Read it, try it on, try during the day to gently follow this tip or at least to remember it, again trying it on and returning to the feeling that you are following it. Adapt to new states... In some cases, one such practice may stretch over several days or even months, because you will feel its significance and begin to introduce it into your life at the level of a habit, that is, adjusting the current homeostasis of the system. And although I did not build in a clear connection between the behavioral practices and the yoga practices that I offer in one email, nevertheless you can perform each yoga practice in the state that arises when you perceive yourself as following my tip. However, this is not at all obligatory, since each of these two practices is self-sufficient.<br>  <br><strong>4. Class schedule</strong><br> Every day at midnight a new practice will open for you (the previous one will disappear, like the previous day). Thanks to this approach, uncompleted practices will not accumulate into a snowball. During the day you can choose any time convenient for you and practice. I recommend that you practice in the morning, so that you live the day in the state obtained as a result of the practice, rather than go to sleep. Perceive this intensive not as a computer illusion, but as real life - in which everything important happens TODAY, and the yoga practice expands from the mat into the space of your manifestation in that world which you perceive as the most real!</p><p></p><p></p><p>By the way, there is a small nuance with the time you receive the second practice. If you signed up before 18:00, then you will receive the second practice at the nearest midnight. If you signed up after 18:00, then you will receive the second practice not at the nearest midnight, but at the following midnight. That is, you will have a reserve of time in case you do not manage to complete the practice on the day you signed up for the intensive. <br>  <br><strong>5. Do not force yourself</strong><br> When you buy a monthly membership at a fitness center, you do understand that you do not have to go there every day, right? Moreover, by taking too fast a pace, you may abandon the classes before you even reach the end of the month... The same rule applies to the practices of this intensive - do not be greedy! Practice at a pace convenient for you - every other day, every two days... Of course, it is good to practice every day, but it is even better to understand your long-term tasks and act accordingly. Most likely, your tasks go beyond one month, and you need to act regularly for a long time. I conceived this intensive so that you could go through it month after month as many times as needed until the goal you have set is achieved. This strategy is more effective than going all out for one month and then abandoning the practices or rushing off in another direction.<br>  <br><strong>6. Safety precautions</strong><br> I care about your health and remind you that only you bear responsibility for the adequacy of performing the asanas, pranayamas, and meditations that I will offer to your physical capabilities and mental state. It is important to understand that these are online classes, and I cannot control your state. You may have physical and psychological particularities. Please be attentive to your state. If you feel that some asana that I suggest performing is premature for you, perform it not very deeply, at a compromise level, or replace it altogether with another asana - one that approximately also engages the body but is easier for you.<br>  <br><strong>7. Answers to questions</strong><br> Every week (usually on Saturdays) I hold group online consultations (webinars) in Zoom, at which we communicate, maintain motivation, and discuss difficulties and questions that arise. Before each such consultation, I will send you an email indicating the date and time of its holding, as well as a link to join it. What is interesting to you will surely also be interesting to many others. Therefore, discussing questions at group consultations is most effective. If it happens that the time of the consultation is inconvenient for you, in that case send your questions by email before it begins. I will answer them at the consultation, and I will send you a link to the recording so that you can watch it at a time convenient for you. Consultation recordings are kept for one week.<br> <br>I wish you fruitful practices!</p><p></p><p>Sergey Zamkovoy</p>","de":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png\" alt=\"Интенсив «Наслаждения»\" width=\"504\" height=\"128\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Guten Tag, {{name}}!<br> <br>Ich freue mich, dass Sie sich entschieden haben, einen Monat lang Ihre Aufmerksamkeit auf das Thema zu richten und gezielt an dem zu arbeiten, das Zustände wie folgende vereint: Genuss, Entspannung, Rauschhaftigkeit, Verspieltheit, Attraktivität, Sexualität... An sich sind das einfache, jedem zugängliche Zustände. Doch in der Gesellschaft wirken viele sowohl antreibende als auch verbietende Szenarien, die unser Verhalten steuern. Wenn Sie die Praktiken auf der Yogamatte und im Leben ausführen, nachdenken, Ihre Gedanken und Handlungen korrigieren, können Sie innerhalb eines Monats wichtige Ergebnisse erzielen, die sich sowohl auf der Ebene des Körpers (Gesundung) als auch auf der Ebene des psychologischen Hintergrunds (Zufriedenheit und Glück) zeigen.</p><p></p><p></p><p> In diesem Monat erhalten Sie 30 Praktiken, die auf die Harmonisierung des zweiten Chakras ausgerichtet sind. Lesen Sie diesen Brief sorgfältig, damit Sie verstehen, was und wie geschehen wird. <br> <br><strong>1. Das Wesentliche</strong><br> Das ist kein Lehrkurs, sondern ein intensives Praktikum, dessen Kern tägliche Yoga-Praktiken sind. Diese Praktiken habe ich morgens live durchgeführt und dabei die Ausrichtung jeder Praxis mit den planetaren Rhythmen jenes Tages synchronisiert. In diesem Intensivkurs habe ich Videoaufzeichnungen der besten Praktiken gesammelt, die genau auf das erste Chakra ausgerichtet waren (manchmal in Wechselwirkung mit einem anderen Chakra), und sie um verhaltensbezogene (psychologische) Praktiken ergänzt. Daraus ist eine äußerst kraftvolle Ladung für die Harmonisierung des Bereichs Gesundheit entstanden. </p><p></p><p></p><p>Wenn Sie meine Kurse nicht besucht haben und nicht verstehen, was es mit dieser „zweiten Chakra“ auf sich hat, empfehle ich Ihnen, den Besuch dieses Intensivkurses mit einem Praktikum oder Kurs zu kombinieren, in dem ich Sie behutsam zum Verständnis dessen hinführe, womit wir uns hier beschäftigen. Wichtig ist, nicht einfach mir zu „glauben“, sondern in sich selbst ein Verständnis durch persönliche Erfahrung zu eröffnen – sowohl auf der Yogamatte als auch im Leben. Dann beginnen die Praktiken viel tiefer zu wirken. Andernfalls bekommen wir bloß Gymnastik – denn das ist das grundlegende Verständnis (die Erfahrung) des Yoga, das jeder hat. </p><p></p><p></p><p>Diesen Intensivkurs können Sie mit folgenden Lernprogrammen ergänzen:<br> - Praktikum „Monat der Genüsse“: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> </p><p></p><p>- Kurs „Yoga plus Weiblichkeit“: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a>  <br>  <br><strong>2. Yoga-Praktiken</strong><br> Die Yoga-Praktiken, die Sie erwarten, unterscheiden sich von dem, was Sie in einem Fitnesscenter antreffen können. Ich gehe davon aus, dass Ihnen das Ergebnis wichtig ist und nicht die Schauspielerei. Wir arbeiten mit inneren Zuständen (das heißt mit Energien) und verbinden Meditation, Pranayama und Asanas in dem Maße, wie es nötig ist, um das gewünschte Ergebnis auf möglichst tiefer Ebene zu erzielen. Die meisten Praktiken beginnen mit einer kurzen Einführung, die notwendig ist, damit Ihr Bewusstsein von der Alltäglichkeit auf die Welle der Praxis umschaltet, Sie in den entsprechenden energetischen Fluss eintreten und Ihr inneres Vorhaben aktiviert wird. Danach folgt die eigentliche Praxis, die an verschiedenen Tagen eine unterschiedliche Dauer und Zusammensetzung der Elemente hat. Nach der Praxis empfehle ich Ihnen, einige Zeit in Meditation zu verweilen, und vielleicht im entstandenen Zustand der Achtsamkeit weiter Asanas auszuführen, die Ihr Körper erbitten wird. Die durchschnittliche Dauer der Praktiken beträgt 30-40 Minuten. Aber manche Praktiken sind kürzer, und manche dauern etwa eine Stunde. Wichtig ist, dass Sie während der Praxis nichts ablenkt und nichts zur Eile treibt. Und noch sehr wichtig – wenn Sie die Praxis begonnen haben, unterbrechen Sie sie nicht bis zu ihrem Ende!!! Jede Praxis ist eine lebendige Geschichte, die Sie einen bestimmten Weg entlangführt. Wenn Sie die Praxis unterbrechen, können Sie in einem weniger ressourcenreichen Zustand landen, als Sie zu Beginn waren. Auch wenn Ihnen diese Worte jetzt wie Mystifikation und leere Esoterik erscheinen mögen, hören Sie auf meine Empfehlungen. <br>  <br><strong>3. Verhaltenspraktiken</strong><br> Jeden Tag werde ich Ihnen im Brief zusammen mit der Yoga-Praxis einen „Tipp des Tages“ schicken. Versuchen Sie, ihn nicht als einen weiteren klugen Gedanken zu betrachten, von der Art, wie Sie sie schon viele Male gehört haben. Ich habe nicht das Ziel, Sie zu überraschen, indem ich etwas sage, das Sie noch nicht gehört haben. Betrachten Sie diesen „Tipp“ als Aufgabe, als Verhaltenspraxis! Führen Sie diese Praxis an diesem Tag aus. Und glauben Sie mir – es wird Ihnen viel interessanter werden, und dieser Intensivkurs wird Ihnen viel mehr Nutzen bringen. Manche solcher Praktiken mögen Ihnen einfacher erscheinen, manche schwieriger. Manche pragmatischer, manche psychologischer. In jedem Fall ist es nicht so, als hätte ich Ihnen vorgeschlagen, 20 Kniebeugen zu machen. Hier arbeiten wir mit Ihren Verhaltens- und psychologischen Mustern. Und der Schlüssel zum Erfolg liegt darin, nicht mit sich zu kämpfen, keine zusätzliche innere Spannung zu erzeugen, sondern wie in den Asanas zu atmen und sich zu entspannen. Deshalb klingt die Praxis sanft – wie ein „Tipp des Tages“ –, damit kein Alarmsignal ausgelöst wird. Lesen Sie ihn, probieren Sie ihn aus, versuchen Sie im Laufe des Tages, diesem Tipp sanft zu folgen oder ihn wenigstens in Erinnerung zu rufen, ihn erneut anzuprobieren und in das Gefühl zurückzukehren, dass Sie ihm folgen. Passen Sie sich an die neuen Zustände an... In manchen Fällen kann sich eine solche Praxis über mehrere Tage oder sogar Monate erstrecken, weil Sie ihre Bedeutung spüren und beginnen, sie auf der Ebene der Gewohnheit in Ihr Leben einzuführen, das heißt, die aktuelle Homöostase des Systems zu korrigieren. Und obwohl ich keine klare Verbindung zwischen den Verhaltenspraktiken und den Yoga-Praktiken, die ich in einem Brief anbiete, angelegt habe, können Sie dennoch jede Yoga-Praxis in dem Zustand ausführen, der entsteht, wenn Sie sich als jemanden wahrnehmen, der meinem Tipp folgt. Das ist jedoch keineswegs zwingend, da jede dieser beiden Praktiken für sich genügt.<br>  <br><strong>4. Zeitplan der Übungen</strong><br> Jeden Tag um Mitternacht wird Ihnen eine neue Praxis freigeschaltet (die vorherige verschwindet dabei, wie der vergangene Tag). Durch diesen Ansatz wird sich bei Ihnen kein Schneeball unerledigter Praktiken ansammeln. Innerhalb von 24 Stunden können Sie jede Ihnen passende Zeit wählen und praktizieren. Ich empfehle Ihnen, morgens zu praktizieren, um den Tag in dem durch die Praxis entstandenen Zustand zu erleben, statt sich schlafen zu legen. Betrachten Sie diesen Intensivkurs nicht als Computer-Illusion, sondern als reales Leben – in dem alles Wichtige HEUTE geschieht und sich die Yoga-Praxis von der Matte auf den Raum Ihrer Manifestation in der Welt ausdehnt, die Sie als die realste wahrnehmen!</p><p></p><p></p><p>Übrigens gibt es eine kleine Besonderheit mit dem Zeitpunkt, zu dem Sie die zweite Praxis erhalten. Wenn Sie sich vor 18:00 Uhr angemeldet haben, erhalten Sie die zweite Praxis in der nächsten Mitternacht. Wenn Sie sich jedoch nach 18:00 Uhr angemeldet haben, erhalten Sie die zweite Praxis nicht in der nächsten, sondern in der darauffolgenden Mitternacht. Das heißt, Sie haben einen Zeitpuffer für den Fall, dass Sie die Praxis am Tag der Anmeldung zum Intensivkurs nicht mehr schaffen. <br>  <br><strong>5. Zwingen Sie sich nicht</strong><br> Wenn Sie ein Monatsabo in einem Fitnesscenter kaufen, verstehen Sie doch, dass Sie nicht unbedingt jeden Tag hingehen müssen? Mehr noch: Wenn Sie ein zu schnelles Tempo anschlagen, können Sie die Übungen aufgeben, ohne sogar das Ende des Monats erreicht zu haben... Für die Praktiken dieses Intensivkurses gilt dieselbe Regel – seien Sie nicht gierig! Praktizieren Sie in einem Ihnen angenehmen Rhythmus – jeden zweiten Tag, jeden dritten... Natürlich ist es gut, jeden Tag zu praktizieren, aber noch besser ist es, seine langfristigen Aufgaben zu verstehen und entsprechend zu handeln. Höchstwahrscheinlich gehen Ihre Aufgaben über einen Monat hinaus, und Sie müssen über einen längeren Zeitraum regelmäßig handeln. Diesen Intensivkurs habe ich so konzipiert, dass Sie ihn Monat für Monat so oft durchlaufen können, wie es nötig ist, bis das von Ihnen gesetzte Ziel erreicht ist. Diese Strategie ist effektiver, als einen Monat lang Vollgas zu geben und dann die Praktiken aufzugeben oder in eine andere Richtung davonzustürmen.<br>  <br><strong>6. Sicherheitstechnik</strong><br> Ich kümmere mich um Ihre Gesundheit und erinnere daran, dass allein Sie die Verantwortung dafür tragen, dass die Ausführung der Asanas, Pranayamas und Meditationen, die ich anbieten werde, Ihren körperlichen Möglichkeiten und Ihrem psychischen Zustand angemessen ist. Wichtig zu verstehen ist, dass dies Online-Kurse sind und ich Ihren Zustand nicht kontrollieren kann. Bei Ihnen können körperliche und psychologische Besonderheiten vorliegen. Bitte seien Sie aufmerksam gegenüber Ihrem Zustand. Wenn Sie spüren, dass eine bestimmte Asana, die ich zur Ausführung anbiete, für Sie verfrüht ist, führen Sie sie nicht sehr tief aus, auf einem Kompromissniveau, oder ersetzen Sie sie ganz durch eine andere Asana – eine, die den Körper ungefähr ebenfalls einbezieht, aber für Sie einfacher ist.<br>  <br><strong>7. Antworten auf Fragen</strong><br> Jede Woche (normalerweise samstags) führe ich in Zoom Gruppen-Online-Konsultationen (Webinare) durch, in denen wir uns austauschen, die Motivation aufrechterhalten und auftretende Schwierigkeiten und Fragen besprechen. Vor jeder solchen Konsultation werde ich Ihnen eine E-Mail mit Angabe von Datum und Uhrzeit ihrer Durchführung sowie einem Link zum Beitreten schicken. Was für Sie interessant ist, wird sicherlich auch für viele andere interessant sein. Deshalb ist die Besprechung von Fragen in den Gruppenkonsultationen am effektivsten. Sollte es geschehen, dass die Zeit der Konsultation für Sie ungünstig ist, senden Sie in diesem Fall Ihre Fragen vor ihrem Beginn per E-Mail. Ich werde sie in der Konsultation beantworten und Ihnen einen Link zur Aufzeichnung schicken, damit Sie sie zu einer Ihnen passenden Zeit ansehen können. Die Aufzeichnungen der Konsultationen werden eine Woche lang gespeichert.<br> <br>Ich wünsche Ihnen fruchtbare Praktiken!</p><p></p><p>Sergei Zamkovoi</p>","fr":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png\" alt=\"Интенсив «Наслаждения»\" width=\"504\" height=\"128\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Bonjour, {{name}} !<br> <br>Je suis heureux que vous ayez décidé, pendant un mois, de diriger votre attention et de travailler de manière ciblée sur le thème qui réunit des états tels que : les plaisirs, la relaxation, le kiff, l’espièglerie, l’attractivité, la sexualité... En apparence, ce sont des états simples, accessibles à chacun. Cependant, dans la société agissent de nombreux scénarios, à la fois incitatifs et prohibitifs, qui gouvernent notre comportement. En pratiquant sur le tapis de yoga et dans la vie, en réfléchissant, en corrigeant vos pensées et vos actes, au cours d’un mois vous pouvez obtenir des résultats importants, qui se manifesteront tant au niveau du corps (guérison) qu’au niveau du fond psychologique (satisfaction et bonheur).</p><p></p><p></p><p> Au cours de ce mois, vous recevrez 30 pratiques visant à harmoniser le deuxième chakra. Lisez attentivement cette lettre afin de comprendre ce qui va se passer et comment. <br> <br><strong>1. L’essentiel</strong><br> Ce n’est pas un cours d’apprentissage, mais un atelier intensif dont le cœur est constitué de pratiques quotidiennes de yoga. J’ai mené ces pratiques le matin en direct, en synchronisant l’orientation de chaque pratique avec les rythmes planétaires de ce jour-là. Dans cet intensif, j’ai réuni des enregistrements vidéo des meilleures pratiques qui étaient précisément destinées au premier chakra (parfois en interaction avec un autre chakra), et je les ai complétées par des pratiques comportementales (psychologiques). Il en est résulté une charge extrêmement puissante pour harmoniser le domaine de la santé. </p><p></p><p></p><p>Si vous n’avez pas suivi mes cours et ne comprenez pas ce que vient faire ici une quelconque « deuxième chakra », je vous recommande de combiner ce parcours intensif avec le séminaire pratique ou le cours dans lequel je vous amène progressivement à comprendre ce que nous faisons ici. Il est important non pas simplement de « me croire », mais d’ouvrir en vous la compréhension par l’expérience personnelle — tant sur le tapis de yoga que dans la vie. Alors les pratiques commencent à agir beaucoup plus profondément. Sinon, nous obtenons de la culture physique — car c’est la compréhension (l’expérience) de base du yoga que chacun possède.</p><p></p><p></p><p>Vous pouvez compléter cet intensif avec les programmes d’apprentissage suivants :<br> - Atelier pratique « Un mois de plaisirs » : <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> </p><p></p><p>- Cours « Yoga plus féminité » : <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a>  <br>  <br><strong>2. Pratiques de yoga</strong><br> Les pratiques de yoga qui vous attendent diffèrent de ce que vous pouvez rencontrer dans un centre de fitness. Je suppose que le résultat vous importe, et non le jeu d’acteur. Nous travaillons avec les états intérieurs (c’est-à-dire avec les énergies), en unissant la méditation, le pranayama et les asanas dans la mesure nécessaire pour obtenir le résultat souhaité au niveau le plus profond possible. La plupart des pratiques commencent par une courte introduction, nécessaire pour que votre conscience passe du quotidien à la vague de la pratique, que vous entriez dans le flux énergétique correspondant et que votre intention intérieure s’active. Vient ensuite la pratique elle-même, qui selon les jours a une durée et une composition d’éléments différentes. Après la pratique, je vous recommande de rester quelque temps en méditation, et peut-être, dans l’état de conscience apparu, de continuer à exécuter les asanas que votre corps demandera. La durée moyenne des pratiques est de 30-40 minutes. Mais certaines pratiques sont plus courtes, et d’autres durent environ une heure. Il est important que pendant la pratique rien ne vous distraie ni ne vous presse. Et encore très important - une fois la pratique commencée, ne l’interrompez pas avant sa fin!!! Chaque pratique est une histoire vivante qui vous conduit sur un chemin déterminé. En interrompant la pratique, vous pouvez vous retrouver dans un état moins pourvu en ressources que celui dans lequel vous étiez au début. Même si maintenant ces mots vous semblent une mystification et de l’ésotérisme vide, écoutez mes recommandations. <br>  <br><strong>3. Pratiques comportementales</strong><br> Chaque jour, dans l’e-mail, avec la pratique de yoga, je vous enverrai un « conseil du jour ». Essayez de le percevoir non pas comme une pensée intelligente de plus, semblable à celles que vous avez déjà entendues bien des fois. Je n’ai pas pour but de vous surprendre en disant ce que vous n’avez encore jamais entendu. Percevez ce « conseil » comme une tâche, comme une pratique comportementale ! Accomplissez cette pratique ce jour-là. Et croyez-moi - cela vous paraîtra beaucoup plus intéressant, et cet intensif vous apportera beaucoup plus de bienfaits. Certaines de ces pratiques peuvent vous sembler plus simples, d’autres plus difficiles. Certaines plus pragmatiques, d’autres plus psychologiques. Dans tous les cas, ce n’est pas comme si je vous proposais de faire 20 squats. Ici, nous travaillons avec vos schémas comportementaux et psychologiques. Et la clé du succès est de ne pas lutter contre vous-même, de ne pas provoquer une tension intérieure supplémentaire, mais, comme dans les asanas, de respirer et de vous détendre. C’est pourquoi la pratique se présente doucement - comme un « conseil du jour » - afin de ne pas déclencher de signal d’alarme. Lisez-le, essayez-le, tentez pendant la journée de suivre doucement ce conseil ou du moins de vous en souvenir, en l’essayant à nouveau et en revenant à la sensation que vous le suivez. Adaptez-vous aux nouveaux états... Dans certains cas, une telle pratique peut s’étendre sur plusieurs jours ou même plusieurs mois, parce que vous en ressentirez l’importance et commencerez à l’intégrer dans votre vie au niveau de l’habitude, c’est-à-dire en corrigeant l’homéostasie actuelle du système. Et, bien que je n’aie pas établi de lien précis entre les pratiques comportementales et les pratiques de yoga que je propose dans un même e-mail, vous pouvez néanmoins accomplir chaque pratique de yoga dans l’état apparu lorsque vous vous percevez comme suivant mon conseil. Cependant, ce n’est pas du tout obligatoire, car chacune de ces deux pratiques est autosuffisante.<br>  <br><strong>4. Horaire des séances</strong><br> Chaque jour à minuit, une nouvelle pratique s’ouvrira pour vous (la précédente disparaîtra alors, comme le jour précédent). Grâce à cette approche, les pratiques non accomplies ne s’accumuleront pas en boule de neige. Pendant les vingt-quatre heures, vous pouvez choisir n’importe quel moment qui vous convient et pratiquer. Je vous recommande de pratiquer le matin, afin de vivre la journée dans l’état obtenu grâce à la pratique, et non d’aller vous coucher. Percevez cet intensif non pas comme une illusion informatique, mais comme la vie réelle - dans laquelle tout ce qui est important se produit AUJOURD’HUI, et la pratique du yoga s’étend du tapis à l’espace de votre manifestation dans ce monde que vous percevez comme le plus réel !</p><p></p><p></p><p>À propos, il y a une petite nuance concernant le moment où vous recevez la deuxième pratique. Si votre inscription a eu lieu avant 18:00, vous recevrez la deuxième pratique à la prochaine minuit. Si en revanche votre inscription a eu lieu après 18:00, vous recevrez la deuxième pratique non pas à la prochaine minuit, mais à la minuit suivante. Autrement dit, vous aurez une marge de temps au cas où vous n’auriez pas le temps d’accomplir la pratique le jour de l’inscription à l’intensif. <br>  <br><strong>5. Ne vous forcez pas</strong><br> Lorsque vous achetez un abonnement mensuel dans un centre de fitness, vous comprenez bien que vous n’êtes pas obligé d’y aller chaque jour ? De plus, en prenant un rythme trop rapide, vous risquez d’abandonner les séances avant même d’arriver à la fin du mois... En ce qui concerne les pratiques de cet intensif, la même règle s’applique - ne soyez pas gourmand ! Pratiquez à un rythme qui vous convient - tous les deux jours, tous les trois jours... Bien sûr, il est bon de pratiquer chaque jour, mais il est encore mieux de comprendre vos tâches à long terme et d’agir en conséquence. Très probablement, vos tâches dépassent le cadre d’un mois, et vous devez agir régulièrement pendant une longue période. J’ai conçu cet intensif de manière à ce que vous puissiez le suivre mois après mois autant de fois que nécessaire, jusqu’à ce que l’objectif que vous vous êtes fixé soit atteint. Cette stratégie est plus efficace que de se donner à fond pendant un mois, puis d’abandonner les pratiques ou de partir dans une autre direction.<br>  <br><strong>6. Consignes de sécurité</strong><br> Je me soucie de votre santé et je vous rappelle que c’est vous qui portez la responsabilité de l’adéquation de l’exécution des asanas, des pranayamas et des méditations que je proposerai à vos possibilités physiques et à votre état psychique. Il est important de comprendre qu’il s’agit de séances en ligne et que je ne peux pas contrôler votre état. Vous pouvez avoir des particularités physiques et psychologiques. Veuillez être attentif à votre état. Si vous sentez qu’une asana que je propose d’exécuter est prématurée pour vous, exécutez-la pas très profondément, à un niveau de compromis, ou remplacez-la entièrement par une autre asana - telle qui sollicite à peu près autant le corps, mais qui est plus simple pour vous.<br>  <br><strong>7. Réponses aux questions</strong><br> Chaque semaine (généralement le samedi), j’anime sur Zoom des consultations en ligne de groupe (webinaires), pendant lesquelles nous échangeons, maintenons la motivation, discutons des difficultés et des questions qui surviennent. Avant chacune de ces consultations, je vous enverrai un e-mail indiquant la date et l’heure de sa tenue, ainsi qu’un lien pour la rejoindre. Ce qui vous intéresse intéressera sûrement aussi beaucoup d’autres personnes. C’est pourquoi il est plus efficace de discuter des questions lors des consultations de groupe. S’il arrive que l’heure de la consultation ne vous convienne pas, dans ce cas envoyez vos questions par e-mail avant son début. Je répondrai à ces questions lors de la consultation, et je vous enverrai un lien vers l’enregistrement afin que vous puissiez le regarder au moment qui vous convient. Les enregistrements des consultations sont conservés pendant une semaine.<br> <br>Je vous souhaite des pratiques fructueuses !</p><p></p><p>Sergueï Zamkovoï</p>","it":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png\" alt=\"Интенсив «Наслаждения»\" width=\"504\" height=\"128\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Salve, {{name}}!<br> <br>Sono felice che vi siate decisi, nell’arco di un mese, a rivolgere la vostra attenzione e a lavorare intenzionalmente sul tema che unisce stati come: piacere, rilassatezza, goduria, giocosità, attrattività, sessualità... In apparenza sembrano stati semplici, accessibili a tutti. Tuttavia, nella società agiscono molti copioni, sia incentivanti sia inibitori, che governano il nostro comportamento. Svolgendo le pratiche sul tappetino yoga e nella vita, riflettendo, correggendo i propri pensieri e le proprie azioni, nell’arco di un mese si possono ottenere risultati importanti, che si manifesteranno sia a livello del corpo (risanamento), sia a livello dello sfondo psicologico (soddisfazione e felicità).</p><p></p><p></p><p> Nel corso di questo mese riceverete 30 pratiche volte ad armonizzare il secondo chakra. Leggete attentamente questa lettera per capire cosa e come accadrà. <br> <br><strong>1. L''essenza stessa</strong><br> Non è un corso didattico, ma un praticum intensivo, il cui nucleo sono le pratiche yoga quotidiane. Queste pratiche le ho condotte al mattino in diretta, sincronizzando la direzione di ogni pratica con i ritmi planetari di quel giorno. In questo intensivo ho raccolto le videoregistrazioni delle migliori pratiche, che erano dirette proprio al primo chakra (a volte in interazione con qualche altro chakra), e le ho integrate con pratiche comportamentali (psicologiche). Il risultato è stato una carica potentissima per l''armonizzazione dell''ambito della salute. </p><p></p><p></p><p>Se non avete seguito i miei corsi e non capite cosa c’entri qui un qualche «secondo chakra», vi consiglio di abbinare lo svolgimento di questo intensivo a un laboratorio pratico o a un corso in cui vi accompagno gradualmente alla comprensione di ciò di cui ci occupiamo qui. È importante non solo «credermi», ma aprire in voi la comprensione attraverso l’esperienza personale, sia sul tappetino yoga sia nella vita. Allora le pratiche iniziano a funzionare molto più in profondità. Altrimenti otteniamo educazione fisica, dal momento che questa è la comprensione (esperienza) di base dello yoga che ognuno possiede. </p><p></p><p></p><p>Questo intensivo potete integrarlo con i seguenti programmi di studio:<br> - Laboratorio pratico «Un mese di piaceri»: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> </p><p></p><p>- Corso «Yoga più femminilità»: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a>  <br>  <br><strong>2. Pratiche yoga</strong><br> Le pratiche yoga che vi attendono sono diverse da ciò che potete trovare in un centro fitness. Presumo che per voi conti il risultato, non la messa in scena. Lavoriamo con gli stati interiori (cioè con le energie), unendo meditazione, pranayama e asana nella misura necessaria per ottenere il risultato desiderato al livello più profondo possibile. La maggior parte delle pratiche inizia con una breve introduzione, necessaria affinché la vostra coscienza passi dalla quotidianità all''onda della pratica, entriate nel corrispondente flusso energetico e si attivi la vostra intenzione interiore. Segue poi la pratica stessa, che nei diversi giorni ha durata e composizione di elementi diverse. Dopo la pratica vi raccomando di restare per un po'' in meditazione, e magari, nello stato di consapevolezza che è emerso, di continuare a eseguire le asana che il vostro corpo chiederà. La durata media delle pratiche è di 30-40 minuti. Ma alcune pratiche sono più brevi, e alcune durano circa un''ora. È importante che durante la pratica nulla vi distragga e vi metta fretta. E ancora molto importante - una volta iniziata la pratica, non interrompetela prima della fine!!! Ogni pratica è una storia viva, che vi conduce lungo un determinato percorso. Interrompendo la pratica, potete ritrovarvi in uno stato meno ricco di risorse di quello in cui eravate all''inizio. Anche se ora queste parole vi sembrano una mistificazione e vuoto esoterismo, ascoltate le mie raccomandazioni. <br>  <br><strong>3. Pratiche comportamentali</strong><br> Ogni giorno, nella lettera insieme alla pratica yoga, vi invierò il «consiglio del giorno». Provate a percepirlo non come un altro pensiero intelligente, simile al quale ne avete già sentiti molti. Non ho l''obiettivo di sorprendervi dicendo qualcosa che non avete ancora sentito. Percepite questo «consiglio» come un compito, come una pratica comportamentale! Eseguite questa pratica nel giorno dato. E credetemi - vi risulterà molto più interessante, e questo intensivo vi porterà molto più beneficio. Alcune di queste pratiche possono sembrarvi più semplici, alcune più difficili. Alcune più pragmatiche, alcune più psicologiche. In ogni caso, non è come se vi avessi proposto di fare 20 squat. Qui lavoriamo con i vostri schemi comportamentali e psicologici. E la chiave del successo sta nel non combattere con voi stessi, nel non provocare ulteriore tensione interiore, ma, come nelle asana, respirare e rilassarvi. Perciò la pratica suona morbida - come «consiglio del giorno» - per non attivare un segnale d''allarme. Leggete, provate su di voi, provate durante la giornata a seguire dolcemente questo consiglio o almeno a ricordarlo, provandolo di nuovo e tornando alla sensazione che lo state seguendo. Adattatevi ai nuovi stati... In alcuni casi una sola pratica del genere può protrarsi per diversi giorni o addirittura mesi, perché ne sentirete l''importanza e inizierete a introdurla nella vostra vita a livello di abitudine, cioè correggendo l''attuale omeostasi del sistema. E, sebbene io non abbia previsto un legame preciso tra le pratiche comportamentali e le pratiche yoga che propongo in una stessa lettera, potete comunque eseguire ogni pratica yoga nello stato che emerge quando percepite voi stessi come seguaci del mio consiglio. Tuttavia, questo non è affatto obbligatorio, poiché ciascuna di queste due pratiche è autosufficiente.<br>  <br><strong>4. Orario delle lezioni</strong><br> Ogni giorno a mezzanotte vi si aprirà una nuova pratica (quella precedente scomparirà, come il giorno passato). Grazie a questo approccio, non si accumulerà una palla di neve di pratiche non eseguite. Nell''arco delle ventiquattro ore potete scegliere qualsiasi momento conveniente per voi e fare pratica. Vi raccomando di praticare al mattino, per vivere la giornata nello stato ottenuto grazie alla pratica, e non andare a dormire. Percepite questo intensivo non come un''illusione informatica, ma come vita reale - in cui tutto ciò che è importante accade OGGI, e la pratica yoga si espande dal tappetino allo spazio della vostra manifestazione in quel mondo che percepite come il più reale!</p><p></p><p></p><p>A proposito, c''è una piccola sfumatura riguardo al momento in cui riceverete la seconda pratica. Se vi siete iscritti prima delle 18:00, riceverete la seconda pratica alla mezzanotte più vicina. Se invece vi siete iscritti dopo le 18:00, riceverete la seconda pratica non alla mezzanotte più vicina, ma a quella successiva. Cioè avrete un margine di tempo nel caso non riusciate a completare la pratica nel giorno dell''iscrizione all''intensivo. <br>  <br><strong>5. Non fatevi violenza</strong><br> Quando acquistate un abbonamento mensile in un centro fitness, capite bene che non dovete per forza andarci ogni giorno? Inoltre, prendendo un ritmo troppo veloce, potete abbandonare le lezioni senza nemmeno arrivare alla fine del mese... Riguardo alle pratiche di questo intensivo vale la stessa regola - non siate avidi! Praticate al ritmo che vi è comodo - a giorni alterni, ogni due... Certo, è bene praticare ogni giorno, ma ancora meglio è capire i propri compiti a lungo termine e agire di conseguenza. Molto probabilmente i vostri compiti vanno oltre un mese, e avete bisogno di agire regolarmente per lungo tempo. Ho concepito questo intensivo in modo che possiate seguirlo mese dopo mese tutte le volte che serve, finché l''obiettivo che vi siete posti non sarà raggiunto. Questa strategia è più efficace che darci dentro per un mese e poi abbandonare le pratiche o lanciarsi in un''altra direzione.<br>  <br><strong>6. Tecnica di sicurezza</strong><br> Mi prendo cura della vostra salute e vi ricordo che solo voi siete responsabili dell''adeguatezza dell''esecuzione delle asana, dei pranayama e delle meditazioni che vi proporrò rispetto alle vostre possibilità fisiche e al vostro stato psichico. È importante capire che queste sono lezioni online e io non posso controllare il vostro stato. Potete avere particolarità fisiche e psicologiche. Per favore, siate attenti al vostro stato. Se sentite che qualche asana che vi propongo di eseguire è per voi prematura, eseguitela non molto profondamente, a un livello di compromesso, oppure sostituitela del tutto con un''altra asana - tale che coinvolga approssimativamente allo stesso modo il corpo, ma sia più semplice per voi.<br>  <br><strong>7. Risposte alle domande</strong><br> Ogni settimana (di solito il sabato) tengo su Zoom consultazioni online di gruppo (webinar), durante le quali comunichiamo, sosteniamo la motivazione, discutiamo le difficoltà e le domande che emergono. Prima di ciascuna di queste consultazioni vi invierò un''email con l''indicazione della data e dell''ora in cui si svolgerà, nonché il link per parteciparvi. Ciò che interessa a voi sarà sicuramente interessante anche per molti altri. Perciò, discutere le domande durante le consultazioni di gruppo è più efficace. Se accadesse che l''orario della consultazione non vi sia comodo, in questo caso inviate le vostre domande via email prima del suo inizio. Risponderò loro durante la consultazione, e vi invierò il link alla registrazione, così potrete guardarla nel momento per voi più comodo. Le registrazioni delle consultazioni vengono conservate per una settimana.<br> <br>Vi auguro pratiche fruttuose!</p><p></p><p>Sergej Zamkovoj</p>","es":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png\" alt=\"Интенсив «Наслаждения»\" width=\"504\" height=\"128\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hola, {{name}}!<br> <br>Me alegra que se haya decidido, durante un mes, a dirigir su atención y a trabajar de forma intencionada en el tema que une estados como: los placeres, la relajación, el gustazo, la juguetividad, el atractivo, la sexualidad… Parecería que son estados simples, accesibles para cualquiera. Sin embargo, en la sociedad operan muchos guiones, tanto incentivadores como prohibitivos, que gobiernan nuestra conducta. Realizando prácticas en la esterilla de yoga y en la vida, reflexionando, corrigiendo sus pensamientos y actos, a lo largo de un mes se pueden obtener resultados importantes que se manifestarán tanto a nivel del cuerpo (sanación) como a nivel del fondo psicológico (satisfacción y felicidad).</p><p></p><p></p><p> Durante este mes usted recibirá 30 prácticas dirigidas a armonizar la segunda chakra. Lea atentamente esta carta para entender qué y cómo sucederá. <br> <br><strong>1. La esencia misma</strong><br> Esto no es un curso de formación, sino un taller intensivo cuyo núcleo son las prácticas diarias de yoga. Estas prácticas las realizaba por las mañanas en directo, sincronizando la dirección de cada práctica con los ritmos planetarios de ese día. En este intensivo he reunido grabaciones de vídeo de las mejores prácticas, que estaban dirigidas precisamente al primer chakra (a veces en interacción con algún otro chakra), y las he complementado con prácticas conductuales (psicológicas). Como resultado, se ha obtenido una carga poderosísima para armonizar el ámbito de la salud. </p><p></p><p></p><p>Si usted no ha tomado mis cursos y no entiende qué tiene que ver aquí esa tal «segunda chakra», le recomiendo combinar la realización de este intensivo con un taller práctico o un curso en el que poco a poco voy conduciendo a la comprensión de aquello de lo que nos ocupamos aquí. Es importante no solo «creerme», sino abrir en usted la comprensión a través de la experiencia personal —tanto en la esterilla de yoga como en la vida—. Entonces las prácticas empiezan a funcionar mucho más profundamente. De lo contrario, obtenemos gimnasia, ya que esta es la comprensión (experiencia) básica del yoga que tiene cada persona. </p><p></p><p></p><p>Puede complementar este intensivo con los siguientes programas de estudio:<br> - Taller práctico «Mes de los placeres»: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> </p><p></p><p>- Curso «Yoga más feminidad»: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a>  <br>  <br><strong>2. Prácticas de yoga</strong><br> Las prácticas de yoga que le esperan se diferencian de lo que puede encontrar en un centro de fitness. Supongo que para usted es importante el resultado, y no el teatro. Trabajamos con estados internos (es decir, con energías), uniendo meditación, pranayama y asanas en la medida necesaria para obtener el resultado deseado al nivel más profundo posible. La mayoría de las prácticas comienzan con una breve introducción, necesaria para que su conciencia cambie de lo cotidiano a la onda de la práctica, entre en el flujo energético correspondiente y se active su intención interna. Después sigue la práctica en sí, que en distintos días tiene distinta duración y composición de elementos. Después de la práctica, le recomiendo permanecer un tiempo en meditación y, tal vez, en el estado de conciencia que haya surgido, continuar realizando las asanas que su cuerpo le pida. La duración media de las prácticas es de 30-40 minutos. Pero algunas prácticas son más cortas y otras duran cerca de una hora. Es importante que durante la práctica nada le distraiga ni le apresure. Y además es muy importante: una vez comenzada la práctica, ¡no la interrumpa hasta que termine!!! Cada práctica es una historia viva que le conduce por un camino determinado. Si interrumpe la práctica, puede encontrarse en un estado con menos recursos que aquel en el que estaba al comenzarla. Aunque ahora estas palabras le parezcan una mistificación y esoterismo vacío, haga caso a mis recomendaciones. <br>  <br><strong>3. Prácticas conductuales</strong><br> Cada día, en la carta, junto con la práctica de yoga, le enviaré el «consejo del día». Intente percibirlo no como una idea inteligente más, de las cuales ya ha oído muchas. No tengo el objetivo de sorprenderle diciendo algo que aún no haya oído. Perciba este «consejo» como una tarea, ¡como una práctica conductual! Realice esta práctica en el día indicado. Y créame: se sentirá mucho más interesado, y este intensivo le aportará mucho más beneficio. Algunas de estas prácticas pueden parecerle más fáciles, otras más difíciles. Algunas más pragmáticas, otras más psicológicas. En cualquier caso, no es como si le propusiera hacer 20 sentadillas. Aquí trabajamos con sus patrones conductuales y psicológicos. Y la clave del éxito está en no luchar contra uno mismo, no generar una tensión interna adicional, sino, como en las asanas, respirar y relajarse. Por eso la práctica suena suave, como «consejo del día», para no activar una señal de alarma. Léalo, pruébeselo, intente durante el día seguir suavemente este consejo o al menos recordarlo, probándoselo de nuevo y regresando a la sensación de que lo sigue. Adáptese a los nuevos estados... En algunos casos, una sola práctica así puede extenderse durante varios días o incluso meses, porque sentirá su importancia y comenzará a incorporarla a su vida a nivel de hábito, es decir, corrigiendo la homeostasis actual del sistema. Y, aunque no establecí una conexión clara entre las prácticas conductuales y las prácticas de yoga que propongo en una misma carta, aun así puede realizar cada práctica de yoga en el estado que surja cuando se percibe a sí mismo siguiendo mi consejo. Sin embargo, esto no es en absoluto obligatorio, ya que cada una de estas dos prácticas es autosuficiente.<br>  <br><strong>4. Horario de las clases</strong><br> Cada día, a medianoche, se le abrirá una nueva práctica (la anterior desaparecerá, como el día anterior). Gracias a este enfoque, no se le irá acumulando una bola de nieve de prácticas sin hacer. A lo largo del día puede elegir el momento que más le convenga y practicar. Le recomiendo practicar por la mañana, para vivir el día en el estado obtenido como resultado de la práctica, y no irse a dormir. Perciba este intensivo no como una ilusión informática, sino como la vida real, en la que todo lo importante ocurre HOY, y la práctica de yoga se expande desde la esterilla al espacio de su manifestación en el mundo que usted percibe como el más real.</p><p></p><p></p><p>Por cierto, hay un pequeño matiz con la hora de recepción de la segunda práctica. Si se inscribió antes de las 18:00, recibirá la segunda práctica en la próxima medianoche. Si se inscribió después de las 18:00, recibirá la segunda práctica no en la próxima medianoche, sino en la siguiente. Es decir, tendrá un margen de tiempo por si no logra realizar la práctica el día de la inscripción al intensivo. <br>  <br><strong>5. No se fuerce</strong><br> Cuando compra un abono mensual en un centro de fitness, entiende que no es obligatorio ir todos los días, ¿verdad? Además, si adopta un ritmo demasiado rápido, puede abandonar las clases sin haber llegado ni siquiera a fin de mes... Con las prácticas de este intensivo rige la misma regla: ¡no sea codicioso! Practique a un ritmo que le resulte cómodo: un día sí y otro no, cada dos días... Claro que es bueno practicar todos los días, pero aún mejor es comprender sus objetivos a largo plazo y actuar en consecuencia. Lo más probable es que sus objetivos vayan más allá de un mes, y necesite actuar con regularidad durante un tiempo prolongado. Concebí este intensivo para que pueda recorrerlo mes tras mes tantas veces como sea necesario, hasta que se alcance el objetivo que se ha propuesto. Esta estrategia es más eficaz que entregarse a tope durante un mes y luego abandonar las prácticas o lanzarse en otra dirección.<br>  <br><strong>6. Técnica de seguridad</strong><br> Me preocupo por su salud y le recuerdo que solo usted es responsable de la adecuación de la ejecución de las asanas, pranayamas y meditaciones que le propondré a sus posibilidades físicas y a su estado psíquico. Es importante comprender que son clases en línea, y no puedo controlar su estado. Usted puede tener particularidades físicas y psicológicas. Por favor, sea atento a su estado. Si siente que alguna asana que le propongo realizar es prematura para usted, ejecútela no muy profundamente, en un nivel de compromiso, o sustitúyala por completo por otra asana, una que incluya el cuerpo aproximadamente de la misma manera pero que le resulte más sencilla.<br>  <br><strong>7. Respuestas a las preguntas</strong><br> Cada semana (normalmente los sábados) realizo en Zoom consultas grupales en línea (webinars), en las que conversamos, mantenemos la motivación y discutimos las dificultades y preguntas que surgen. Antes de cada una de estas consultas le enviaré una carta con la fecha y la hora de su realización, así como un enlace para unirse a ella. Lo que es interesante para usted seguramente también lo será para muchas otras personas. Por eso, la discusión de preguntas en las consultas grupales es lo más eficaz. Si ocurre que la hora de la consulta le resulta inconveniente, en ese caso envíe sus preguntas por correo electrónico antes de su comienzo. Las responderé en la consulta y le enviaré un enlace a la grabación para que pueda verla en el momento que le resulte cómodo. Las grabaciones de las consultas se conservan durante una semana.<br> <br>¡Le deseo prácticas fructíferas!</p><p></p><p>Serguéi Zamkovói</p>","pt":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png\" alt=\"Интенсив «Наслаждения»\" width=\"504\" height=\"128\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Olá, {{name}}!<br> <br>Fico feliz que você tenha decidido, ao longo de um mês, direcionar sua atenção e trabalhar intencionalmente o tema que reúne estados como: prazeres, relaxamento, gostosura, ludicidade, atratividade, sexualidade... Parecem ser estados simples, acessíveis a qualquer pessoa. No entanto, na sociedade atuam muitos roteiros tanto incentivadores quanto proibitivos, que governam nosso comportamento. Praticando no tapete de yoga e na vida, refletindo, corrigindo seus pensamentos e atitudes, ao longo de um mês é possível obter resultados importantes, que se manifestarão tanto no nível do corpo (melhora da saúde) quanto no nível do fundo psicológico (satisfação e felicidade).</p><p></p><p></p><p> Ao longo deste mês você receberá 30 práticas voltadas para a harmonização do segundo chakra. Leia esta carta com atenção para entender o que e como vai acontecer. <br> <br><strong>1. A própria essência</strong><br> Este não é um curso de estudo, mas um praticum intensivo, cujo núcleo são as práticas diárias de yoga. Eu conduzia essas práticas pela manhã ao vivo, sincronizando a direção de cada prática com os ritmos planetários daquele dia. Neste intensivo, reuni gravações em vídeo das melhores práticas que eram direcionadas justamente ao primeiro chakra (às vezes em interação com algum outro chakra), e as complementei com práticas comportamentais (psicológicas). O resultado foi uma carga poderosíssima para harmonizar a esfera da saúde. </p><p></p><p></p><p>Se você não fez meus cursos e não entende o que tem a ver com isso algum «segundo chakra», eu recomendo combinar a realização deste intensivo com um workshop ou curso no qual eu conduzo suavemente à compreensão do que estamos fazendo aqui. É importante não apenas «acreditar» em mim, mas despertar em si a compreensão por meio da experiência pessoal - tanto no tapete de yoga quanto na vida. Então as práticas começam a funcionar muito mais profundamente. Caso contrário, obtemos ginástica - já que essa é a compreensão (experiência) básica do yoga que todos têm. </p><p></p><p></p><p>Você pode complementar este intensivo com os seguintes programas de estudo:<br> - Workshop «Mês dos prazeres»: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> </p><p></p><p>- Curso «Yoga mais feminilidade»: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a>  <br>  <br><strong>2. Práticas de yoga</strong><br> As práticas de yoga que você terá pela frente diferem daquilo que você pode encontrar em uma academia de ginástica. Presumo que para você o resultado é importante, e não a teatralidade. Trabalhamos com estados internos (ou seja, com energias), unindo meditação, pranayama e asanas na medida necessária para obter o resultado desejado no nível mais profundo possível. A maioria das práticas começa com uma pequena introdução, necessária para que sua consciência se desligue da cotidianidade e entre na onda da prática, você entre no fluxo energético correspondente e sua intenção interna se ative. Em seguida vem a própria prática, que em dias diferentes tem duração e composição de elementos diferentes. Depois da prática, recomendo que você fique algum tempo em meditação e, talvez, no estado de consciência que surgir, continue executando as asanas que seu corpo pedir. A duração média das práticas é de 30 a 40 minutos. Mas algumas práticas são mais curtas, e algumas duram cerca de uma hora. É importante que durante a prática nada o distraia nem o apresse. E é ainda muito importante - tendo começado a prática, não a interrompa até o final!!! Cada prática é uma história viva que o conduz por um determinado caminho. Se interromper a prática, você pode acabar em um estado com menos recursos do que aquele em que estava no início dela. Mesmo que agora estas palavras lhe pareçam mistificação e esoterismo vazio, escute minhas recomendações. <br>  <br><strong>3. Práticas comportamentais</strong><br> Todos os dias, no e-mail, junto com a prática de yoga, enviarei a você o «conselho do dia». Tente não percebê-lo como mais um pensamento inteligente, semelhante aos que você já ouviu muitas vezes. Não tenho o objetivo de surpreendê-lo dizendo algo que você ainda não ouviu. Perceba esse «conselho» como uma tarefa, como uma prática comportamental! Execute essa prática no dia em questão. E acredite - vai se tornar muito mais interessante para você, e este intensivo lhe trará muito mais benefício. Algumas dessas práticas podem parecer-lhe mais simples, outras mais difíceis. Algumas mais pragmáticas, outras mais psicológicas. Em qualquer caso, não é como se eu tivesse proposto a você agachar 20 vezes. Aqui trabalhamos com seus padrões comportamentais e psicológicos. E a chave do sucesso está em não lutar consigo mesmo, não provocar tensão interna adicional, mas, como nas asanas, respirar e relaxar. Por isso a prática soa suave - como «conselho do dia» - para não provocar o sinal de alarme. Leia, experimente, tente ao longo do dia seguir suavemente esse conselho ou ao menos lembrar dele, experimentando-o de novo e retornando à sensação de que o está seguindo. Adapte-se aos novos estados... Em alguns casos, uma dessas práticas pode se estender por vários dias ou até meses, porque você sentirá sua importância e começará a introduzi-la em sua vida no nível do hábito, ou seja, corrigindo a homeostase atual do sistema. E, embora eu não tenha estabelecido uma ligação clara entre as práticas comportamentais e as práticas de yoga que proponho em um mesmo e-mail, ainda assim você pode executar cada prática de yoga no estado que surgir quando você se percebe seguindo meu conselho. No entanto, isso não é de modo algum obrigatório, pois cada uma dessas duas práticas é autossuficiente.<br>  <br><strong>4. Horário das aulas</strong><br> Todos os dias, à meia-noite, uma nova prática será aberta para você (a anterior desaparecerá, como o dia anterior). Graças a essa abordagem, não se acumulará em você uma bola de neve de práticas não realizadas. Ao longo do dia, você pode escolher o horário que lhe for conveniente e praticar. Recomendo que você pratique pela manhã, para viver o dia no estado obtido como resultado da prática, e não para ir dormir. Perceba este intensivo não como uma ilusão de computador, mas como a vida real - na qual tudo o que é importante acontece HOJE, e a prática de yoga se expande do tapete para o espaço da sua manifestação naquele mundo que você percebe como o mais real!</p><p></p><p></p><p>A propósito, há um pequeno detalhe com o horário de recebimento da segunda prática. Se você se inscreveu antes das 18:00, receberá a segunda prática na próxima meia-noite. Mas se se inscreveu depois das 18:00, receberá a segunda prática não na próxima meia-noite, mas na meia-noite seguinte. Ou seja, você terá uma reserva de tempo caso não consiga realizar a prática no dia da inscrição no intensivo. <br>  <br><strong>5. Não se force</strong><br> Quando você compra uma mensalidade em uma academia, você entende que não precisa ir lá todos os dias, certo? Mais do que isso, se pegar um ritmo rápido demais, você pode abandonar os treinos antes mesmo do fim do mês... Em relação às práticas deste intensivo, vale a mesma regra - não seja ganancioso! Pratique no ritmo que lhe for conveniente - um dia sim, dois não... Claro, é bom praticar todos os dias, mas ainda melhor é entender suas tarefas de longo prazo e agir de acordo. Muito provavelmente, suas tarefas vão além de um mês, e você precisa agir regularmente por um longo tempo. Concebi este intensivo de modo que você possa percorrê-lo mês após mês, quantas vezes for necessário, até que o objetivo que você estabeleceu seja alcançado. Essa estratégia é mais eficaz do que se entregar a fundo por um mês e depois abandonar as práticas ou partir para outra direção.<br>  <br><strong>6. Técnica de segurança</strong><br> Eu me preocupo com sua saúde e lembro que somente você é responsável pela adequação da execução das asanas, pranayamas e meditações que eu proporei às suas possibilidades físicas e ao seu estado psíquico. É importante entender que estas são aulas on-line, e eu não posso controlar seu estado. Você pode ter particularidades físicas e psicológicas. Por favor, esteja atento ao seu estado. Se você sentir que alguma asana que proponho executar é prematura para você, execute-a não muito profundamente, em um nível de meio-termo, ou substitua-a totalmente por outra asana - que envolva o corpo de modo aproximadamente semelhante, mas seja mais simples para você.<br>  <br><strong>7. Respostas às perguntas</strong><br> Toda semana (normalmente aos sábados) realizo no Zoom consultorias on-line em grupo (webinars), nas quais conversamos, mantemos a motivação, discutimos as dificuldades e dúvidas que surgem. Antes de cada consultoria dessas, enviarei a você um e-mail com a data e o horário de sua realização, bem como o link para se juntar a ela. O que é interessante para você certamente também será interessante para muitas outras pessoas. Por isso, discutir as questões nas consultorias em grupo é o mais eficaz. Se acontecer de o horário da consultoria ser inconveniente para você, nesse caso envie suas perguntas por e-mail antes de ela começar. Eu responderei a elas na consultoria e enviarei a você o link da gravação, para que possa assisti-la no horário que lhe for conveniente. As gravações das consultorias ficam salvas por uma semana.<br> <br>Desejo a você práticas frutíferas!</p><p></p><p>Sergei Zamkovoi</p>","nl":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png\" alt=\"Интенсив «Наслаждения»\" width=\"504\" height=\"128\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hallo, {{name}}!<br> <br>Ik ben blij dat je besloten hebt om een maand lang je aandacht te richten en gericht te werken aan het thema dat staten verenigt als: genietingen, ontspanning, heerlijkheid, speelsheid, aantrekkelijkheid, seksualiteit... Het lijken misschien eenvoudige, voor iedereen toegankelijke toestanden. In de samenleving werken echter veel zowel stimulerende als verbiedende scenario''s die ons gedrag sturen. Door praktijken op de yogamat en in het leven uit te voeren, na te denken en je gedachten en daden bij te sturen, kun je in een maand belangrijke resultaten behalen, die zich zowel op lichaamsniveau (gezond worden) als op het niveau van de psychologische gesteldheid (tevredenheid en geluk) manifesteren.</p><p></p><p></p><p> Deze maand ontvang je 30 praktijken gericht op het harmoniseren van de tweede chakra. Lees deze e-mail aandachtig, zodat je begrijpt wat er gaat gebeuren en hoe. <br> <br><strong>1. De kern</strong><br> Dit is geen leercursus, maar een intensieve praktijk, waarvan de dagelijkse yogapraktijken de kern vormen. Deze praktijken gaf ik ''s ochtends live, waarbij ik de richting van elke praktijk afstemde op de planetaire ritmen van die dag. In dit intensief heb ik video-opnamen verzameld van de beste praktijken die juist op de eerste chakra waren gericht (soms in wisselwerking met een andere chakra), en deze aangevuld met gedragsmatige (psychologische) praktijken. Het resultaat is een uiterst krachtige impuls voor het harmoniseren van het gebied van gezondheid. </p><p></p><p></p><p>Als je mijn cursussen niet hebt gevolgd en niet begrijpt wat een of andere «tweede chakra» hier mee te maken heeft, raad ik je aan dit intensief te combineren met een practicum of cursus waarin ik je geleidelijk tot begrip breng van wat we hier doen. Het is belangrijk om mij niet alleen maar «te geloven», maar in jezelf begrip te openen via persoonlijke ervaring - zowel op de yogamat als in het leven. Dan gaan de praktijken veel dieper werken. Anders krijgen we gymnastiek - omdat dit het basisbegrip (de ervaring) van yoga is die iedereen heeft. </p><p></p><p></p><p>Je kunt dit intensief aanvullen met de volgende studieprogramma''s:<br> - Practicum «Maand van genietingen»: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> </p><p></p><p>- Cursus «Yoga plus vrouwelijkheid»: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a>  <br>  <br><strong>2. Yogapraktijken</strong><br> Yogapraktijken die u te wachten staan, verschillen van wat u in een fitnesscentrum kunt tegenkomen. Ik ga ervan uit dat het u om het resultaat gaat, en niet om toneelspel. We werken met innerlijke toestanden (dat wil zeggen met energieën), waarbij ik meditatie, pranayama en asana''s verbind voor zover dat nodig is om het gewenste resultaat op een zo diep mogelijk niveau te bereiken. De meeste praktijken beginnen met een korte inleiding, die nodig is opdat uw bewustzijn van de alledaagsheid overschakelt naar de golf van de praktijk, u in de bijbehorende energetische stroom komt en uw innerlijke intentie wordt geactiveerd. Daarna volgt de praktijk zelf, die op verschillende dagen een verschillende duur en samenstelling van elementen heeft. Na de praktijk raad ik u aan enige tijd in meditatie te blijven, of misschien in de ontstane staat van bewustzijn door te gaan met het uitvoeren van de asana''s die uw lichaam zal vragen. De gemiddelde duur van de praktijken is 30-40 minuten. Maar sommige praktijken zijn korter, en sommige duren ongeveer een uur. Het is belangrijk dat niets u tijdens de praktijk afleidt en dat niets u opjaagt. En heel belangrijk: als u eenmaal aan de praktijk bent begonnen, onderbreek deze dan niet tot het einde!!! Elke praktijk is een levend verhaal dat u langs een bepaald pad leidt. Als u de praktijk onderbreekt, kunt u in een minder veerkrachtige toestand terechtkomen dan aan het begin ervan. Zelfs als deze woorden u nu als mystificatie en lege esoterie voorkomen, luister naar mijn aanbevelingen. <br>  <br><strong>3. Gedragspraktijken</strong><br> Elke dag zal ik u in de brief samen met de yogapraktijk een «advies van de dag» sturen. Probeer het niet te zien als nog een slimme gedachte, waarvan u er al vele malen soortgelijke hebt gehoord. Het is niet mijn doel u te verrassen door iets te zeggen wat u nog niet hebt gehoord. Zie dit «advies» als een opdracht, als een gedragspraktijk! Voer deze praktijk op die dag uit. En geloof me - het zal veel interessanter voor u worden, en dit intensief zal u veel meer nut brengen. Sommige van zulke praktijken kunnen u eenvoudiger lijken, sommige moeilijker. Sommige pragmatischer, sommige psychologischer. In ieder geval is het niet alsof ik u heb voorgesteld twintig keer te hurken. Hier werken we met uw gedragsmatige en psychologische patronen. En de sleutel tot succes is om niet met uzelf te vechten, geen extra innerlijke spanning op te roepen, maar zoals in de asana''s - te ademen en te ontspannen. Daarom klinkt de praktijk zacht - als &quot;advies van de dag&quot; - om geen alarmsignaal op te roepen. Lees het, pas het op uzelf toe, probeer dit advies gedurende de dag zachtjes te volgen of er ten minste aan te denken, het opnieuw toe te passen en terug te keren naar het gevoel dat u het volgt. Pas u aan de nieuwe toestanden aan... In sommige gevallen kan één zo''n praktijk zich over meerdere dagen of zelfs maanden uitstrekken, omdat u het belang ervan zult voelen, en het in uw leven op het niveau van een gewoonte zult gaan invoeren, dat wil zeggen door de huidige homeostase van het systeem bij te stellen. En hoewel ik geen duidelijke verbinding heb aangelegd tussen de gedragspraktijken en de yogapraktijken die ik in één brief aanbied, kunt u toch elke yogapraktijk uitvoeren in de toestand die ontstaat wanneer u zichzelf ziet als iemand die mijn advies volgt. Dat is echter helemaal niet verplicht, omdat elk van deze twee praktijken op zichzelf voldoende is.<br>  <br><strong>4. Lesschema</strong><br> Elke dag om middernacht gaat er een nieuwe praktijk voor u open (de vorige verdwijnt daarbij, zoals de vorige dag). Dankzij deze aanpak zal er bij u geen sneeuwbal van niet-uitgevoerde praktijken ontstaan. Binnen een etmaal kunt u een voor u geschikt tijdstip kiezen en oefenen. Ik raad u aan ''s ochtends te oefenen, zodat u de dag kunt doorbrengen in de toestand die u door de praktijk hebt verkregen, in plaats van naar bed te gaan. Zie dit intensief niet als een computerillusie, maar als het echte leven - waarin alles wat belangrijk is VANDAAG gebeurt, en de yogapraktijk zich van de mat uitbreidt naar de ruimte van uw manifestatie in die wereld die u als de meest werkelijke ervaart!</p><p></p><p></p><p>Trouwens, er is een kleine nuance met betrekking tot de tijd waarop u de tweede praktijk ontvangt. Als u zich vóór 18:00 hebt ingeschreven, ontvangt u de tweede praktijk bij de eerstvolgende middernacht. Als u zich na 18:00 hebt ingeschreven, ontvangt u de tweede praktijk niet bij de eerstvolgende, maar bij de daaropvolgende middernacht. Dat wil zeggen dat u extra tijd hebt voor het geval u er niet aan toe komt de praktijk uit te voeren op de dag van inschrijving voor het intensief. <br>  <br><strong>5. Doe uzelf geen geweld aan</strong><br> Wanneer u een maandabonnement bij een fitnesscentrum koopt, begrijpt u toch dat u er niet elke dag heen hoeft? Sterker nog, als u een te snel tempo aanneemt, kunt u de lessen laten vallen nog voordat u zelfs maar het einde van de maand hebt bereikt... Voor de praktijken van dit intensief geldt dezelfde regel - wees niet hebberig! Oefen in een tempo dat u bevalt - om de dag, om de twee dagen... Natuurlijk is het goed om elke dag te oefenen, maar nog beter is - uw langetermijntaken te begrijpen en dienovereenkomstig te handelen. Waarschijnlijk gaan uw taken verder dan één maand, en moet u langdurig regelmatig in actie komen. Dit intensief heb ik zo bedacht dat u het maand na maand kunt doorlopen, zo vaak als nodig, totdat het door u gestelde doel is bereikt. Deze strategie is effectiever dan één maand er flink tegenaan te gaan en daarna de praktijken te laten vallen of in een andere richting te schieten.<br>  <br><strong>6. Veiligheidstechniek</strong><br> Ik geef om uw gezondheid en herinner u eraan dat alleen u verantwoordelijk bent voor of de uitvoering van de asana''s, pranayama''s en meditaties die ik zal aanbieden adequaat is voor uw lichamelijke mogelijkheden en psychische toestand. Het is belangrijk te begrijpen dat dit online lessen zijn, en dat ik uw toestand niet kan controleren. U kunt lichamelijke en psychologische bijzonderheden hebben. Wees alstublieft aandachtig voor uw eigen toestand. Als u merkt dat een bepaalde asana die ik voorstel uit te voeren voor u voortijdig is, voer haar dan niet erg diep uit, op een compromisniveau, of vervang haar helemaal door een andere asana - een die ongeveer ook het lichaam betrekt, maar eenvoudiger voor u is.<br>  <br><strong>7. Antwoorden op vragen</strong><br> Elke week (meestal op zaterdag) geef ik in Zoom groepsgewijze onlineconsulten (webinars), waarin we met elkaar praten, de motivatie ondersteunen en opkomende moeilijkheden en vragen bespreken. Voor elk zo''n consult stuur ik u een bericht met de datum en tijd waarop het plaatsvindt, evenals een link om eraan deel te nemen. Wat voor u interessant is, zal zeker ook voor velen anderen interessant zijn. Daarom is het bespreken van vragen in groepsconsulten het meest effectief. Als het zo uitkomt dat het tijdstip van het consult u niet uitkomt, stuur uw vragen dan vóór het begin per e-mail. Ik zal ze tijdens het consult beantwoorden, en u stuur ik een link naar de opname, zodat u deze op een voor u geschikt moment kunt bekijken. Opnamen van consulten worden gedurende één week bewaard.<br> <br>Ik wens u vruchtbare praktijken!</p><p></p><p>Sergey Zamkovoy</p>"}'::jsonb,'{"ru":[{"id":"intensive-pleasure-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png","alt":"Интенсив «Наслаждения»","width":"100%","align":"center","naturalWidth":599,"naturalHeight":152,"marginTop":0,"marginBottom":24},{"id":"intensive-pleasure-1-text","type":"text","html":"<p>Здравствуйте, {{name}}!<br> <br>Я рад, что вы решились в течение месяца направить своё внимание и целенаправленно поработать над темой, объединяющей такие состояния, как: наслаждения, расслабленность, кайфушность, игривость, привлекательность, сексуальность... Вроде бы как это простые, доступные каждому состояния. Однако, в социуме действует множество как побудительных, так и запретительных сценариев, которые управляют нашим поведением. Выполняя практики на йоговском коврике и в жизни, размышляя, корректируя свои мысли и поступки, в течение месяца можно получить важные результаты, которые проявятся как на уровне тела (оздоравливание), так и на уровне психологического фона (удовлетворённость и счастье).</p><p></p><p></p><p> В течение этого месяца вы получите 30 практик, направленных на гармонизацию второй чакры. Внимательно прочитайте это письмо, чтобы понимать, что и как будет происходить. <br> <br><strong>1. Самая суть</strong><br> Это не учебный курс, а интенсивный практикум, ядром которого являются ежедневные практики йоги. Данные практики я проводил по утрам в прямом эфире, синхронизируя направление каждой практики с планетными ритмами в тот день. В этом интенсиве я собрал видеозаписи лучших практик, которые были направлены именно на первую чакру (иногда во взаимодействии с какой-нибудь ещё чакрой), дополнил их поведенческими (психологическими) практиками. В результате получился мощнейший заряд для гармонизации сферы здоровья. </p><p></p><p></p><p>Если вы не проходили моих курсов и не понимаете при чём здесь какая-то там «вторая чакра», я рекомендую вам совместить прохождение данного интенсива с практикумом или курсом, в котором я плавно подвожу к пониманию того, чем мы здесь занимаемся. Важно не просто «поверить» мне, а открыть в себе понимание через личный опыт - как на йоговском коврике, так и в жизни. Тогда практики начинают работать гораздо глубже. Иначе получаем физкультуру - так как это базовое понимание (опыт) йоги, которое есть у каждого. </p><p></p><p></p><p>Данный интенсив вы можете дополнить следующими учебными программами:<br> - Практикум «Месяц наслаждений»: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> </p><p></p><p>- Курс «Йога плюс женственность»: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a>  <br>  <br><strong>2. Практики йоги</strong><br> Практики йоги, которые вас ожидают, отличаются от того, что вы можете встретить в фитнес-центре. Я предполагаю, что вам важен результат, а не лицедейство. Мы работаем с внутренними состояниями (то есть с энергиями), соединяя медитацию, пранаяму и асаны в той мере, в которой это необходимо для получения желаемого результата на максимально глубоком уровне. Большинство практик начинаются с небольшого введения, которое необходимо, чтобы ваше сознание переключилось с обыденности на волну практики, вы вошли в соответствующий энергетический поток и активировалось ваше внутреннее намерение. Далее следует сама практика, которая в разные дни имеет разную длительность и состав элементов. После практики я рекомендую вам некоторое время побыть в медитации, а может быть в возникшем состоянии осознанности продолжить выполнять асаны, которые будет просить ваше тело. Средняя продолжительность практик 30-40 минут. Но некоторые практики короче, а некоторые длятся около часа. Важно, чтобы во время практики вас ничто не отвлекало и не торопило. И ещё очень важно - начав практику, не прерывайтесь до её окончания!!! Каждая практика - это живая история, которая проводит вас по определённому пути. Прервав практику, вы можете оказаться в менее ресурсном состоянии, чем были в её начале. Даже если сейчас эти слова вам кажутся мистификацией и пустой эзотерикой, прислушайтесь к моим рекомендациям. <br>  <br><strong>3. Поведенческие практики</strong><br> Каждый день в письме вместе с практикой йоги я буду присылать вам «совет дня». Попробуйте воспринимать его не как ещё одну умную мысль, подобную которой вы уже много раз слышали. У меня нет цели вас удивить, сказав то, что вы ещё не слышали. Воспринимайте этот «совет» как задание, как поведенческую практику! Выполняйте эту практику в данный день. И поверьте - вам станет гораздо интересней, и этот интенсив принесёт вам гораздо больше пользы. Некоторые такие практики могут казаться вам проще, некоторые сложнее. Некоторые прагматичнее, некоторые более психологическими. В любом случае, это не как если бы я предложил вам 20 раз присесть. Тут мы работаем с вашими поведенческими и психологическими шаблонами. И ключ к успеху в том, чтобы не сражаться с собой, не вызывать дополнительное внутреннее напряжение, а как в асанах - дышать и расслабляться. Поэтому практика звучит мягко - как &quot;совет дня&quot; - чтобы не вызывать сигнал тревоги. Прочитайте, примерьте, попробуйте в течение дня мягко следовать этому совету или хотя бы вспоминать его, вновь примеряя и возвращаясь в ощущение, что вы ему следуете. Адаптируйтесь к новым состояниям... В некоторых случаях одна такая практика может растянуться на несколько дней или даже месяцев, потому что вы ощутите её значимость, и начнёте внедрять её в свою жизнь на уровне привычки, то есть корректируя текущий гомеостаз системы. И, хотя я не закладывал чёткую связь между поведенческими практиками и практиками йоги, которые предлагаю в одном письме, тем не менее вы можете выполнять каждую практику йоги в состоянии, возникшем когда вы воспринимаете себя следующим моему совету. Однако, это вовсе не обязательно, так как каждая из этих двух практик самодостаточна.<br>  <br><strong>4. Расписание занятий</strong><br> Каждый день в полночь вам будет открываться новая практика (прошлая при этом будет исчезать, как прошлый день). Благодаря такому подходу, у вас не будет накапливаться снежный ком невыполненных практик. В течение суток вы можете выбрать любое удобное вам время, и позаниматься. Я рекомендую вам заниматься утром, чтобы в полученном в результате практики состоянии проживать день, а не спать лечь. Воспринимайте этот интенсив не как компьютерную иллюзию, а как реальную жизнь - в которой всё важное происходит СЕГОДНЯ, и практика йоги расширяется с коврика на пространство вашей проявленности в том мире, который вы воспринимаете, как наиболее реальный!</p><p></p><p></p><p>Кстати, есть небольшой нюанс с временем получения второй практики. Если вы записались до 18:00, то вторую практику вы получите в ближайшую полночь. Если же вы записались после 18:00, то вторую практику вы получите не в ближайшую, а в следующую полночь. То есть у вас будет запас времени на случай, если вы не успеете выполнить практику в день записи на интенсив. <br>  <br><strong>5. Не насилуйте себя</strong><br> Когда вы покупаете месячный абонемент в фитнес центр, вы ведь понимаете, что вам не обязательно ходить в него каждый день? Более того, взяв слишком быстрый темп, вы можете забросить занятия не дойдя даже до конца месяца... В отношении практик данного интенсива действует то же правило - не жадничайте! Занимайтесь в удобном вам ритме - через день, через два... Конечно, хорошо заниматься каждый день, но ещё лучше - понимать свои долгосрочные задачи, и действовать соответственно. Скорее всего, ваши задачи выходят за рамки одного месяца, и вам необходимо регулярно действовать длительное время. Данный интенсив я задумал так, чтобы вы могли проходить его месяц за месяцем столько раз, сколько потребуется, пока поставленная вами цель не будет достигнута. Эта стратегия эффективней, чем один месяц втопить, а потом забросить практики или рвануть в другом направлении.<br>  <br><strong>6. Техника безопасности</strong><br> Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, которые я буду предлагать, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу контролировать ваше состояние. У вас могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.<br>  <br><strong>7. Ответы на вопросы</strong><br> Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.<br> <br>Желаю вам плодотворных практик!</p><p></p><p>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"en":[{"id":"intensive-pleasure-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png","alt":"Интенсив «Наслаждения»","width":"100%","align":"center","naturalWidth":599,"naturalHeight":152,"marginTop":0,"marginBottom":24},{"id":"intensive-pleasure-1-text","type":"text","html":"<p>Hello, {{name}}!<br> <br>I am glad that you decided to direct your attention for a month and purposefully work on the theme uniting such states as: pleasures, relaxation, blissfulness, playfulness, attractiveness, sexuality... They seem to be simple states accessible to everyone. However, in society there are many both motivating and prohibitive scenarios that control our behavior. By doing practices on the yoga mat and in life, reflecting, adjusting your thoughts and actions, over the course of a month you can get important results that will manifest both at the level of the body (healing) and at the level of the psychological background (satisfaction and happiness).</p><p></p><p></p><p> During this month you will receive 30 practices aimed at harmonizing the second chakra. Read this letter carefully to understand what and how everything will happen. <br> <br><strong>1. The very essence</strong><br> This is not a training course, but an intensive workshop, the core of which is daily yoga practices. I conducted these practices in the mornings in live broadcasts, synchronizing the direction of each practice with the planetary rhythms on that day. In this intensive I have gathered video recordings of the best practices that were aimed specifically at the first chakra (sometimes in interaction with some other chakra), and supplemented them with behavioral (psychological) practices. The result is a most powerful charge for harmonizing the sphere of health. </p><p></p><p></p><p>If you have not taken my courses and do not understand what some “second chakra” has to do with this, I recommend that you combine going through this intensive with a workshop or course in which I smoothly lead you to an understanding of what we are doing here. It is important not just to “believe” me, but to open understanding within yourself through personal experience—both on the yoga mat and in life. Then the practices begin to work much deeper. Otherwise we get physical exercise—since this is the basic understanding (experience) of yoga that everyone has. </p><p></p><p></p><p>You can supplement this intensive with the following educational programs:<br> - Workshop “A Month of Pleasures”: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> </p><p></p><p>- Course “Yoga Plus Femininity”: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a> <br>  <br><strong>2. Yoga practices</strong><br> The yoga practices that await you differ from what you may encounter in a fitness center. I assume that the result matters to you, not playacting. We work with inner states (that is, with energies), combining meditation, pranayama, and asanas to the extent necessary to obtain the desired result at the deepest possible level. Most practices begin with a short introduction, which is necessary so that your consciousness switches from everydayness to the wave of the practice, you enter the corresponding energy flow, and your inner intention becomes activated. Then comes the practice itself, which on different days has a different duration and composition of elements. After the practice, I recommend that you spend some time in meditation, or perhaps, in the arising state of awareness, continue to perform the asanas that your body will ask for. The average duration of the practices is 30-40 minutes. But some practices are shorter, and some last about an hour. It is important that during the practice nothing distracts you and nothing hurries you. And one more very important thing - having begun the practice, do not interrupt it until it ends!!! Each practice is a living story that takes you along a certain path. If you interrupt the practice, you may end up in a less resourceful state than you were in at its beginning. Even if right now these words seem to you like mystification and empty esotericism, heed my recommendations. <br>  <br><strong>3. Behavioral practices</strong><br> Every day in the email, together with the yoga practice, I will send you a “tip of the day.” Try to perceive it not as yet another clever thought, similar to which you have already heard many times. I have no goal of surprising you by saying something you have not yet heard. Perceive this “tip” as a task, as a behavioral practice! Perform this practice on the given day. And believe me - it will become much more interesting for you, and this intensive will bring you much more benefit. Some such practices may seem easier to you, some harder. Some more pragmatic, some more psychological. In any case, it is not as if I suggested that you do 20 squats. Here we work with your behavioral and psychological patterns. And the key to success is not to fight with yourself, not to create additional inner tension, but, as in asanas, to breathe and relax. That is why the practice sounds soft - like a “tip of the day” - so as not to trigger an alarm signal. Read it, try it on, try during the day to gently follow this tip or at least to remember it, again trying it on and returning to the feeling that you are following it. Adapt to new states... In some cases, one such practice may stretch over several days or even months, because you will feel its significance and begin to introduce it into your life at the level of a habit, that is, adjusting the current homeostasis of the system. And although I did not build in a clear connection between the behavioral practices and the yoga practices that I offer in one email, nevertheless you can perform each yoga practice in the state that arises when you perceive yourself as following my tip. However, this is not at all obligatory, since each of these two practices is self-sufficient.<br>  <br><strong>4. Class schedule</strong><br> Every day at midnight a new practice will open for you (the previous one will disappear, like the previous day). Thanks to this approach, uncompleted practices will not accumulate into a snowball. During the day you can choose any time convenient for you and practice. I recommend that you practice in the morning, so that you live the day in the state obtained as a result of the practice, rather than go to sleep. Perceive this intensive not as a computer illusion, but as real life - in which everything important happens TODAY, and the yoga practice expands from the mat into the space of your manifestation in that world which you perceive as the most real!</p><p></p><p></p><p>By the way, there is a small nuance with the time you receive the second practice. If you signed up before 18:00, then you will receive the second practice at the nearest midnight. If you signed up after 18:00, then you will receive the second practice not at the nearest midnight, but at the following midnight. That is, you will have a reserve of time in case you do not manage to complete the practice on the day you signed up for the intensive. <br>  <br><strong>5. Do not force yourself</strong><br> When you buy a monthly membership at a fitness center, you do understand that you do not have to go there every day, right? Moreover, by taking too fast a pace, you may abandon the classes before you even reach the end of the month... The same rule applies to the practices of this intensive - do not be greedy! Practice at a pace convenient for you - every other day, every two days... Of course, it is good to practice every day, but it is even better to understand your long-term tasks and act accordingly. Most likely, your tasks go beyond one month, and you need to act regularly for a long time. I conceived this intensive so that you could go through it month after month as many times as needed until the goal you have set is achieved. This strategy is more effective than going all out for one month and then abandoning the practices or rushing off in another direction.<br>  <br><strong>6. Safety precautions</strong><br> I care about your health and remind you that only you bear responsibility for the adequacy of performing the asanas, pranayamas, and meditations that I will offer to your physical capabilities and mental state. It is important to understand that these are online classes, and I cannot control your state. You may have physical and psychological particularities. Please be attentive to your state. If you feel that some asana that I suggest performing is premature for you, perform it not very deeply, at a compromise level, or replace it altogether with another asana - one that approximately also engages the body but is easier for you.<br>  <br><strong>7. Answers to questions</strong><br> Every week (usually on Saturdays) I hold group online consultations (webinars) in Zoom, at which we communicate, maintain motivation, and discuss difficulties and questions that arise. Before each such consultation, I will send you an email indicating the date and time of its holding, as well as a link to join it. What is interesting to you will surely also be interesting to many others. Therefore, discussing questions at group consultations is most effective. If it happens that the time of the consultation is inconvenient for you, in that case send your questions by email before it begins. I will answer them at the consultation, and I will send you a link to the recording so that you can watch it at a time convenient for you. Consultation recordings are kept for one week.<br> <br>I wish you fruitful practices!</p><p></p><p>Sergey Zamkovoy</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"de":[{"id":"intensive-pleasure-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png","alt":"Интенсив «Наслаждения»","width":"100%","align":"center","naturalWidth":599,"naturalHeight":152,"marginTop":0,"marginBottom":24},{"id":"intensive-pleasure-1-text","type":"text","html":"<p>Guten Tag, {{name}}!<br> <br>Ich freue mich, dass Sie sich entschieden haben, einen Monat lang Ihre Aufmerksamkeit auf das Thema zu richten und gezielt an dem zu arbeiten, das Zustände wie folgende vereint: Genuss, Entspannung, Rauschhaftigkeit, Verspieltheit, Attraktivität, Sexualität... An sich sind das einfache, jedem zugängliche Zustände. Doch in der Gesellschaft wirken viele sowohl antreibende als auch verbietende Szenarien, die unser Verhalten steuern. Wenn Sie die Praktiken auf der Yogamatte und im Leben ausführen, nachdenken, Ihre Gedanken und Handlungen korrigieren, können Sie innerhalb eines Monats wichtige Ergebnisse erzielen, die sich sowohl auf der Ebene des Körpers (Gesundung) als auch auf der Ebene des psychologischen Hintergrunds (Zufriedenheit und Glück) zeigen.</p><p></p><p></p><p> In diesem Monat erhalten Sie 30 Praktiken, die auf die Harmonisierung des zweiten Chakras ausgerichtet sind. Lesen Sie diesen Brief sorgfältig, damit Sie verstehen, was und wie geschehen wird. <br> <br><strong>1. Das Wesentliche</strong><br> Das ist kein Lehrkurs, sondern ein intensives Praktikum, dessen Kern tägliche Yoga-Praktiken sind. Diese Praktiken habe ich morgens live durchgeführt und dabei die Ausrichtung jeder Praxis mit den planetaren Rhythmen jenes Tages synchronisiert. In diesem Intensivkurs habe ich Videoaufzeichnungen der besten Praktiken gesammelt, die genau auf das erste Chakra ausgerichtet waren (manchmal in Wechselwirkung mit einem anderen Chakra), und sie um verhaltensbezogene (psychologische) Praktiken ergänzt. Daraus ist eine äußerst kraftvolle Ladung für die Harmonisierung des Bereichs Gesundheit entstanden. </p><p></p><p></p><p>Wenn Sie meine Kurse nicht besucht haben und nicht verstehen, was es mit dieser „zweiten Chakra“ auf sich hat, empfehle ich Ihnen, den Besuch dieses Intensivkurses mit einem Praktikum oder Kurs zu kombinieren, in dem ich Sie behutsam zum Verständnis dessen hinführe, womit wir uns hier beschäftigen. Wichtig ist, nicht einfach mir zu „glauben“, sondern in sich selbst ein Verständnis durch persönliche Erfahrung zu eröffnen – sowohl auf der Yogamatte als auch im Leben. Dann beginnen die Praktiken viel tiefer zu wirken. Andernfalls bekommen wir bloß Gymnastik – denn das ist das grundlegende Verständnis (die Erfahrung) des Yoga, das jeder hat. </p><p></p><p></p><p>Diesen Intensivkurs können Sie mit folgenden Lernprogrammen ergänzen:<br> - Praktikum „Monat der Genüsse“: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> </p><p></p><p>- Kurs „Yoga plus Weiblichkeit“: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a>  <br>  <br><strong>2. Yoga-Praktiken</strong><br> Die Yoga-Praktiken, die Sie erwarten, unterscheiden sich von dem, was Sie in einem Fitnesscenter antreffen können. Ich gehe davon aus, dass Ihnen das Ergebnis wichtig ist und nicht die Schauspielerei. Wir arbeiten mit inneren Zuständen (das heißt mit Energien) und verbinden Meditation, Pranayama und Asanas in dem Maße, wie es nötig ist, um das gewünschte Ergebnis auf möglichst tiefer Ebene zu erzielen. Die meisten Praktiken beginnen mit einer kurzen Einführung, die notwendig ist, damit Ihr Bewusstsein von der Alltäglichkeit auf die Welle der Praxis umschaltet, Sie in den entsprechenden energetischen Fluss eintreten und Ihr inneres Vorhaben aktiviert wird. Danach folgt die eigentliche Praxis, die an verschiedenen Tagen eine unterschiedliche Dauer und Zusammensetzung der Elemente hat. Nach der Praxis empfehle ich Ihnen, einige Zeit in Meditation zu verweilen, und vielleicht im entstandenen Zustand der Achtsamkeit weiter Asanas auszuführen, die Ihr Körper erbitten wird. Die durchschnittliche Dauer der Praktiken beträgt 30-40 Minuten. Aber manche Praktiken sind kürzer, und manche dauern etwa eine Stunde. Wichtig ist, dass Sie während der Praxis nichts ablenkt und nichts zur Eile treibt. Und noch sehr wichtig – wenn Sie die Praxis begonnen haben, unterbrechen Sie sie nicht bis zu ihrem Ende!!! Jede Praxis ist eine lebendige Geschichte, die Sie einen bestimmten Weg entlangführt. Wenn Sie die Praxis unterbrechen, können Sie in einem weniger ressourcenreichen Zustand landen, als Sie zu Beginn waren. Auch wenn Ihnen diese Worte jetzt wie Mystifikation und leere Esoterik erscheinen mögen, hören Sie auf meine Empfehlungen. <br>  <br><strong>3. Verhaltenspraktiken</strong><br> Jeden Tag werde ich Ihnen im Brief zusammen mit der Yoga-Praxis einen „Tipp des Tages“ schicken. Versuchen Sie, ihn nicht als einen weiteren klugen Gedanken zu betrachten, von der Art, wie Sie sie schon viele Male gehört haben. Ich habe nicht das Ziel, Sie zu überraschen, indem ich etwas sage, das Sie noch nicht gehört haben. Betrachten Sie diesen „Tipp“ als Aufgabe, als Verhaltenspraxis! Führen Sie diese Praxis an diesem Tag aus. Und glauben Sie mir – es wird Ihnen viel interessanter werden, und dieser Intensivkurs wird Ihnen viel mehr Nutzen bringen. Manche solcher Praktiken mögen Ihnen einfacher erscheinen, manche schwieriger. Manche pragmatischer, manche psychologischer. In jedem Fall ist es nicht so, als hätte ich Ihnen vorgeschlagen, 20 Kniebeugen zu machen. Hier arbeiten wir mit Ihren Verhaltens- und psychologischen Mustern. Und der Schlüssel zum Erfolg liegt darin, nicht mit sich zu kämpfen, keine zusätzliche innere Spannung zu erzeugen, sondern wie in den Asanas zu atmen und sich zu entspannen. Deshalb klingt die Praxis sanft – wie ein „Tipp des Tages“ –, damit kein Alarmsignal ausgelöst wird. Lesen Sie ihn, probieren Sie ihn aus, versuchen Sie im Laufe des Tages, diesem Tipp sanft zu folgen oder ihn wenigstens in Erinnerung zu rufen, ihn erneut anzuprobieren und in das Gefühl zurückzukehren, dass Sie ihm folgen. Passen Sie sich an die neuen Zustände an... In manchen Fällen kann sich eine solche Praxis über mehrere Tage oder sogar Monate erstrecken, weil Sie ihre Bedeutung spüren und beginnen, sie auf der Ebene der Gewohnheit in Ihr Leben einzuführen, das heißt, die aktuelle Homöostase des Systems zu korrigieren. Und obwohl ich keine klare Verbindung zwischen den Verhaltenspraktiken und den Yoga-Praktiken, die ich in einem Brief anbiete, angelegt habe, können Sie dennoch jede Yoga-Praxis in dem Zustand ausführen, der entsteht, wenn Sie sich als jemanden wahrnehmen, der meinem Tipp folgt. Das ist jedoch keineswegs zwingend, da jede dieser beiden Praktiken für sich genügt.<br>  <br><strong>4. Zeitplan der Übungen</strong><br> Jeden Tag um Mitternacht wird Ihnen eine neue Praxis freigeschaltet (die vorherige verschwindet dabei, wie der vergangene Tag). Durch diesen Ansatz wird sich bei Ihnen kein Schneeball unerledigter Praktiken ansammeln. Innerhalb von 24 Stunden können Sie jede Ihnen passende Zeit wählen und praktizieren. Ich empfehle Ihnen, morgens zu praktizieren, um den Tag in dem durch die Praxis entstandenen Zustand zu erleben, statt sich schlafen zu legen. Betrachten Sie diesen Intensivkurs nicht als Computer-Illusion, sondern als reales Leben – in dem alles Wichtige HEUTE geschieht und sich die Yoga-Praxis von der Matte auf den Raum Ihrer Manifestation in der Welt ausdehnt, die Sie als die realste wahrnehmen!</p><p></p><p></p><p>Übrigens gibt es eine kleine Besonderheit mit dem Zeitpunkt, zu dem Sie die zweite Praxis erhalten. Wenn Sie sich vor 18:00 Uhr angemeldet haben, erhalten Sie die zweite Praxis in der nächsten Mitternacht. Wenn Sie sich jedoch nach 18:00 Uhr angemeldet haben, erhalten Sie die zweite Praxis nicht in der nächsten, sondern in der darauffolgenden Mitternacht. Das heißt, Sie haben einen Zeitpuffer für den Fall, dass Sie die Praxis am Tag der Anmeldung zum Intensivkurs nicht mehr schaffen. <br>  <br><strong>5. Zwingen Sie sich nicht</strong><br> Wenn Sie ein Monatsabo in einem Fitnesscenter kaufen, verstehen Sie doch, dass Sie nicht unbedingt jeden Tag hingehen müssen? Mehr noch: Wenn Sie ein zu schnelles Tempo anschlagen, können Sie die Übungen aufgeben, ohne sogar das Ende des Monats erreicht zu haben... Für die Praktiken dieses Intensivkurses gilt dieselbe Regel – seien Sie nicht gierig! Praktizieren Sie in einem Ihnen angenehmen Rhythmus – jeden zweiten Tag, jeden dritten... Natürlich ist es gut, jeden Tag zu praktizieren, aber noch besser ist es, seine langfristigen Aufgaben zu verstehen und entsprechend zu handeln. Höchstwahrscheinlich gehen Ihre Aufgaben über einen Monat hinaus, und Sie müssen über einen längeren Zeitraum regelmäßig handeln. Diesen Intensivkurs habe ich so konzipiert, dass Sie ihn Monat für Monat so oft durchlaufen können, wie es nötig ist, bis das von Ihnen gesetzte Ziel erreicht ist. Diese Strategie ist effektiver, als einen Monat lang Vollgas zu geben und dann die Praktiken aufzugeben oder in eine andere Richtung davonzustürmen.<br>  <br><strong>6. Sicherheitstechnik</strong><br> Ich kümmere mich um Ihre Gesundheit und erinnere daran, dass allein Sie die Verantwortung dafür tragen, dass die Ausführung der Asanas, Pranayamas und Meditationen, die ich anbieten werde, Ihren körperlichen Möglichkeiten und Ihrem psychischen Zustand angemessen ist. Wichtig zu verstehen ist, dass dies Online-Kurse sind und ich Ihren Zustand nicht kontrollieren kann. Bei Ihnen können körperliche und psychologische Besonderheiten vorliegen. Bitte seien Sie aufmerksam gegenüber Ihrem Zustand. Wenn Sie spüren, dass eine bestimmte Asana, die ich zur Ausführung anbiete, für Sie verfrüht ist, führen Sie sie nicht sehr tief aus, auf einem Kompromissniveau, oder ersetzen Sie sie ganz durch eine andere Asana – eine, die den Körper ungefähr ebenfalls einbezieht, aber für Sie einfacher ist.<br>  <br><strong>7. Antworten auf Fragen</strong><br> Jede Woche (normalerweise samstags) führe ich in Zoom Gruppen-Online-Konsultationen (Webinare) durch, in denen wir uns austauschen, die Motivation aufrechterhalten und auftretende Schwierigkeiten und Fragen besprechen. Vor jeder solchen Konsultation werde ich Ihnen eine E-Mail mit Angabe von Datum und Uhrzeit ihrer Durchführung sowie einem Link zum Beitreten schicken. Was für Sie interessant ist, wird sicherlich auch für viele andere interessant sein. Deshalb ist die Besprechung von Fragen in den Gruppenkonsultationen am effektivsten. Sollte es geschehen, dass die Zeit der Konsultation für Sie ungünstig ist, senden Sie in diesem Fall Ihre Fragen vor ihrem Beginn per E-Mail. Ich werde sie in der Konsultation beantworten und Ihnen einen Link zur Aufzeichnung schicken, damit Sie sie zu einer Ihnen passenden Zeit ansehen können. Die Aufzeichnungen der Konsultationen werden eine Woche lang gespeichert.<br> <br>Ich wünsche Ihnen fruchtbare Praktiken!</p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"fr":[{"id":"intensive-pleasure-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png","alt":"Интенсив «Наслаждения»","width":"100%","align":"center","naturalWidth":599,"naturalHeight":152,"marginTop":0,"marginBottom":24},{"id":"intensive-pleasure-1-text","type":"text","html":"<p>Bonjour, {{name}} !<br> <br>Je suis heureux que vous ayez décidé, pendant un mois, de diriger votre attention et de travailler de manière ciblée sur le thème qui réunit des états tels que : les plaisirs, la relaxation, le kiff, l’espièglerie, l’attractivité, la sexualité... En apparence, ce sont des états simples, accessibles à chacun. Cependant, dans la société agissent de nombreux scénarios, à la fois incitatifs et prohibitifs, qui gouvernent notre comportement. En pratiquant sur le tapis de yoga et dans la vie, en réfléchissant, en corrigeant vos pensées et vos actes, au cours d’un mois vous pouvez obtenir des résultats importants, qui se manifesteront tant au niveau du corps (guérison) qu’au niveau du fond psychologique (satisfaction et bonheur).</p><p></p><p></p><p> Au cours de ce mois, vous recevrez 30 pratiques visant à harmoniser le deuxième chakra. Lisez attentivement cette lettre afin de comprendre ce qui va se passer et comment. <br> <br><strong>1. L’essentiel</strong><br> Ce n’est pas un cours d’apprentissage, mais un atelier intensif dont le cœur est constitué de pratiques quotidiennes de yoga. J’ai mené ces pratiques le matin en direct, en synchronisant l’orientation de chaque pratique avec les rythmes planétaires de ce jour-là. Dans cet intensif, j’ai réuni des enregistrements vidéo des meilleures pratiques qui étaient précisément destinées au premier chakra (parfois en interaction avec un autre chakra), et je les ai complétées par des pratiques comportementales (psychologiques). Il en est résulté une charge extrêmement puissante pour harmoniser le domaine de la santé. </p><p></p><p></p><p>Si vous n’avez pas suivi mes cours et ne comprenez pas ce que vient faire ici une quelconque « deuxième chakra », je vous recommande de combiner ce parcours intensif avec le séminaire pratique ou le cours dans lequel je vous amène progressivement à comprendre ce que nous faisons ici. Il est important non pas simplement de « me croire », mais d’ouvrir en vous la compréhension par l’expérience personnelle — tant sur le tapis de yoga que dans la vie. Alors les pratiques commencent à agir beaucoup plus profondément. Sinon, nous obtenons de la culture physique — car c’est la compréhension (l’expérience) de base du yoga que chacun possède.</p><p></p><p></p><p>Vous pouvez compléter cet intensif avec les programmes d’apprentissage suivants :<br> - Atelier pratique « Un mois de plaisirs » : <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> </p><p></p><p>- Cours « Yoga plus féminité » : <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a>  <br>  <br><strong>2. Pratiques de yoga</strong><br> Les pratiques de yoga qui vous attendent diffèrent de ce que vous pouvez rencontrer dans un centre de fitness. Je suppose que le résultat vous importe, et non le jeu d’acteur. Nous travaillons avec les états intérieurs (c’est-à-dire avec les énergies), en unissant la méditation, le pranayama et les asanas dans la mesure nécessaire pour obtenir le résultat souhaité au niveau le plus profond possible. La plupart des pratiques commencent par une courte introduction, nécessaire pour que votre conscience passe du quotidien à la vague de la pratique, que vous entriez dans le flux énergétique correspondant et que votre intention intérieure s’active. Vient ensuite la pratique elle-même, qui selon les jours a une durée et une composition d’éléments différentes. Après la pratique, je vous recommande de rester quelque temps en méditation, et peut-être, dans l’état de conscience apparu, de continuer à exécuter les asanas que votre corps demandera. La durée moyenne des pratiques est de 30-40 minutes. Mais certaines pratiques sont plus courtes, et d’autres durent environ une heure. Il est important que pendant la pratique rien ne vous distraie ni ne vous presse. Et encore très important - une fois la pratique commencée, ne l’interrompez pas avant sa fin!!! Chaque pratique est une histoire vivante qui vous conduit sur un chemin déterminé. En interrompant la pratique, vous pouvez vous retrouver dans un état moins pourvu en ressources que celui dans lequel vous étiez au début. Même si maintenant ces mots vous semblent une mystification et de l’ésotérisme vide, écoutez mes recommandations. <br>  <br><strong>3. Pratiques comportementales</strong><br> Chaque jour, dans l’e-mail, avec la pratique de yoga, je vous enverrai un « conseil du jour ». Essayez de le percevoir non pas comme une pensée intelligente de plus, semblable à celles que vous avez déjà entendues bien des fois. Je n’ai pas pour but de vous surprendre en disant ce que vous n’avez encore jamais entendu. Percevez ce « conseil » comme une tâche, comme une pratique comportementale ! Accomplissez cette pratique ce jour-là. Et croyez-moi - cela vous paraîtra beaucoup plus intéressant, et cet intensif vous apportera beaucoup plus de bienfaits. Certaines de ces pratiques peuvent vous sembler plus simples, d’autres plus difficiles. Certaines plus pragmatiques, d’autres plus psychologiques. Dans tous les cas, ce n’est pas comme si je vous proposais de faire 20 squats. Ici, nous travaillons avec vos schémas comportementaux et psychologiques. Et la clé du succès est de ne pas lutter contre vous-même, de ne pas provoquer une tension intérieure supplémentaire, mais, comme dans les asanas, de respirer et de vous détendre. C’est pourquoi la pratique se présente doucement - comme un « conseil du jour » - afin de ne pas déclencher de signal d’alarme. Lisez-le, essayez-le, tentez pendant la journée de suivre doucement ce conseil ou du moins de vous en souvenir, en l’essayant à nouveau et en revenant à la sensation que vous le suivez. Adaptez-vous aux nouveaux états... Dans certains cas, une telle pratique peut s’étendre sur plusieurs jours ou même plusieurs mois, parce que vous en ressentirez l’importance et commencerez à l’intégrer dans votre vie au niveau de l’habitude, c’est-à-dire en corrigeant l’homéostasie actuelle du système. Et, bien que je n’aie pas établi de lien précis entre les pratiques comportementales et les pratiques de yoga que je propose dans un même e-mail, vous pouvez néanmoins accomplir chaque pratique de yoga dans l’état apparu lorsque vous vous percevez comme suivant mon conseil. Cependant, ce n’est pas du tout obligatoire, car chacune de ces deux pratiques est autosuffisante.<br>  <br><strong>4. Horaire des séances</strong><br> Chaque jour à minuit, une nouvelle pratique s’ouvrira pour vous (la précédente disparaîtra alors, comme le jour précédent). Grâce à cette approche, les pratiques non accomplies ne s’accumuleront pas en boule de neige. Pendant les vingt-quatre heures, vous pouvez choisir n’importe quel moment qui vous convient et pratiquer. Je vous recommande de pratiquer le matin, afin de vivre la journée dans l’état obtenu grâce à la pratique, et non d’aller vous coucher. Percevez cet intensif non pas comme une illusion informatique, mais comme la vie réelle - dans laquelle tout ce qui est important se produit AUJOURD’HUI, et la pratique du yoga s’étend du tapis à l’espace de votre manifestation dans ce monde que vous percevez comme le plus réel !</p><p></p><p></p><p>À propos, il y a une petite nuance concernant le moment où vous recevez la deuxième pratique. Si votre inscription a eu lieu avant 18:00, vous recevrez la deuxième pratique à la prochaine minuit. Si en revanche votre inscription a eu lieu après 18:00, vous recevrez la deuxième pratique non pas à la prochaine minuit, mais à la minuit suivante. Autrement dit, vous aurez une marge de temps au cas où vous n’auriez pas le temps d’accomplir la pratique le jour de l’inscription à l’intensif. <br>  <br><strong>5. Ne vous forcez pas</strong><br> Lorsque vous achetez un abonnement mensuel dans un centre de fitness, vous comprenez bien que vous n’êtes pas obligé d’y aller chaque jour ? De plus, en prenant un rythme trop rapide, vous risquez d’abandonner les séances avant même d’arriver à la fin du mois... En ce qui concerne les pratiques de cet intensif, la même règle s’applique - ne soyez pas gourmand ! Pratiquez à un rythme qui vous convient - tous les deux jours, tous les trois jours... Bien sûr, il est bon de pratiquer chaque jour, mais il est encore mieux de comprendre vos tâches à long terme et d’agir en conséquence. Très probablement, vos tâches dépassent le cadre d’un mois, et vous devez agir régulièrement pendant une longue période. J’ai conçu cet intensif de manière à ce que vous puissiez le suivre mois après mois autant de fois que nécessaire, jusqu’à ce que l’objectif que vous vous êtes fixé soit atteint. Cette stratégie est plus efficace que de se donner à fond pendant un mois, puis d’abandonner les pratiques ou de partir dans une autre direction.<br>  <br><strong>6. Consignes de sécurité</strong><br> Je me soucie de votre santé et je vous rappelle que c’est vous qui portez la responsabilité de l’adéquation de l’exécution des asanas, des pranayamas et des méditations que je proposerai à vos possibilités physiques et à votre état psychique. Il est important de comprendre qu’il s’agit de séances en ligne et que je ne peux pas contrôler votre état. Vous pouvez avoir des particularités physiques et psychologiques. Veuillez être attentif à votre état. Si vous sentez qu’une asana que je propose d’exécuter est prématurée pour vous, exécutez-la pas très profondément, à un niveau de compromis, ou remplacez-la entièrement par une autre asana - telle qui sollicite à peu près autant le corps, mais qui est plus simple pour vous.<br>  <br><strong>7. Réponses aux questions</strong><br> Chaque semaine (généralement le samedi), j’anime sur Zoom des consultations en ligne de groupe (webinaires), pendant lesquelles nous échangeons, maintenons la motivation, discutons des difficultés et des questions qui surviennent. Avant chacune de ces consultations, je vous enverrai un e-mail indiquant la date et l’heure de sa tenue, ainsi qu’un lien pour la rejoindre. Ce qui vous intéresse intéressera sûrement aussi beaucoup d’autres personnes. C’est pourquoi il est plus efficace de discuter des questions lors des consultations de groupe. S’il arrive que l’heure de la consultation ne vous convienne pas, dans ce cas envoyez vos questions par e-mail avant son début. Je répondrai à ces questions lors de la consultation, et je vous enverrai un lien vers l’enregistrement afin que vous puissiez le regarder au moment qui vous convient. Les enregistrements des consultations sont conservés pendant une semaine.<br> <br>Je vous souhaite des pratiques fructueuses !</p><p></p><p>Sergueï Zamkovoï</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"it":[{"id":"intensive-pleasure-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png","alt":"Интенсив «Наслаждения»","width":"100%","align":"center","naturalWidth":599,"naturalHeight":152,"marginTop":0,"marginBottom":24},{"id":"intensive-pleasure-1-text","type":"text","html":"<p>Salve, {{name}}!<br> <br>Sono felice che vi siate decisi, nell’arco di un mese, a rivolgere la vostra attenzione e a lavorare intenzionalmente sul tema che unisce stati come: piacere, rilassatezza, goduria, giocosità, attrattività, sessualità... In apparenza sembrano stati semplici, accessibili a tutti. Tuttavia, nella società agiscono molti copioni, sia incentivanti sia inibitori, che governano il nostro comportamento. Svolgendo le pratiche sul tappetino yoga e nella vita, riflettendo, correggendo i propri pensieri e le proprie azioni, nell’arco di un mese si possono ottenere risultati importanti, che si manifesteranno sia a livello del corpo (risanamento), sia a livello dello sfondo psicologico (soddisfazione e felicità).</p><p></p><p></p><p> Nel corso di questo mese riceverete 30 pratiche volte ad armonizzare il secondo chakra. Leggete attentamente questa lettera per capire cosa e come accadrà. <br> <br><strong>1. L''essenza stessa</strong><br> Non è un corso didattico, ma un praticum intensivo, il cui nucleo sono le pratiche yoga quotidiane. Queste pratiche le ho condotte al mattino in diretta, sincronizzando la direzione di ogni pratica con i ritmi planetari di quel giorno. In questo intensivo ho raccolto le videoregistrazioni delle migliori pratiche, che erano dirette proprio al primo chakra (a volte in interazione con qualche altro chakra), e le ho integrate con pratiche comportamentali (psicologiche). Il risultato è stato una carica potentissima per l''armonizzazione dell''ambito della salute. </p><p></p><p></p><p>Se non avete seguito i miei corsi e non capite cosa c’entri qui un qualche «secondo chakra», vi consiglio di abbinare lo svolgimento di questo intensivo a un laboratorio pratico o a un corso in cui vi accompagno gradualmente alla comprensione di ciò di cui ci occupiamo qui. È importante non solo «credermi», ma aprire in voi la comprensione attraverso l’esperienza personale, sia sul tappetino yoga sia nella vita. Allora le pratiche iniziano a funzionare molto più in profondità. Altrimenti otteniamo educazione fisica, dal momento che questa è la comprensione (esperienza) di base dello yoga che ognuno possiede. </p><p></p><p></p><p>Questo intensivo potete integrarlo con i seguenti programmi di studio:<br> - Laboratorio pratico «Un mese di piaceri»: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> </p><p></p><p>- Corso «Yoga più femminilità»: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a>  <br>  <br><strong>2. Pratiche yoga</strong><br> Le pratiche yoga che vi attendono sono diverse da ciò che potete trovare in un centro fitness. Presumo che per voi conti il risultato, non la messa in scena. Lavoriamo con gli stati interiori (cioè con le energie), unendo meditazione, pranayama e asana nella misura necessaria per ottenere il risultato desiderato al livello più profondo possibile. La maggior parte delle pratiche inizia con una breve introduzione, necessaria affinché la vostra coscienza passi dalla quotidianità all''onda della pratica, entriate nel corrispondente flusso energetico e si attivi la vostra intenzione interiore. Segue poi la pratica stessa, che nei diversi giorni ha durata e composizione di elementi diverse. Dopo la pratica vi raccomando di restare per un po'' in meditazione, e magari, nello stato di consapevolezza che è emerso, di continuare a eseguire le asana che il vostro corpo chiederà. La durata media delle pratiche è di 30-40 minuti. Ma alcune pratiche sono più brevi, e alcune durano circa un''ora. È importante che durante la pratica nulla vi distragga e vi metta fretta. E ancora molto importante - una volta iniziata la pratica, non interrompetela prima della fine!!! Ogni pratica è una storia viva, che vi conduce lungo un determinato percorso. Interrompendo la pratica, potete ritrovarvi in uno stato meno ricco di risorse di quello in cui eravate all''inizio. Anche se ora queste parole vi sembrano una mistificazione e vuoto esoterismo, ascoltate le mie raccomandazioni. <br>  <br><strong>3. Pratiche comportamentali</strong><br> Ogni giorno, nella lettera insieme alla pratica yoga, vi invierò il «consiglio del giorno». Provate a percepirlo non come un altro pensiero intelligente, simile al quale ne avete già sentiti molti. Non ho l''obiettivo di sorprendervi dicendo qualcosa che non avete ancora sentito. Percepite questo «consiglio» come un compito, come una pratica comportamentale! Eseguite questa pratica nel giorno dato. E credetemi - vi risulterà molto più interessante, e questo intensivo vi porterà molto più beneficio. Alcune di queste pratiche possono sembrarvi più semplici, alcune più difficili. Alcune più pragmatiche, alcune più psicologiche. In ogni caso, non è come se vi avessi proposto di fare 20 squat. Qui lavoriamo con i vostri schemi comportamentali e psicologici. E la chiave del successo sta nel non combattere con voi stessi, nel non provocare ulteriore tensione interiore, ma, come nelle asana, respirare e rilassarvi. Perciò la pratica suona morbida - come «consiglio del giorno» - per non attivare un segnale d''allarme. Leggete, provate su di voi, provate durante la giornata a seguire dolcemente questo consiglio o almeno a ricordarlo, provandolo di nuovo e tornando alla sensazione che lo state seguendo. Adattatevi ai nuovi stati... In alcuni casi una sola pratica del genere può protrarsi per diversi giorni o addirittura mesi, perché ne sentirete l''importanza e inizierete a introdurla nella vostra vita a livello di abitudine, cioè correggendo l''attuale omeostasi del sistema. E, sebbene io non abbia previsto un legame preciso tra le pratiche comportamentali e le pratiche yoga che propongo in una stessa lettera, potete comunque eseguire ogni pratica yoga nello stato che emerge quando percepite voi stessi come seguaci del mio consiglio. Tuttavia, questo non è affatto obbligatorio, poiché ciascuna di queste due pratiche è autosufficiente.<br>  <br><strong>4. Orario delle lezioni</strong><br> Ogni giorno a mezzanotte vi si aprirà una nuova pratica (quella precedente scomparirà, come il giorno passato). Grazie a questo approccio, non si accumulerà una palla di neve di pratiche non eseguite. Nell''arco delle ventiquattro ore potete scegliere qualsiasi momento conveniente per voi e fare pratica. Vi raccomando di praticare al mattino, per vivere la giornata nello stato ottenuto grazie alla pratica, e non andare a dormire. Percepite questo intensivo non come un''illusione informatica, ma come vita reale - in cui tutto ciò che è importante accade OGGI, e la pratica yoga si espande dal tappetino allo spazio della vostra manifestazione in quel mondo che percepite come il più reale!</p><p></p><p></p><p>A proposito, c''è una piccola sfumatura riguardo al momento in cui riceverete la seconda pratica. Se vi siete iscritti prima delle 18:00, riceverete la seconda pratica alla mezzanotte più vicina. Se invece vi siete iscritti dopo le 18:00, riceverete la seconda pratica non alla mezzanotte più vicina, ma a quella successiva. Cioè avrete un margine di tempo nel caso non riusciate a completare la pratica nel giorno dell''iscrizione all''intensivo. <br>  <br><strong>5. Non fatevi violenza</strong><br> Quando acquistate un abbonamento mensile in un centro fitness, capite bene che non dovete per forza andarci ogni giorno? Inoltre, prendendo un ritmo troppo veloce, potete abbandonare le lezioni senza nemmeno arrivare alla fine del mese... Riguardo alle pratiche di questo intensivo vale la stessa regola - non siate avidi! Praticate al ritmo che vi è comodo - a giorni alterni, ogni due... Certo, è bene praticare ogni giorno, ma ancora meglio è capire i propri compiti a lungo termine e agire di conseguenza. Molto probabilmente i vostri compiti vanno oltre un mese, e avete bisogno di agire regolarmente per lungo tempo. Ho concepito questo intensivo in modo che possiate seguirlo mese dopo mese tutte le volte che serve, finché l''obiettivo che vi siete posti non sarà raggiunto. Questa strategia è più efficace che darci dentro per un mese e poi abbandonare le pratiche o lanciarsi in un''altra direzione.<br>  <br><strong>6. Tecnica di sicurezza</strong><br> Mi prendo cura della vostra salute e vi ricordo che solo voi siete responsabili dell''adeguatezza dell''esecuzione delle asana, dei pranayama e delle meditazioni che vi proporrò rispetto alle vostre possibilità fisiche e al vostro stato psichico. È importante capire che queste sono lezioni online e io non posso controllare il vostro stato. Potete avere particolarità fisiche e psicologiche. Per favore, siate attenti al vostro stato. Se sentite che qualche asana che vi propongo di eseguire è per voi prematura, eseguitela non molto profondamente, a un livello di compromesso, oppure sostituitela del tutto con un''altra asana - tale che coinvolga approssimativamente allo stesso modo il corpo, ma sia più semplice per voi.<br>  <br><strong>7. Risposte alle domande</strong><br> Ogni settimana (di solito il sabato) tengo su Zoom consultazioni online di gruppo (webinar), durante le quali comunichiamo, sosteniamo la motivazione, discutiamo le difficoltà e le domande che emergono. Prima di ciascuna di queste consultazioni vi invierò un''email con l''indicazione della data e dell''ora in cui si svolgerà, nonché il link per parteciparvi. Ciò che interessa a voi sarà sicuramente interessante anche per molti altri. Perciò, discutere le domande durante le consultazioni di gruppo è più efficace. Se accadesse che l''orario della consultazione non vi sia comodo, in questo caso inviate le vostre domande via email prima del suo inizio. Risponderò loro durante la consultazione, e vi invierò il link alla registrazione, così potrete guardarla nel momento per voi più comodo. Le registrazioni delle consultazioni vengono conservate per una settimana.<br> <br>Vi auguro pratiche fruttuose!</p><p></p><p>Sergej Zamkovoj</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"es":[{"id":"intensive-pleasure-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png","alt":"Интенсив «Наслаждения»","width":"100%","align":"center","naturalWidth":599,"naturalHeight":152,"marginTop":0,"marginBottom":24},{"id":"intensive-pleasure-1-text","type":"text","html":"<p>Hola, {{name}}!<br> <br>Me alegra que se haya decidido, durante un mes, a dirigir su atención y a trabajar de forma intencionada en el tema que une estados como: los placeres, la relajación, el gustazo, la juguetividad, el atractivo, la sexualidad… Parecería que son estados simples, accesibles para cualquiera. Sin embargo, en la sociedad operan muchos guiones, tanto incentivadores como prohibitivos, que gobiernan nuestra conducta. Realizando prácticas en la esterilla de yoga y en la vida, reflexionando, corrigiendo sus pensamientos y actos, a lo largo de un mes se pueden obtener resultados importantes que se manifestarán tanto a nivel del cuerpo (sanación) como a nivel del fondo psicológico (satisfacción y felicidad).</p><p></p><p></p><p> Durante este mes usted recibirá 30 prácticas dirigidas a armonizar la segunda chakra. Lea atentamente esta carta para entender qué y cómo sucederá. <br> <br><strong>1. La esencia misma</strong><br> Esto no es un curso de formación, sino un taller intensivo cuyo núcleo son las prácticas diarias de yoga. Estas prácticas las realizaba por las mañanas en directo, sincronizando la dirección de cada práctica con los ritmos planetarios de ese día. En este intensivo he reunido grabaciones de vídeo de las mejores prácticas, que estaban dirigidas precisamente al primer chakra (a veces en interacción con algún otro chakra), y las he complementado con prácticas conductuales (psicológicas). Como resultado, se ha obtenido una carga poderosísima para armonizar el ámbito de la salud. </p><p></p><p></p><p>Si usted no ha tomado mis cursos y no entiende qué tiene que ver aquí esa tal «segunda chakra», le recomiendo combinar la realización de este intensivo con un taller práctico o un curso en el que poco a poco voy conduciendo a la comprensión de aquello de lo que nos ocupamos aquí. Es importante no solo «creerme», sino abrir en usted la comprensión a través de la experiencia personal —tanto en la esterilla de yoga como en la vida—. Entonces las prácticas empiezan a funcionar mucho más profundamente. De lo contrario, obtenemos gimnasia, ya que esta es la comprensión (experiencia) básica del yoga que tiene cada persona. </p><p></p><p></p><p>Puede complementar este intensivo con los siguientes programas de estudio:<br> - Taller práctico «Mes de los placeres»: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> </p><p></p><p>- Curso «Yoga más feminidad»: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a>  <br>  <br><strong>2. Prácticas de yoga</strong><br> Las prácticas de yoga que le esperan se diferencian de lo que puede encontrar en un centro de fitness. Supongo que para usted es importante el resultado, y no el teatro. Trabajamos con estados internos (es decir, con energías), uniendo meditación, pranayama y asanas en la medida necesaria para obtener el resultado deseado al nivel más profundo posible. La mayoría de las prácticas comienzan con una breve introducción, necesaria para que su conciencia cambie de lo cotidiano a la onda de la práctica, entre en el flujo energético correspondiente y se active su intención interna. Después sigue la práctica en sí, que en distintos días tiene distinta duración y composición de elementos. Después de la práctica, le recomiendo permanecer un tiempo en meditación y, tal vez, en el estado de conciencia que haya surgido, continuar realizando las asanas que su cuerpo le pida. La duración media de las prácticas es de 30-40 minutos. Pero algunas prácticas son más cortas y otras duran cerca de una hora. Es importante que durante la práctica nada le distraiga ni le apresure. Y además es muy importante: una vez comenzada la práctica, ¡no la interrumpa hasta que termine!!! Cada práctica es una historia viva que le conduce por un camino determinado. Si interrumpe la práctica, puede encontrarse en un estado con menos recursos que aquel en el que estaba al comenzarla. Aunque ahora estas palabras le parezcan una mistificación y esoterismo vacío, haga caso a mis recomendaciones. <br>  <br><strong>3. Prácticas conductuales</strong><br> Cada día, en la carta, junto con la práctica de yoga, le enviaré el «consejo del día». Intente percibirlo no como una idea inteligente más, de las cuales ya ha oído muchas. No tengo el objetivo de sorprenderle diciendo algo que aún no haya oído. Perciba este «consejo» como una tarea, ¡como una práctica conductual! Realice esta práctica en el día indicado. Y créame: se sentirá mucho más interesado, y este intensivo le aportará mucho más beneficio. Algunas de estas prácticas pueden parecerle más fáciles, otras más difíciles. Algunas más pragmáticas, otras más psicológicas. En cualquier caso, no es como si le propusiera hacer 20 sentadillas. Aquí trabajamos con sus patrones conductuales y psicológicos. Y la clave del éxito está en no luchar contra uno mismo, no generar una tensión interna adicional, sino, como en las asanas, respirar y relajarse. Por eso la práctica suena suave, como «consejo del día», para no activar una señal de alarma. Léalo, pruébeselo, intente durante el día seguir suavemente este consejo o al menos recordarlo, probándoselo de nuevo y regresando a la sensación de que lo sigue. Adáptese a los nuevos estados... En algunos casos, una sola práctica así puede extenderse durante varios días o incluso meses, porque sentirá su importancia y comenzará a incorporarla a su vida a nivel de hábito, es decir, corrigiendo la homeostasis actual del sistema. Y, aunque no establecí una conexión clara entre las prácticas conductuales y las prácticas de yoga que propongo en una misma carta, aun así puede realizar cada práctica de yoga en el estado que surja cuando se percibe a sí mismo siguiendo mi consejo. Sin embargo, esto no es en absoluto obligatorio, ya que cada una de estas dos prácticas es autosuficiente.<br>  <br><strong>4. Horario de las clases</strong><br> Cada día, a medianoche, se le abrirá una nueva práctica (la anterior desaparecerá, como el día anterior). Gracias a este enfoque, no se le irá acumulando una bola de nieve de prácticas sin hacer. A lo largo del día puede elegir el momento que más le convenga y practicar. Le recomiendo practicar por la mañana, para vivir el día en el estado obtenido como resultado de la práctica, y no irse a dormir. Perciba este intensivo no como una ilusión informática, sino como la vida real, en la que todo lo importante ocurre HOY, y la práctica de yoga se expande desde la esterilla al espacio de su manifestación en el mundo que usted percibe como el más real.</p><p></p><p></p><p>Por cierto, hay un pequeño matiz con la hora de recepción de la segunda práctica. Si se inscribió antes de las 18:00, recibirá la segunda práctica en la próxima medianoche. Si se inscribió después de las 18:00, recibirá la segunda práctica no en la próxima medianoche, sino en la siguiente. Es decir, tendrá un margen de tiempo por si no logra realizar la práctica el día de la inscripción al intensivo. <br>  <br><strong>5. No se fuerce</strong><br> Cuando compra un abono mensual en un centro de fitness, entiende que no es obligatorio ir todos los días, ¿verdad? Además, si adopta un ritmo demasiado rápido, puede abandonar las clases sin haber llegado ni siquiera a fin de mes... Con las prácticas de este intensivo rige la misma regla: ¡no sea codicioso! Practique a un ritmo que le resulte cómodo: un día sí y otro no, cada dos días... Claro que es bueno practicar todos los días, pero aún mejor es comprender sus objetivos a largo plazo y actuar en consecuencia. Lo más probable es que sus objetivos vayan más allá de un mes, y necesite actuar con regularidad durante un tiempo prolongado. Concebí este intensivo para que pueda recorrerlo mes tras mes tantas veces como sea necesario, hasta que se alcance el objetivo que se ha propuesto. Esta estrategia es más eficaz que entregarse a tope durante un mes y luego abandonar las prácticas o lanzarse en otra dirección.<br>  <br><strong>6. Técnica de seguridad</strong><br> Me preocupo por su salud y le recuerdo que solo usted es responsable de la adecuación de la ejecución de las asanas, pranayamas y meditaciones que le propondré a sus posibilidades físicas y a su estado psíquico. Es importante comprender que son clases en línea, y no puedo controlar su estado. Usted puede tener particularidades físicas y psicológicas. Por favor, sea atento a su estado. Si siente que alguna asana que le propongo realizar es prematura para usted, ejecútela no muy profundamente, en un nivel de compromiso, o sustitúyala por completo por otra asana, una que incluya el cuerpo aproximadamente de la misma manera pero que le resulte más sencilla.<br>  <br><strong>7. Respuestas a las preguntas</strong><br> Cada semana (normalmente los sábados) realizo en Zoom consultas grupales en línea (webinars), en las que conversamos, mantenemos la motivación y discutimos las dificultades y preguntas que surgen. Antes de cada una de estas consultas le enviaré una carta con la fecha y la hora de su realización, así como un enlace para unirse a ella. Lo que es interesante para usted seguramente también lo será para muchas otras personas. Por eso, la discusión de preguntas en las consultas grupales es lo más eficaz. Si ocurre que la hora de la consulta le resulta inconveniente, en ese caso envíe sus preguntas por correo electrónico antes de su comienzo. Las responderé en la consulta y le enviaré un enlace a la grabación para que pueda verla en el momento que le resulte cómodo. Las grabaciones de las consultas se conservan durante una semana.<br> <br>¡Le deseo prácticas fructíferas!</p><p></p><p>Serguéi Zamkovói</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"pt":[{"id":"intensive-pleasure-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png","alt":"Интенсив «Наслаждения»","width":"100%","align":"center","naturalWidth":599,"naturalHeight":152,"marginTop":0,"marginBottom":24},{"id":"intensive-pleasure-1-text","type":"text","html":"<p>Olá, {{name}}!<br> <br>Fico feliz que você tenha decidido, ao longo de um mês, direcionar sua atenção e trabalhar intencionalmente o tema que reúne estados como: prazeres, relaxamento, gostosura, ludicidade, atratividade, sexualidade... Parecem ser estados simples, acessíveis a qualquer pessoa. No entanto, na sociedade atuam muitos roteiros tanto incentivadores quanto proibitivos, que governam nosso comportamento. Praticando no tapete de yoga e na vida, refletindo, corrigindo seus pensamentos e atitudes, ao longo de um mês é possível obter resultados importantes, que se manifestarão tanto no nível do corpo (melhora da saúde) quanto no nível do fundo psicológico (satisfação e felicidade).</p><p></p><p></p><p> Ao longo deste mês você receberá 30 práticas voltadas para a harmonização do segundo chakra. Leia esta carta com atenção para entender o que e como vai acontecer. <br> <br><strong>1. A própria essência</strong><br> Este não é um curso de estudo, mas um praticum intensivo, cujo núcleo são as práticas diárias de yoga. Eu conduzia essas práticas pela manhã ao vivo, sincronizando a direção de cada prática com os ritmos planetários daquele dia. Neste intensivo, reuni gravações em vídeo das melhores práticas que eram direcionadas justamente ao primeiro chakra (às vezes em interação com algum outro chakra), e as complementei com práticas comportamentais (psicológicas). O resultado foi uma carga poderosíssima para harmonizar a esfera da saúde. </p><p></p><p></p><p>Se você não fez meus cursos e não entende o que tem a ver com isso algum «segundo chakra», eu recomendo combinar a realização deste intensivo com um workshop ou curso no qual eu conduzo suavemente à compreensão do que estamos fazendo aqui. É importante não apenas «acreditar» em mim, mas despertar em si a compreensão por meio da experiência pessoal - tanto no tapete de yoga quanto na vida. Então as práticas começam a funcionar muito mais profundamente. Caso contrário, obtemos ginástica - já que essa é a compreensão (experiência) básica do yoga que todos têm. </p><p></p><p></p><p>Você pode complementar este intensivo com os seguintes programas de estudo:<br> - Workshop «Mês dos prazeres»: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> </p><p></p><p>- Curso «Yoga mais feminilidade»: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a>  <br>  <br><strong>2. Práticas de yoga</strong><br> As práticas de yoga que você terá pela frente diferem daquilo que você pode encontrar em uma academia de ginástica. Presumo que para você o resultado é importante, e não a teatralidade. Trabalhamos com estados internos (ou seja, com energias), unindo meditação, pranayama e asanas na medida necessária para obter o resultado desejado no nível mais profundo possível. A maioria das práticas começa com uma pequena introdução, necessária para que sua consciência se desligue da cotidianidade e entre na onda da prática, você entre no fluxo energético correspondente e sua intenção interna se ative. Em seguida vem a própria prática, que em dias diferentes tem duração e composição de elementos diferentes. Depois da prática, recomendo que você fique algum tempo em meditação e, talvez, no estado de consciência que surgir, continue executando as asanas que seu corpo pedir. A duração média das práticas é de 30 a 40 minutos. Mas algumas práticas são mais curtas, e algumas duram cerca de uma hora. É importante que durante a prática nada o distraia nem o apresse. E é ainda muito importante - tendo começado a prática, não a interrompa até o final!!! Cada prática é uma história viva que o conduz por um determinado caminho. Se interromper a prática, você pode acabar em um estado com menos recursos do que aquele em que estava no início dela. Mesmo que agora estas palavras lhe pareçam mistificação e esoterismo vazio, escute minhas recomendações. <br>  <br><strong>3. Práticas comportamentais</strong><br> Todos os dias, no e-mail, junto com a prática de yoga, enviarei a você o «conselho do dia». Tente não percebê-lo como mais um pensamento inteligente, semelhante aos que você já ouviu muitas vezes. Não tenho o objetivo de surpreendê-lo dizendo algo que você ainda não ouviu. Perceba esse «conselho» como uma tarefa, como uma prática comportamental! Execute essa prática no dia em questão. E acredite - vai se tornar muito mais interessante para você, e este intensivo lhe trará muito mais benefício. Algumas dessas práticas podem parecer-lhe mais simples, outras mais difíceis. Algumas mais pragmáticas, outras mais psicológicas. Em qualquer caso, não é como se eu tivesse proposto a você agachar 20 vezes. Aqui trabalhamos com seus padrões comportamentais e psicológicos. E a chave do sucesso está em não lutar consigo mesmo, não provocar tensão interna adicional, mas, como nas asanas, respirar e relaxar. Por isso a prática soa suave - como «conselho do dia» - para não provocar o sinal de alarme. Leia, experimente, tente ao longo do dia seguir suavemente esse conselho ou ao menos lembrar dele, experimentando-o de novo e retornando à sensação de que o está seguindo. Adapte-se aos novos estados... Em alguns casos, uma dessas práticas pode se estender por vários dias ou até meses, porque você sentirá sua importância e começará a introduzi-la em sua vida no nível do hábito, ou seja, corrigindo a homeostase atual do sistema. E, embora eu não tenha estabelecido uma ligação clara entre as práticas comportamentais e as práticas de yoga que proponho em um mesmo e-mail, ainda assim você pode executar cada prática de yoga no estado que surgir quando você se percebe seguindo meu conselho. No entanto, isso não é de modo algum obrigatório, pois cada uma dessas duas práticas é autossuficiente.<br>  <br><strong>4. Horário das aulas</strong><br> Todos os dias, à meia-noite, uma nova prática será aberta para você (a anterior desaparecerá, como o dia anterior). Graças a essa abordagem, não se acumulará em você uma bola de neve de práticas não realizadas. Ao longo do dia, você pode escolher o horário que lhe for conveniente e praticar. Recomendo que você pratique pela manhã, para viver o dia no estado obtido como resultado da prática, e não para ir dormir. Perceba este intensivo não como uma ilusão de computador, mas como a vida real - na qual tudo o que é importante acontece HOJE, e a prática de yoga se expande do tapete para o espaço da sua manifestação naquele mundo que você percebe como o mais real!</p><p></p><p></p><p>A propósito, há um pequeno detalhe com o horário de recebimento da segunda prática. Se você se inscreveu antes das 18:00, receberá a segunda prática na próxima meia-noite. Mas se se inscreveu depois das 18:00, receberá a segunda prática não na próxima meia-noite, mas na meia-noite seguinte. Ou seja, você terá uma reserva de tempo caso não consiga realizar a prática no dia da inscrição no intensivo. <br>  <br><strong>5. Não se force</strong><br> Quando você compra uma mensalidade em uma academia, você entende que não precisa ir lá todos os dias, certo? Mais do que isso, se pegar um ritmo rápido demais, você pode abandonar os treinos antes mesmo do fim do mês... Em relação às práticas deste intensivo, vale a mesma regra - não seja ganancioso! Pratique no ritmo que lhe for conveniente - um dia sim, dois não... Claro, é bom praticar todos os dias, mas ainda melhor é entender suas tarefas de longo prazo e agir de acordo. Muito provavelmente, suas tarefas vão além de um mês, e você precisa agir regularmente por um longo tempo. Concebi este intensivo de modo que você possa percorrê-lo mês após mês, quantas vezes for necessário, até que o objetivo que você estabeleceu seja alcançado. Essa estratégia é mais eficaz do que se entregar a fundo por um mês e depois abandonar as práticas ou partir para outra direção.<br>  <br><strong>6. Técnica de segurança</strong><br> Eu me preocupo com sua saúde e lembro que somente você é responsável pela adequação da execução das asanas, pranayamas e meditações que eu proporei às suas possibilidades físicas e ao seu estado psíquico. É importante entender que estas são aulas on-line, e eu não posso controlar seu estado. Você pode ter particularidades físicas e psicológicas. Por favor, esteja atento ao seu estado. Se você sentir que alguma asana que proponho executar é prematura para você, execute-a não muito profundamente, em um nível de meio-termo, ou substitua-a totalmente por outra asana - que envolva o corpo de modo aproximadamente semelhante, mas seja mais simples para você.<br>  <br><strong>7. Respostas às perguntas</strong><br> Toda semana (normalmente aos sábados) realizo no Zoom consultorias on-line em grupo (webinars), nas quais conversamos, mantemos a motivação, discutimos as dificuldades e dúvidas que surgem. Antes de cada consultoria dessas, enviarei a você um e-mail com a data e o horário de sua realização, bem como o link para se juntar a ela. O que é interessante para você certamente também será interessante para muitas outras pessoas. Por isso, discutir as questões nas consultorias em grupo é o mais eficaz. Se acontecer de o horário da consultoria ser inconveniente para você, nesse caso envie suas perguntas por e-mail antes de ela começar. Eu responderei a elas na consultoria e enviarei a você o link da gravação, para que possa assisti-la no horário que lhe for conveniente. As gravações das consultorias ficam salvas por uma semana.<br> <br>Desejo a você práticas frutíferas!</p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"nl":[{"id":"intensive-pleasure-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png","alt":"Интенсив «Наслаждения»","width":"100%","align":"center","naturalWidth":599,"naturalHeight":152,"marginTop":0,"marginBottom":24},{"id":"intensive-pleasure-1-text","type":"text","html":"<p>Hallo, {{name}}!<br> <br>Ik ben blij dat je besloten hebt om een maand lang je aandacht te richten en gericht te werken aan het thema dat staten verenigt als: genietingen, ontspanning, heerlijkheid, speelsheid, aantrekkelijkheid, seksualiteit... Het lijken misschien eenvoudige, voor iedereen toegankelijke toestanden. In de samenleving werken echter veel zowel stimulerende als verbiedende scenario''s die ons gedrag sturen. Door praktijken op de yogamat en in het leven uit te voeren, na te denken en je gedachten en daden bij te sturen, kun je in een maand belangrijke resultaten behalen, die zich zowel op lichaamsniveau (gezond worden) als op het niveau van de psychologische gesteldheid (tevredenheid en geluk) manifesteren.</p><p></p><p></p><p> Deze maand ontvang je 30 praktijken gericht op het harmoniseren van de tweede chakra. Lees deze e-mail aandachtig, zodat je begrijpt wat er gaat gebeuren en hoe. <br> <br><strong>1. De kern</strong><br> Dit is geen leercursus, maar een intensieve praktijk, waarvan de dagelijkse yogapraktijken de kern vormen. Deze praktijken gaf ik ''s ochtends live, waarbij ik de richting van elke praktijk afstemde op de planetaire ritmen van die dag. In dit intensief heb ik video-opnamen verzameld van de beste praktijken die juist op de eerste chakra waren gericht (soms in wisselwerking met een andere chakra), en deze aangevuld met gedragsmatige (psychologische) praktijken. Het resultaat is een uiterst krachtige impuls voor het harmoniseren van het gebied van gezondheid. </p><p></p><p></p><p>Als je mijn cursussen niet hebt gevolgd en niet begrijpt wat een of andere «tweede chakra» hier mee te maken heeft, raad ik je aan dit intensief te combineren met een practicum of cursus waarin ik je geleidelijk tot begrip breng van wat we hier doen. Het is belangrijk om mij niet alleen maar «te geloven», maar in jezelf begrip te openen via persoonlijke ervaring - zowel op de yogamat als in het leven. Dan gaan de praktijken veel dieper werken. Anders krijgen we gymnastiek - omdat dit het basisbegrip (de ervaring) van yoga is die iedereen heeft. </p><p></p><p></p><p>Je kunt dit intensief aanvullen met de volgende studieprogramma''s:<br> - Practicum «Maand van genietingen»: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a> </p><p></p><p>- Cursus «Yoga plus vrouwelijkheid»: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a>  <br>  <br><strong>2. Yogapraktijken</strong><br> Yogapraktijken die u te wachten staan, verschillen van wat u in een fitnesscentrum kunt tegenkomen. Ik ga ervan uit dat het u om het resultaat gaat, en niet om toneelspel. We werken met innerlijke toestanden (dat wil zeggen met energieën), waarbij ik meditatie, pranayama en asana''s verbind voor zover dat nodig is om het gewenste resultaat op een zo diep mogelijk niveau te bereiken. De meeste praktijken beginnen met een korte inleiding, die nodig is opdat uw bewustzijn van de alledaagsheid overschakelt naar de golf van de praktijk, u in de bijbehorende energetische stroom komt en uw innerlijke intentie wordt geactiveerd. Daarna volgt de praktijk zelf, die op verschillende dagen een verschillende duur en samenstelling van elementen heeft. Na de praktijk raad ik u aan enige tijd in meditatie te blijven, of misschien in de ontstane staat van bewustzijn door te gaan met het uitvoeren van de asana''s die uw lichaam zal vragen. De gemiddelde duur van de praktijken is 30-40 minuten. Maar sommige praktijken zijn korter, en sommige duren ongeveer een uur. Het is belangrijk dat niets u tijdens de praktijk afleidt en dat niets u opjaagt. En heel belangrijk: als u eenmaal aan de praktijk bent begonnen, onderbreek deze dan niet tot het einde!!! Elke praktijk is een levend verhaal dat u langs een bepaald pad leidt. Als u de praktijk onderbreekt, kunt u in een minder veerkrachtige toestand terechtkomen dan aan het begin ervan. Zelfs als deze woorden u nu als mystificatie en lege esoterie voorkomen, luister naar mijn aanbevelingen. <br>  <br><strong>3. Gedragspraktijken</strong><br> Elke dag zal ik u in de brief samen met de yogapraktijk een «advies van de dag» sturen. Probeer het niet te zien als nog een slimme gedachte, waarvan u er al vele malen soortgelijke hebt gehoord. Het is niet mijn doel u te verrassen door iets te zeggen wat u nog niet hebt gehoord. Zie dit «advies» als een opdracht, als een gedragspraktijk! Voer deze praktijk op die dag uit. En geloof me - het zal veel interessanter voor u worden, en dit intensief zal u veel meer nut brengen. Sommige van zulke praktijken kunnen u eenvoudiger lijken, sommige moeilijker. Sommige pragmatischer, sommige psychologischer. In ieder geval is het niet alsof ik u heb voorgesteld twintig keer te hurken. Hier werken we met uw gedragsmatige en psychologische patronen. En de sleutel tot succes is om niet met uzelf te vechten, geen extra innerlijke spanning op te roepen, maar zoals in de asana''s - te ademen en te ontspannen. Daarom klinkt de praktijk zacht - als &quot;advies van de dag&quot; - om geen alarmsignaal op te roepen. Lees het, pas het op uzelf toe, probeer dit advies gedurende de dag zachtjes te volgen of er ten minste aan te denken, het opnieuw toe te passen en terug te keren naar het gevoel dat u het volgt. Pas u aan de nieuwe toestanden aan... In sommige gevallen kan één zo''n praktijk zich over meerdere dagen of zelfs maanden uitstrekken, omdat u het belang ervan zult voelen, en het in uw leven op het niveau van een gewoonte zult gaan invoeren, dat wil zeggen door de huidige homeostase van het systeem bij te stellen. En hoewel ik geen duidelijke verbinding heb aangelegd tussen de gedragspraktijken en de yogapraktijken die ik in één brief aanbied, kunt u toch elke yogapraktijk uitvoeren in de toestand die ontstaat wanneer u zichzelf ziet als iemand die mijn advies volgt. Dat is echter helemaal niet verplicht, omdat elk van deze twee praktijken op zichzelf voldoende is.<br>  <br><strong>4. Lesschema</strong><br> Elke dag om middernacht gaat er een nieuwe praktijk voor u open (de vorige verdwijnt daarbij, zoals de vorige dag). Dankzij deze aanpak zal er bij u geen sneeuwbal van niet-uitgevoerde praktijken ontstaan. Binnen een etmaal kunt u een voor u geschikt tijdstip kiezen en oefenen. Ik raad u aan ''s ochtends te oefenen, zodat u de dag kunt doorbrengen in de toestand die u door de praktijk hebt verkregen, in plaats van naar bed te gaan. Zie dit intensief niet als een computerillusie, maar als het echte leven - waarin alles wat belangrijk is VANDAAG gebeurt, en de yogapraktijk zich van de mat uitbreidt naar de ruimte van uw manifestatie in die wereld die u als de meest werkelijke ervaart!</p><p></p><p></p><p>Trouwens, er is een kleine nuance met betrekking tot de tijd waarop u de tweede praktijk ontvangt. Als u zich vóór 18:00 hebt ingeschreven, ontvangt u de tweede praktijk bij de eerstvolgende middernacht. Als u zich na 18:00 hebt ingeschreven, ontvangt u de tweede praktijk niet bij de eerstvolgende, maar bij de daaropvolgende middernacht. Dat wil zeggen dat u extra tijd hebt voor het geval u er niet aan toe komt de praktijk uit te voeren op de dag van inschrijving voor het intensief. <br>  <br><strong>5. Doe uzelf geen geweld aan</strong><br> Wanneer u een maandabonnement bij een fitnesscentrum koopt, begrijpt u toch dat u er niet elke dag heen hoeft? Sterker nog, als u een te snel tempo aanneemt, kunt u de lessen laten vallen nog voordat u zelfs maar het einde van de maand hebt bereikt... Voor de praktijken van dit intensief geldt dezelfde regel - wees niet hebberig! Oefen in een tempo dat u bevalt - om de dag, om de twee dagen... Natuurlijk is het goed om elke dag te oefenen, maar nog beter is - uw langetermijntaken te begrijpen en dienovereenkomstig te handelen. Waarschijnlijk gaan uw taken verder dan één maand, en moet u langdurig regelmatig in actie komen. Dit intensief heb ik zo bedacht dat u het maand na maand kunt doorlopen, zo vaak als nodig, totdat het door u gestelde doel is bereikt. Deze strategie is effectiever dan één maand er flink tegenaan te gaan en daarna de praktijken te laten vallen of in een andere richting te schieten.<br>  <br><strong>6. Veiligheidstechniek</strong><br> Ik geef om uw gezondheid en herinner u eraan dat alleen u verantwoordelijk bent voor of de uitvoering van de asana''s, pranayama''s en meditaties die ik zal aanbieden adequaat is voor uw lichamelijke mogelijkheden en psychische toestand. Het is belangrijk te begrijpen dat dit online lessen zijn, en dat ik uw toestand niet kan controleren. U kunt lichamelijke en psychologische bijzonderheden hebben. Wees alstublieft aandachtig voor uw eigen toestand. Als u merkt dat een bepaalde asana die ik voorstel uit te voeren voor u voortijdig is, voer haar dan niet erg diep uit, op een compromisniveau, of vervang haar helemaal door een andere asana - een die ongeveer ook het lichaam betrekt, maar eenvoudiger voor u is.<br>  <br><strong>7. Antwoorden op vragen</strong><br> Elke week (meestal op zaterdag) geef ik in Zoom groepsgewijze onlineconsulten (webinars), waarin we met elkaar praten, de motivatie ondersteunen en opkomende moeilijkheden en vragen bespreken. Voor elk zo''n consult stuur ik u een bericht met de datum en tijd waarop het plaatsvindt, evenals een link om eraan deel te nemen. Wat voor u interessant is, zal zeker ook voor velen anderen interessant zijn. Daarom is het bespreken van vragen in groepsconsulten het meest effectief. Als het zo uitkomt dat het tijdstip van het consult u niet uitkomt, stuur uw vragen dan vóór het begin per e-mail. Ik zal ze tijdens het consult beantwoorden, en u stuur ik een link naar de opname, zodat u deze op een voor u geschikt moment kunt bekijken. Opnamen van consulten worden gedurende één week bewaard.<br> <br>Ik wens u vruchtbare praktijken!</p><p></p><p>Sergey Zamkovoy</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('085569cb-1cda-5e45-affe-4f98482e70a9','1dfe9e9e-a458-5a4a-b8ce-0b90014a21a1','Заключительное письмо',2,0,'{Интенсив Наслаждения} Что дальше?','{"ru":"{Интенсив Наслаждения} Что дальше?","en":"{Pleasures Intensive} What next?","de":"{Интенсив Наслаждения} Was kommt als Nächstes?","fr":"{Интенсив Наслаждения} Et ensuite ?","it":"{Intensivo Piacere} E adesso?","es":"{Интенсив Наслаждения} ¿Qué sigue?","pt":"{Intensivo Prazeres} O que vem a seguir?","nl":"{Интенсив Наслаждения} Wat nu?"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png" alt="Интенсив «Наслаждения»" width="504" height="128" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!<br> <br>Вот и подошёл к концу месяц практик, направленных на гармонизацию второй чакры. Я надеюсь, что вы регулярно занимались, и получили плоды в виде расширения пространства удовольствий, большей расслабленности, кайфушности. Возможно, ваша жизнь заиграла новыми красками. Может быть даже в плане здоровья что-то изменилось в лучшую сторону… И сейчас я предлагаю вам не терять волну и продолжить практики! В течение многих лет вы укрепляли определенный образ мыслей, ценностей, привычек, психологических клише, и сейчас вы лишь начали от всего этого освобождаться, шаг за шагом открывая кто же вы есть на самом деле. Продолжение движения в этом направлении, безусловно, даст вам более глубокие результаты.</p><p></p><p> Чтобы вновь записаться на этот интенсив, перейдите по ссылке - <a href="https://zamkovoi.yoga/i2">https://zamkovoi.yoga/i2</a> <br> <br>Если же вы чувствуете, что хотите сменить направление, то ознакомьтесь с другими моими практикумами и курсами. <br> <br>ПРАКТИКУМЫ:<br> - Месяц здоровья: <a href="https://zamkovoi.yoga/m1">https://zamkovoi.yoga/m1</a><br> - Месяц наслаждений: <a href="https://zamkovoi.yoga/m2">https://zamkovoi.yoga/m2</a><br> - Месяц силы: <a href="https://zamkovoi.yoga/m3">https://zamkovoi.yoga/m3</a><br> - Месяц любви: <a href="https://zamkovoi.yoga/m4">https://zamkovoi.yoga/m4</a><br> - Месяц свободы: <a href="https://zamkovoi.yoga/m5">https://zamkovoi.yoga/m5</a><br> - Месяц мудрости: <a href="https://zamkovoi.yoga/m6">https://zamkovoi.yoga/m6</a><br> - Месяц святости: <a href="https://zamkovoi.yoga/m7">https://zamkovoi.yoga/m7</a><br> <br>КУРСЫ:<br> - Йога и здоровье: <a href="https://zamkovoi.yoga/yoga1">https://zamkovoi.yoga/yoga1</a><br> - Йога и женственность: <a href="https://zamkovoi.yoga/yoga2">https://zamkovoi.yoga/yoga2</a><br> - Тантра - мистерия взаимоотношений: <a href="https://zamkovoi.yoga/tantra12">https://zamkovoi.yoga/tantra12</a><br> - Осуществи мечту: <a href="https://zamkovoi.yoga/yoga3">https://zamkovoi.yoga/yoga3</a><br> - Планета любви: <a href="https://zamkovoi.yoga/yoga4">https://zamkovoi.yoga/yoga4</a><br> - Источник творческой силы: <a href="https://zamkovoi.yoga/yoga5">https://zamkovoi.yoga/yoga5</a><br> - 36 шагов йоги: <a href="https://zamkovoi.yoga/yoga36">https://zamkovoi.yoga/yoga36</a><br> - Путь души: <a href="https://zamkovoi.yoga/yogas">https://zamkovoi.yoga/yogas</a><br> <br>Всех благ!<br> Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png\" alt=\"Интенсив «Наслаждения»\" width=\"504\" height=\"128\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!<br> <br>Вот и подошёл к концу месяц практик, направленных на гармонизацию второй чакры. Я надеюсь, что вы регулярно занимались, и получили плоды в виде расширения пространства удовольствий, большей расслабленности, кайфушности. Возможно, ваша жизнь заиграла новыми красками. Может быть даже в плане здоровья что-то изменилось в лучшую сторону… И сейчас я предлагаю вам не терять волну и продолжить практики! В течение многих лет вы укрепляли определенный образ мыслей, ценностей, привычек, психологических клише, и сейчас вы лишь начали от всего этого освобождаться, шаг за шагом открывая кто же вы есть на самом деле. Продолжение движения в этом направлении, безусловно, даст вам более глубокие результаты.</p><p></p><p> Чтобы вновь записаться на этот интенсив, перейдите по ссылке - <a href=\"https://zamkovoi.yoga/i2\">https://zamkovoi.yoga/i2</a> <br> <br>Если же вы чувствуете, что хотите сменить направление, то ознакомьтесь с другими моими практикумами и курсами. <br> <br>ПРАКТИКУМЫ:<br> - Месяц здоровья: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Месяц наслаждений: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Месяц силы: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Месяц любви: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Месяц свободы: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Месяц мудрости: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Месяц святости: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>КУРСЫ:<br> - Йога и здоровье: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Йога и женственность: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Тантра - мистерия взаимоотношений: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Осуществи мечту: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Планета любви: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Источник творческой силы: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 шагов йоги: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Путь души: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Всех благ!<br> Сергей Замковой</p>","en":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png\" alt=\"Интенсив «Наслаждения»\" width=\"504\" height=\"128\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hello, {{name}}!<br> <br>So the month of practices aimed at harmonizing the second chakra has come to an end. I hope that you practiced regularly and received fruits in the form of an expanded space of pleasures, greater relaxation, blissfulness. Perhaps your life has begun to play with new colors. Maybe even in terms of health something has changed for the better… And now I invite you not to lose the wave and continue the practices! For many years you have strengthened a certain way of thinking, values, habits, psychological clichés, and now you have only begun to free yourself from all of this, step by step discovering who you really are. Continuing to move in this direction will, of course, give you deeper results.</p><p></p><p> To sign up for this intensive again, follow the link - <a href=\"https://zamkovoi.yoga/i2\">https://zamkovoi.yoga/i2</a> <br> <br>If you feel that you want to change direction, then take a look at my other workshops and courses. <br> <br>WORKSHOPS:<br> - Month of Health: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Month of Pleasures: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Month of Strength: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Month of Love: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Month of Freedom: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Month of Wisdom: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Month of Holiness: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>COURSES:<br> - Yoga and Health: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga and Femininity: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - the mystery of relationships: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Fulfill the Dream: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planet of Love: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Source of Creative Power: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 Steps of Yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Path of the Soul: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>All the best!<br> Sergey Zamkovoy</p>","de":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png\" alt=\"Интенсив «Наслаждения»\" width=\"504\" height=\"128\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Guten Tag, {{name}}!<br> <br>Nun ist der Monat der Praktiken, die auf die Harmonisierung des zweiten Chakras ausgerichtet waren, zu Ende gegangen. Ich hoffe, dass Sie regelmäßig praktiziert und Früchte erhalten haben – in Form einer Erweiterung des Raums der Genüsse, größerer Entspannung, mehr Rauschhaftigkeit. Vielleicht hat Ihr Leben in neuen Farben zu spielen begonnen. Möglicherweise hat sich sogar in gesundheitlicher Hinsicht etwas zum Besseren verändert … Und jetzt schlage ich Ihnen vor, die Welle nicht zu verlieren und mit den Praktiken fortzufahren! Viele Jahre lang haben Sie eine bestimmte Denkweise, Werte, Gewohnheiten, psychologische Klischees gefestigt, und jetzt haben Sie erst begonnen, sich von all dem zu befreien, Schritt für Schritt zu entdecken, wer Sie wirklich sind. Die Fortsetzung der Bewegung in diese Richtung wird Ihnen zweifellos tiefere Ergebnisse bringen.</p><p></p><p> Um sich erneut für diesen Intensivkurs anzumelden, folgen Sie dem Link - <a href=\"https://zamkovoi.yoga/i2\">https://zamkovoi.yoga/i2</a> <br> <br>Wenn Sie jedoch das Gefühl haben, die Richtung wechseln zu wollen, dann machen Sie sich mit meinen anderen Praktika und Kursen vertraut. <br> <br>PRAKTIKA:<br> - Monat der Gesundheit: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Monat der Genüsse: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Monat der Kraft: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Monat der Liebe: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Monat der Freiheit: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Monat der Weisheit: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Monat der Heiligkeit: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>KURSE:<br> - Yoga und Gesundheit: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga und Weiblichkeit: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - Mysterium der Beziehungen: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Verwirkliche den Traum: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planet der Liebe: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Quelle schöpferischer Kraft: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 Schritte des Yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Weg der Seele: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Alles Gute!<br> Sergej Zamkovoi</p>","fr":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png\" alt=\"Интенсив «Наслаждения»\" width=\"504\" height=\"128\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Bonjour, {{name}} !<br> <br>Voilà, le mois de pratiques visant à harmoniser le deuxième chakra est arrivé à son terme. J’espère que vous avez pratiqué régulièrement et que vous avez obtenu des fruits sous forme d’élargissement de l’espace des plaisirs, d’une plus grande relaxation, d’un plus grand kiff. Peut-être votre vie s’est-elle mise à scintiller de nouvelles couleurs. Peut-être même que, sur le plan de la santé, quelque chose a changé pour le mieux… Et maintenant, je vous propose de ne pas perdre la vague et de poursuivre les pratiques ! Pendant de nombreuses années, vous avez renforcé une certaine manière de penser, des valeurs, des habitudes, des clichés psychologiques, et maintenant vous avez seulement commencé à vous en libérer, ouvrant pas à pas qui vous êtes réellement. La poursuite du mouvement dans cette direction vous apportera, sans aucun doute, des résultats plus profonds.</p><p></p><p> Pour vous réinscrire à cet intensif, suivez le lien - <a href=\"https://zamkovoi.yoga/i2\">https://zamkovoi.yoga/i2</a> <br> <br>Si toutefois vous sentez que vous voulez changer de direction, alors prenez connaissance de mes autres ateliers et cours. <br> <br>ATELIERS :<br> - Mois de la santé : <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mois des plaisirs : <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mois de la force : <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mois de l’amour : <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mois de la liberté : <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mois de la sagesse : <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mois de la sainteté : <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>COURS :<br> - Yoga et santé: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga et féminité: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mystère des relations: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Réalise ton rêve: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planète de l''amour: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Source de force créatrice: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 pas de yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Chemin de l''âme: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Toutes les bénédictions !<br> Sergueï Zamkovoï</p>","it":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png\" alt=\"Интенсив «Наслаждения»\" width=\"504\" height=\"128\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Salve, {{name}}!<br> <br>Ecco che è giunto al termine il mese di pratiche volte ad armonizzare il secondo chakra. Spero che vi siate esercitati regolarmente e che abbiate ottenuto frutti sotto forma di ampliamento dello spazio dei piaceri, maggiore rilassatezza, goduria. Forse la vostra vita ha iniziato a risplendere di nuovi colori. Magari anche sul piano della salute qualcosa è cambiato in meglio… E ora vi propongo di non perdere l’onda e di continuare le pratiche! Per molti anni avete consolidato un certo modo di pensare, valori, abitudini, cliché psicologici, e ora avete solo iniziato a liberarvi di tutto questo, aprendo passo dopo passo chi siete davvero. Continuare il movimento in questa direzione, senza dubbio, vi darà risultati più profondi.</p><p></p><p> Per iscrivervi di nuovo a questo intensivo, seguite il link - <a href=\"https://zamkovoi.yoga/i2\">https://zamkovoi.yoga/i2</a> <br> <br>Se invece sentite di voler cambiare direzione, allora date un''occhiata agli altri miei praticum e corsi. <br> <br>PRATICUM:<br> - Mese della salute: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mese dei piaceri: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mese della forza: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mese dell''amore: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mese della libertà: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mese della saggezza: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mese della santità: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CORSI:<br> - Yoga e salute: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga e femminilità: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mistero delle relazioni: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Realizza il sogno: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Pianeta dell''amore: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fonte di forza creativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 passi di yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Il cammino dell''anima: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Ogni bene!<br> Sergej Zamkovoj</p>","es":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png\" alt=\"Интенсив «Наслаждения»\" width=\"504\" height=\"128\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hola, {{name}}!<br> <br>Así ha llegado a su fin el mes de prácticas dirigidas a armonizar la segunda chakra. Espero que usted haya practicado con regularidad y haya obtenido frutos en forma de ampliación del espacio de los placeres, mayor relajación, gustazo. Quizá su vida haya empezado a brillar con nuevos colores. Puede que incluso, en cuanto a la salud, algo haya cambiado para mejor… Y ahora le propongo no perder la ola y continuar con las prácticas. Durante muchos años usted ha fortalecido una determinada forma de pensar, valores, hábitos, clichés psicológicos, y ahora solo ha comenzado a liberarse de todo ello, abriendo paso a paso quién es usted en realidad. La continuación del movimiento en esta dirección, sin duda, le dará resultados más profundos.</p><p></p><p> Para inscribirse de nuevo en este intensivo, vaya al enlace - <a href=\"https://zamkovoi.yoga/i2\">https://zamkovoi.yoga/i2</a> <br> <br>Si siente que quiere cambiar de dirección, eche un vistazo a mis otros talleres y cursos. <br> <br>TALLERES:<br> - Mes de la salud: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mes de los placeres: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mes de la fuerza: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mes del amor: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mes de la libertad: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mes de la sabiduría: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mes de la santidad: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSOS:<br> - Yoga y salud: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga y feminidad: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - misterio de las relaciones: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Haz realidad tu sueño: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeta del amor: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fuente de la fuerza creativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 pasos del yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Camino del alma: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>¡Todo lo mejor!<br> Serguéi Zamkovói</p>","pt":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png\" alt=\"Интенсив «Наслаждения»\" width=\"504\" height=\"128\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Olá, {{name}}!<br> <br>Chegou ao fim o mês de práticas voltadas para a harmonização do segundo chakra. Espero que você tenha praticado regularmente e colhido frutos na forma de ampliação do espaço dos prazeres, de maior relaxamento, de gostosura. Talvez sua vida tenha ganhado novas cores. Talvez até na questão da saúde algo tenha mudado para melhor… E agora eu proponho que você não perca a onda e continue as práticas! Durante muitos anos você fortaleceu um determinado modo de pensar, valores, hábitos, clichês psicológicos, e agora você apenas começou a se libertar de tudo isso, passo a passo descobrindo quem você realmente é. A continuação do movimento nessa direção, sem dúvida, dará a você resultados mais profundos.</p><p></p><p> Para se inscrever novamente neste intensivo, acesse o link - <a href=\"https://zamkovoi.yoga/i2\">https://zamkovoi.yoga/i2</a> <br> <br>Se, porém, você sente que quer mudar de direção, conheça meus outros praticuns e cursos. <br> <br>PRATICUNS:<br> - Mês da saúde: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mês dos prazeres: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mês da força: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mês do amor: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mês da liberdade: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mês da sabedoria: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mês da santidade: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSOS:<br> - Yoga e saúde: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga e feminilidade: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mistério das relações: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Realize o sonho: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeta do amor: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fonte da força criativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 passos de yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Caminho da alma: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Tudo de bom!<br> Sergey Zamkovoy</p>","nl":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png\" alt=\"Интенсив «Наслаждения»\" width=\"504\" height=\"128\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hallo, {{name}}!<br> <br>De maand van praktijken gericht op het harmoniseren van de tweede chakra is ten einde gekomen. Ik hoop dat je regelmatig geoefend hebt en de vruchten hebt geoogst in de vorm van een grotere ruimte voor plezier, meer ontspanning, heerlijkheid. Misschien heeft je leven nieuwe kleuren gekregen. Misschien is er zelfs op gezondheidsgebied iets ten goede veranderd… En nu nodig ik je uit om de golf niet te verliezen en door te gaan met de praktijken! Jarenlang heb je een bepaald gedachtegoed, waarden, gewoonten en psychologische clichés versterkt, en nu ben je pas begonnen je daarvan te bevrijden, stap voor stap ontdekkend wie je werkelijk bent. Doorgaan in deze richting zal je beslist diepere resultaten opleveren.</p><p></p><p> Om je opnieuw voor dit intensief in te schrijven, ga naar de link - <a href=\"https://zamkovoi.yoga/i2\">https://zamkovoi.yoga/i2</a>  <br> <br>Als u echter voelt dat u van richting wilt veranderen, maak dan kennis met mijn andere praktijken en cursussen. <br> <br>PRAKTIJKEN:<br> - Maand van gezondheid: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Maand van genot: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Maand van kracht: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Maand van liefde: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Maand van vrijheid: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Maand van wijsheid: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Maand van heiligheid: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSUSSEN:<br> - Yoga en gezondheid: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga en vrouwelijkheid: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mysterie van relaties: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Verwezenlijk je droom: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeet van de liefde: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Bron van creatieve kracht: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 stappen van yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Pad van de ziel: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Alle goeds!<br> Sergej Zamkovoj</p>"}'::jsonb,'{"ru":[{"id":"intensive-pleasure-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png","alt":"Интенсив «Наслаждения»","width":"100%","align":"center","naturalWidth":599,"naturalHeight":152,"marginTop":0,"marginBottom":24},{"id":"intensive-pleasure-2-text","type":"text","html":"<p>Здравствуйте, {{name}}!<br> <br>Вот и подошёл к концу месяц практик, направленных на гармонизацию второй чакры. Я надеюсь, что вы регулярно занимались, и получили плоды в виде расширения пространства удовольствий, большей расслабленности, кайфушности. Возможно, ваша жизнь заиграла новыми красками. Может быть даже в плане здоровья что-то изменилось в лучшую сторону… И сейчас я предлагаю вам не терять волну и продолжить практики! В течение многих лет вы укрепляли определенный образ мыслей, ценностей, привычек, психологических клише, и сейчас вы лишь начали от всего этого освобождаться, шаг за шагом открывая кто же вы есть на самом деле. Продолжение движения в этом направлении, безусловно, даст вам более глубокие результаты.</p><p></p><p> Чтобы вновь записаться на этот интенсив, перейдите по ссылке - <a href=\"https://zamkovoi.yoga/i2\">https://zamkovoi.yoga/i2</a> <br> <br>Если же вы чувствуете, что хотите сменить направление, то ознакомьтесь с другими моими практикумами и курсами. <br> <br>ПРАКТИКУМЫ:<br> - Месяц здоровья: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Месяц наслаждений: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Месяц силы: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Месяц любви: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Месяц свободы: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Месяц мудрости: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Месяц святости: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>КУРСЫ:<br> - Йога и здоровье: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Йога и женственность: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Тантра - мистерия взаимоотношений: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Осуществи мечту: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Планета любви: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Источник творческой силы: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 шагов йоги: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Путь души: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Всех благ!<br> Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"en":[{"id":"intensive-pleasure-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png","alt":"Интенсив «Наслаждения»","width":"100%","align":"center","naturalWidth":599,"naturalHeight":152,"marginTop":0,"marginBottom":24},{"id":"intensive-pleasure-2-text","type":"text","html":"<p>Hello, {{name}}!<br> <br>So the month of practices aimed at harmonizing the second chakra has come to an end. I hope that you practiced regularly and received fruits in the form of an expanded space of pleasures, greater relaxation, blissfulness. Perhaps your life has begun to play with new colors. Maybe even in terms of health something has changed for the better… And now I invite you not to lose the wave and continue the practices! For many years you have strengthened a certain way of thinking, values, habits, psychological clichés, and now you have only begun to free yourself from all of this, step by step discovering who you really are. Continuing to move in this direction will, of course, give you deeper results.</p><p></p><p> To sign up for this intensive again, follow the link - <a href=\"https://zamkovoi.yoga/i2\">https://zamkovoi.yoga/i2</a> <br> <br>If you feel that you want to change direction, then take a look at my other workshops and courses. <br> <br>WORKSHOPS:<br> - Month of Health: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Month of Pleasures: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Month of Strength: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Month of Love: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Month of Freedom: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Month of Wisdom: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Month of Holiness: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>COURSES:<br> - Yoga and Health: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga and Femininity: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - the mystery of relationships: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Fulfill the Dream: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planet of Love: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Source of Creative Power: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 Steps of Yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Path of the Soul: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>All the best!<br> Sergey Zamkovoy</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"de":[{"id":"intensive-pleasure-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png","alt":"Интенсив «Наслаждения»","width":"100%","align":"center","naturalWidth":599,"naturalHeight":152,"marginTop":0,"marginBottom":24},{"id":"intensive-pleasure-2-text","type":"text","html":"<p>Guten Tag, {{name}}!<br> <br>Nun ist der Monat der Praktiken, die auf die Harmonisierung des zweiten Chakras ausgerichtet waren, zu Ende gegangen. Ich hoffe, dass Sie regelmäßig praktiziert und Früchte erhalten haben – in Form einer Erweiterung des Raums der Genüsse, größerer Entspannung, mehr Rauschhaftigkeit. Vielleicht hat Ihr Leben in neuen Farben zu spielen begonnen. Möglicherweise hat sich sogar in gesundheitlicher Hinsicht etwas zum Besseren verändert … Und jetzt schlage ich Ihnen vor, die Welle nicht zu verlieren und mit den Praktiken fortzufahren! Viele Jahre lang haben Sie eine bestimmte Denkweise, Werte, Gewohnheiten, psychologische Klischees gefestigt, und jetzt haben Sie erst begonnen, sich von all dem zu befreien, Schritt für Schritt zu entdecken, wer Sie wirklich sind. Die Fortsetzung der Bewegung in diese Richtung wird Ihnen zweifellos tiefere Ergebnisse bringen.</p><p></p><p> Um sich erneut für diesen Intensivkurs anzumelden, folgen Sie dem Link - <a href=\"https://zamkovoi.yoga/i2\">https://zamkovoi.yoga/i2</a> <br> <br>Wenn Sie jedoch das Gefühl haben, die Richtung wechseln zu wollen, dann machen Sie sich mit meinen anderen Praktika und Kursen vertraut. <br> <br>PRAKTIKA:<br> - Monat der Gesundheit: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Monat der Genüsse: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Monat der Kraft: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Monat der Liebe: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Monat der Freiheit: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Monat der Weisheit: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Monat der Heiligkeit: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>KURSE:<br> - Yoga und Gesundheit: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga und Weiblichkeit: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - Mysterium der Beziehungen: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Verwirkliche den Traum: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planet der Liebe: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Quelle schöpferischer Kraft: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 Schritte des Yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Weg der Seele: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Alles Gute!<br> Sergej Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"fr":[{"id":"intensive-pleasure-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png","alt":"Интенсив «Наслаждения»","width":"100%","align":"center","naturalWidth":599,"naturalHeight":152,"marginTop":0,"marginBottom":24},{"id":"intensive-pleasure-2-text","type":"text","html":"<p>Bonjour, {{name}} !<br> <br>Voilà, le mois de pratiques visant à harmoniser le deuxième chakra est arrivé à son terme. J’espère que vous avez pratiqué régulièrement et que vous avez obtenu des fruits sous forme d’élargissement de l’espace des plaisirs, d’une plus grande relaxation, d’un plus grand kiff. Peut-être votre vie s’est-elle mise à scintiller de nouvelles couleurs. Peut-être même que, sur le plan de la santé, quelque chose a changé pour le mieux… Et maintenant, je vous propose de ne pas perdre la vague et de poursuivre les pratiques ! Pendant de nombreuses années, vous avez renforcé une certaine manière de penser, des valeurs, des habitudes, des clichés psychologiques, et maintenant vous avez seulement commencé à vous en libérer, ouvrant pas à pas qui vous êtes réellement. La poursuite du mouvement dans cette direction vous apportera, sans aucun doute, des résultats plus profonds.</p><p></p><p> Pour vous réinscrire à cet intensif, suivez le lien - <a href=\"https://zamkovoi.yoga/i2\">https://zamkovoi.yoga/i2</a> <br> <br>Si toutefois vous sentez que vous voulez changer de direction, alors prenez connaissance de mes autres ateliers et cours. <br> <br>ATELIERS :<br> - Mois de la santé : <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mois des plaisirs : <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mois de la force : <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mois de l’amour : <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mois de la liberté : <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mois de la sagesse : <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mois de la sainteté : <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>COURS :<br> - Yoga et santé: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga et féminité: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mystère des relations: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Réalise ton rêve: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planète de l''amour: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Source de force créatrice: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 pas de yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Chemin de l''âme: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Toutes les bénédictions !<br> Sergueï Zamkovoï</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"it":[{"id":"intensive-pleasure-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png","alt":"Интенсив «Наслаждения»","width":"100%","align":"center","naturalWidth":599,"naturalHeight":152,"marginTop":0,"marginBottom":24},{"id":"intensive-pleasure-2-text","type":"text","html":"<p>Salve, {{name}}!<br> <br>Ecco che è giunto al termine il mese di pratiche volte ad armonizzare il secondo chakra. Spero che vi siate esercitati regolarmente e che abbiate ottenuto frutti sotto forma di ampliamento dello spazio dei piaceri, maggiore rilassatezza, goduria. Forse la vostra vita ha iniziato a risplendere di nuovi colori. Magari anche sul piano della salute qualcosa è cambiato in meglio… E ora vi propongo di non perdere l’onda e di continuare le pratiche! Per molti anni avete consolidato un certo modo di pensare, valori, abitudini, cliché psicologici, e ora avete solo iniziato a liberarvi di tutto questo, aprendo passo dopo passo chi siete davvero. Continuare il movimento in questa direzione, senza dubbio, vi darà risultati più profondi.</p><p></p><p> Per iscrivervi di nuovo a questo intensivo, seguite il link - <a href=\"https://zamkovoi.yoga/i2\">https://zamkovoi.yoga/i2</a> <br> <br>Se invece sentite di voler cambiare direzione, allora date un''occhiata agli altri miei praticum e corsi. <br> <br>PRATICUM:<br> - Mese della salute: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mese dei piaceri: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mese della forza: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mese dell''amore: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mese della libertà: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mese della saggezza: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mese della santità: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CORSI:<br> - Yoga e salute: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga e femminilità: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mistero delle relazioni: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Realizza il sogno: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Pianeta dell''amore: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fonte di forza creativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 passi di yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Il cammino dell''anima: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Ogni bene!<br> Sergej Zamkovoj</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"es":[{"id":"intensive-pleasure-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png","alt":"Интенсив «Наслаждения»","width":"100%","align":"center","naturalWidth":599,"naturalHeight":152,"marginTop":0,"marginBottom":24},{"id":"intensive-pleasure-2-text","type":"text","html":"<p>Hola, {{name}}!<br> <br>Así ha llegado a su fin el mes de prácticas dirigidas a armonizar la segunda chakra. Espero que usted haya practicado con regularidad y haya obtenido frutos en forma de ampliación del espacio de los placeres, mayor relajación, gustazo. Quizá su vida haya empezado a brillar con nuevos colores. Puede que incluso, en cuanto a la salud, algo haya cambiado para mejor… Y ahora le propongo no perder la ola y continuar con las prácticas. Durante muchos años usted ha fortalecido una determinada forma de pensar, valores, hábitos, clichés psicológicos, y ahora solo ha comenzado a liberarse de todo ello, abriendo paso a paso quién es usted en realidad. La continuación del movimiento en esta dirección, sin duda, le dará resultados más profundos.</p><p></p><p> Para inscribirse de nuevo en este intensivo, vaya al enlace - <a href=\"https://zamkovoi.yoga/i2\">https://zamkovoi.yoga/i2</a> <br> <br>Si siente que quiere cambiar de dirección, eche un vistazo a mis otros talleres y cursos. <br> <br>TALLERES:<br> - Mes de la salud: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mes de los placeres: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mes de la fuerza: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mes del amor: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mes de la libertad: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mes de la sabiduría: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mes de la santidad: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSOS:<br> - Yoga y salud: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga y feminidad: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - misterio de las relaciones: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Haz realidad tu sueño: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeta del amor: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fuente de la fuerza creativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 pasos del yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Camino del alma: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>¡Todo lo mejor!<br> Serguéi Zamkovói</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"pt":[{"id":"intensive-pleasure-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png","alt":"Интенсив «Наслаждения»","width":"100%","align":"center","naturalWidth":599,"naturalHeight":152,"marginTop":0,"marginBottom":24},{"id":"intensive-pleasure-2-text","type":"text","html":"<p>Olá, {{name}}!<br> <br>Chegou ao fim o mês de práticas voltadas para a harmonização do segundo chakra. Espero que você tenha praticado regularmente e colhido frutos na forma de ampliação do espaço dos prazeres, de maior relaxamento, de gostosura. Talvez sua vida tenha ganhado novas cores. Talvez até na questão da saúde algo tenha mudado para melhor… E agora eu proponho que você não perca a onda e continue as práticas! Durante muitos anos você fortaleceu um determinado modo de pensar, valores, hábitos, clichês psicológicos, e agora você apenas começou a se libertar de tudo isso, passo a passo descobrindo quem você realmente é. A continuação do movimento nessa direção, sem dúvida, dará a você resultados mais profundos.</p><p></p><p> Para se inscrever novamente neste intensivo, acesse o link - <a href=\"https://zamkovoi.yoga/i2\">https://zamkovoi.yoga/i2</a> <br> <br>Se, porém, você sente que quer mudar de direção, conheça meus outros praticuns e cursos. <br> <br>PRATICUNS:<br> - Mês da saúde: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mês dos prazeres: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mês da força: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mês do amor: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mês da liberdade: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mês da sabedoria: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mês da santidade: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSOS:<br> - Yoga e saúde: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga e feminilidade: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mistério das relações: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Realize o sonho: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeta do amor: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fonte da força criativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 passos de yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Caminho da alma: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Tudo de bom!<br> Sergey Zamkovoy</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"nl":[{"id":"intensive-pleasure-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-pleasure/i2_email-d22f0ad82946.png","alt":"Интенсив «Наслаждения»","width":"100%","align":"center","naturalWidth":599,"naturalHeight":152,"marginTop":0,"marginBottom":24},{"id":"intensive-pleasure-2-text","type":"text","html":"<p>Hallo, {{name}}!<br> <br>De maand van praktijken gericht op het harmoniseren van de tweede chakra is ten einde gekomen. Ik hoop dat je regelmatig geoefend hebt en de vruchten hebt geoogst in de vorm van een grotere ruimte voor plezier, meer ontspanning, heerlijkheid. Misschien heeft je leven nieuwe kleuren gekregen. Misschien is er zelfs op gezondheidsgebied iets ten goede veranderd… En nu nodig ik je uit om de golf niet te verliezen en door te gaan met de praktijken! Jarenlang heb je een bepaald gedachtegoed, waarden, gewoonten en psychologische clichés versterkt, en nu ben je pas begonnen je daarvan te bevrijden, stap voor stap ontdekkend wie je werkelijk bent. Doorgaan in deze richting zal je beslist diepere resultaten opleveren.</p><p></p><p> Om je opnieuw voor dit intensief in te schrijven, ga naar de link - <a href=\"https://zamkovoi.yoga/i2\">https://zamkovoi.yoga/i2</a>  <br> <br>Als u echter voelt dat u van richting wilt veranderen, maak dan kennis met mijn andere praktijken en cursussen. <br> <br>PRAKTIJKEN:<br> - Maand van gezondheid: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Maand van genot: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Maand van kracht: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Maand van liefde: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Maand van vrijheid: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Maand van wijsheid: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Maand van heiligheid: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSUSSEN:<br> - Yoga en gezondheid: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga en vrouwelijkheid: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mysterie van relaties: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Verwezenlijk je droom: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeet van de liefde: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Bron van creatieve kracht: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 stappen van yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Pad van de ziel: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Alle goeds!<br> Sergej Zamkovoj</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.courses(slug,title,title_i18n,kind,landing_url,access_days,day_card_extra_days,webinar_extra_days,automation_id,intro_email_step_id,completion_email_step_id,source_hash) values('intensive-pleasure','Интенсив «Наслаждения»','{"ru":"Интенсив «Наслаждения»","en":"Pleasures Intensive","de":"Intensivkurs „Genüsse“","fr":"Intensif « Plaisirs »","it":"Intensivo «Piacere»","es":"Intensivo «Placeres»","pt":"Intensivo «Prazeres»","nl":"Intensief «Genietingen»"}'::jsonb,'intensive','',1,1,1,'1dfe9e9e-a458-5a4a-b8ce-0b90014a21a1','4a5a18cc-7153-5b54-b233-410af5793c50','085569cb-1cda-5e45-affe-4f98482e70a9','6844249b246aec262094774ba61b62ad7ae1aee4c60e4c8c38675d2cc93f61a9') on conflict(slug) do update set source_hash=excluded.source_hash;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-01','intensive-pleasure',1,0,'День: 1','[{"type":"video","vimeoId":"1147911332"},{"type":"text","markdown":"### Совет дня:\n\nРазрешите себе хотеть \"запретное\". В сфере второй чакры находятся одни из самых сильных желаний. Часть из них табуированы и вытеснены глубоко в подсознание. Но многие желания очевидны, и люди сами себе их запрещают - прикосновения к другому человеку, особенно если он нравится, проявление своей чувственности, привлекательности, сексуальности. Даже качественный отдых люди могут себе запрещать из лояльности к \"в поте лица добывающему хлеб свой\" большинству... Внутренние запреты создают огромное напряжение как в психике, так и в теле. Осознайте и поставьте под сомнение хотя бы некоторые из тех запретов, которые очевидно проявляются в вашей жизни. И я сейчас не предлагаю вам их преодолевать. Просто, разрешите себе хотеть - это уже частично снимает напряжение."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1147911332"},{"type":"text","markdown":"### Tip of the day:\n\nAllow yourself to want the “forbidden.” In the sphere of the second chakra are some of the strongest desires. Some of them are tabooed and pushed deep into the subconscious. But many desires are obvious, and people forbid them to themselves—touching another person, especially if you like them, showing your sensuality, attractiveness, sexuality. Even quality rest people can forbid themselves out of loyalty to the majority “earning their bread by the sweat of their brow”... Internal prohibitions create enormous tension both in the psyche and in the body. Become aware of and call into question at least some of those prohibitions that obviously manifest in your life. And I am not now suggesting that you overcome them. Simply allow yourself to want—this already partially removes the tension."}],"de":[{"type":"video","vimeoId":"1147911332"},{"type":"text","markdown":"### Tipp des Tages:\n\nErlauben Sie sich, das „Verbotene“ zu wollen. Im Bereich des zweiten Chakras liegen einige der stärksten Wünsche. Ein Teil von ihnen ist tabuisiert und tief ins Unterbewusstsein verdrängt. Doch viele Wünsche sind offensichtlich, und die Menschen verbieten sie sich selbst – Berührungen eines anderen Menschen, besonders wenn er gefällt, das Zeigen der eigenen Sinnlichkeit, Attraktivität, Sexualität. Sogar gute Erholung können Menschen sich selbst verbieten, aus Loyalität gegenüber der Mehrheit, die „im Schweiße ihres Angesichts ihr Brot erwirbt“... Innere Verbote erzeugen enorme Spannung sowohl in der Psyche als auch im Körper. Werden Sie sich zumindest einiger der Verbote bewusst und stellen Sie sie infrage, die sich offensichtlich in Ihrem Leben zeigen. Und ich schlage Ihnen jetzt nicht vor, sie zu überwinden. Erlauben Sie sich einfach zu wollen – das nimmt bereits teilweise die Spannung."}],"fr":[{"type":"video","vimeoId":"1147911332"},{"type":"text","markdown":"### Conseil du jour :\n\nAutorisez-vous à désirer « l’interdit ». Dans la sphère du deuxième chakra se trouvent certains des désirs les plus forts. Une partie d’entre eux sont tabous et refoulés profondément dans le subconscient. Mais beaucoup de désirs sont évidents, et les gens se les interdisent eux-mêmes — les contacts avec une autre personne, surtout si elle plaît, l’expression de sa sensualité, de son attractivité, de sa sexualité. Même un repos de qualité, les gens peuvent se l’interdire par loyauté envers la majorité qui « gagne son pain à la sueur de son front »... Les interdits intérieurs créent une énorme tension tant dans la psyché que dans le corps. Prenez conscience et remettez en question au moins certains de ces interdits qui se manifestent de façon évidente dans votre vie. Et je ne vous propose pas maintenant de les surmonter. Simplement, autorisez-vous à désirer — cela soulage déjà partiellement la tension."}],"it":[{"type":"video","vimeoId":"1147911332"},{"type":"text","markdown":"### Consiglio del giorno:\n\nPermettetevi di desiderare il «proibito». Nell’ambito del secondo chakra si trovano alcuni dei desideri più forti. Parte di essi è tabuizzata e rimossa in profondità nel subconscio. Ma molti desideri sono evidenti, e le persone se li proibiscono da sole: i contatti con un’altra persona, soprattutto se piace, la manifestazione della propria sensualità, attrattività, sessualità. Persino un riposo di qualità le persone possono proibirselo per lealtà alla maggioranza che «si guadagna il pane col sudore della fronte»... I divieti interiori creano un’enorme tensione sia nella psiche sia nel corpo. Prendete coscienza e mettete in dubbio almeno alcuni di quei divieti che si manifestano evidentemente nella vostra vita. E ora non vi propongo di superarli. Semplicemente, permettetevi di desiderare: questo già rimuove in parte la tensione."}],"es":[{"type":"video","vimeoId":"1147911332"},{"type":"text","markdown":"### Consejo del día:\n\nPermítase desear «lo prohibido». En el ámbito de la segunda chakra se encuentran algunos de los deseos más fuertes. Parte de ellos están tabuizados y desplazados profundamente al subconsciente. Pero muchos deseos son evidentes, y las personas mismas se los prohíben: tocar a otra persona, especialmente si esa persona le gusta, la manifestación de su propia sensualidad, atractivo, sexualidad. Incluso un descanso de calidad las personas pueden prohibirse por lealtad a la mayoría que «con el sudor de su frente se gana el pan»… Las prohibiciones internas crean una enorme tensión tanto en la psique como en el cuerpo. Tome conciencia y ponga en duda al menos algunas de esas prohibiciones que se manifiestan de forma evidente en su vida. Y ahora no le propongo superarlas. Simplemente, permítase desear: eso ya alivia parcialmente la tensión."}],"pt":[{"type":"video","vimeoId":"1147911332"},{"type":"text","markdown":"### Dica do dia:\n\nPermita-se desejar o \"proibido\". No âmbito do segundo chakra estão alguns dos desejos mais fortes. Parte deles é tabu e foi reprimida bem fundo no subconsciente. Mas muitos desejos são óbvios, e as pessoas os proíbem a si mesmas - toques em outra pessoa, especialmente se ela lhe agrada, manifestação da própria sensualidade, atratividade, sexualidade. Até um descanso de qualidade as pessoas podem proibir a si mesmas por lealdade à maioria que \"ganha o pão com o suor do próprio rosto\"... Proibições internas criam uma tensão enorme tanto na psique quanto no corpo. Tome consciência e questione ao menos algumas das proibições que se manifestam claramente na sua vida. E não estou propondo agora que você as supere. Apenas permita-se desejar - isso já alivia parcialmente a tensão."}],"nl":[{"type":"video","vimeoId":"1147911332"},{"type":"text","markdown":"### Tip van de dag:\n\nSta jezelf toe het «verbodene» te willen. Op het gebied van de tweede chakra liggen enkele van de sterkste verlangens. Een deel ervan is taboe en diep in het onderbewustzijn verdrongen. Maar veel verlangens zijn evident, en mensen verbieden ze zichzelf - aanrakingen van een ander mens, vooral als je hem of haar leuk vindt, het tonen van je sensualiteit, aantrekkelijkheid, seksualiteit. Zelfs goede rust kunnen mensen zichzelf verbieden uit loyaliteit aan de «in het zweet des aanschijns je brood verdienende» meerderheid... Innerlijke verboden creëren enorme spanning, zowel in de psyche als in het lichaam. Word je bewust en trek ten minste enkele van die verboden die duidelijk in je leven zichtbaar worden in twijfel. En ik stel nu niet voor ze te overwinnen. Sta jezelf gewoon toe te willen - dat vermindert de spanning al gedeeltelijk."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-02','intensive-pleasure',2,1,'День: 2','[{"type":"video","vimeoId":"1150277253"},{"type":"text","markdown":"### Совет дня:\n\nФлиртуйте с жизнью. Флирт - это не только про сексуальные подкаты. Это лёгкое, игривое взаимодействие с миром. Улыбнитесь незнакомцу, скажите комплимент кассиру в супермаркете, подмигните своему отражению в витрине. Это создаёт вокруг вас поле лёгкости и приятных вибраций, делая вашу жизнь ярче и интереснее."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1150277253"},{"type":"text","markdown":"### Tip of the day:\n\nFlirt with life. Flirting is not only about sexual advances. It is a light, playful interaction with the world. Smile at a stranger, give a compliment to the cashier in the supermarket, wink at your reflection in a shop window. This creates a field of lightness and pleasant vibrations around you, making your life brighter and more interesting."}],"de":[{"type":"video","vimeoId":"1150277253"},{"type":"text","markdown":"### Tipp des Tages:\n\nFlirten Sie mit dem Leben. Flirten bedeutet nicht nur sexuelle Anmachsprüche. Es ist eine leichte, verspielte Interaktion mit der Welt. Lächeln Sie einem Fremden zu, machen Sie der Kassiererin im Supermarkt ein Kompliment, zwinkern Sie Ihrem Spiegelbild in einer Schaufensterscheibe zu. Das schafft um Sie herum ein Feld der Leichtigkeit und angenehmer Schwingungen und macht Ihr Leben heller und interessanter."}],"fr":[{"type":"video","vimeoId":"1150277253"},{"type":"text","markdown":"### Conseil du jour :\n\nFlirtez avec la vie. Le flirt, ce n’est pas seulement des avances sexuelles. C’est une interaction légère et joueuse avec le monde. Souriez à un inconnu, faites un compliment au caissier du supermarché, faites un clin d’œil à votre reflet dans une vitrine. Cela crée autour de vous un champ de légèreté et de vibrations agréables, rendant votre vie plus lumineuse et plus intéressante."}],"it":[{"type":"video","vimeoId":"1150277253"},{"type":"text","markdown":"### Consiglio del giorno:\n\nFlirtate con la vita. Il flirt non riguarda solo le avances sessuali. È un’interazione leggera e giocosa con il mondo. Sorridete a uno sconosciuto, fate un complimento al cassiere del supermercato, fate l’occhiolino al vostro riflesso in una vetrina. Questo crea intorno a voi un campo di leggerezza e vibrazioni piacevoli, rendendo la vostra vita più luminosa e interessante."}],"es":[{"type":"video","vimeoId":"1150277253"},{"type":"text","markdown":"### Consejo del día:\n\nCoquetee con la vida. El coqueteo no se trata solo de insinuaciones sexuales. Es una interacción ligera y juguetona con el mundo. Sonría a un desconocido, diga un cumplido al cajero del supermercado, guiñe un ojo a su reflejo en el escaparate. Esto crea a su alrededor un campo de ligereza y vibraciones agradables, haciendo su vida más brillante e interesante."}],"pt":[{"type":"video","vimeoId":"1150277253"},{"type":"text","markdown":"### Dica do dia:\n\nFlertar com a vida. Flertar não é apenas sobre investidas sexuais. É uma interação leve e lúdica com o mundo. Sorria para um desconhecido, faça um elogio ao caixa do supermercado, pisque para o seu reflexo na vitrine. Isso cria ao seu redor um campo de leveza e vibrações agradáveis, tornando sua vida mais brilhante e interessante."}],"nl":[{"type":"video","vimeoId":"1150277253"},{"type":"text","markdown":"### Tip van de dag:\n\nFlirt met het leven. Flirten gaat niet alleen over seksuele avances. Het is een lichte, speelse interactie met de wereld. Glimlach naar een vreemde, geef een compliment aan de caissière in de supermarkt, knipoog naar je spiegelbeeld in een etalage. Dat creëert om je heen een veld van lichtheid en aangename vibraties, waardoor je leven kleurrijker en interessanter wordt."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-03','intensive-pleasure',3,1,'День: 3','[{"type":"video","vimeoId":"1141808936"},{"type":"text","markdown":"### Совет дня:\n\nЛегализуйте свои фантазии. Сексуальные фантазии - это естественная игра ума, творчество вашей сексуальной энергии. Не стыдитесь и не подавляйте их. Признайте их существование, не обязательно воплощая в жизнь. Позволяя им быть, вы освобождаете огромное количество энергии, которая была заперта чувством вины и страха. Но всё-таки не становитесь их рабом. И понимайте - когда они мягко приглашают вас к развитию, а когда всего-лишь украшают психологический фон :)"}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1141808936"},{"type":"text","markdown":"### Tip of the day:\n\nLegalize your fantasies. Sexual fantasies are a natural play of the mind, the creativity of your sexual energy. Do not be ashamed of them and do not suppress them. Acknowledge their existence, not necessarily embodying them in life. By allowing them to be, you release a huge amount of energy that was locked up by guilt and fear. But still do not become their slave. And understand—when they gently invite you to development, and when they merely decorate the psychological background :)"}],"de":[{"type":"video","vimeoId":"1141808936"},{"type":"text","markdown":"### Tipp des Tages:\n\nLegalisieren Sie Ihre Fantasien. Sexuelle Fantasien sind ein natürliches Spiel des Geistes, die Kreativität Ihrer sexuellen Energie. Schämen Sie sich nicht und unterdrücken Sie sie nicht. Erkennen Sie ihre Existenz an, ohne sie unbedingt in die Tat umsetzen zu müssen. Indem Sie ihnen erlauben zu sein, befreien Sie eine enorme Menge Energie, die durch Schuldgefühle und Angst eingeschlossen war. Aber werden Sie trotzdem nicht ihr Sklave. Und verstehen Sie – wann sie Sie sanft zur Entwicklung einladen und wann sie bloß den psychologischen Hintergrund schmücken :)"}],"fr":[{"type":"video","vimeoId":"1141808936"},{"type":"text","markdown":"### Conseil du jour :\n\nLégalisez vos fantasmes. Les fantasmes sexuels sont un jeu naturel de l’esprit, la créativité de votre énergie sexuelle. N’en ayez pas honte et ne les réprimez pas. Reconnaissez leur existence, sans forcément les concrétiser. En leur permettant d’être, vous libérez une immense quantité d’énergie qui était enfermée par la culpabilité et la peur. Mais tout de même, ne devenez pas leur esclave. Et comprenez : quand ils vous invitent en douceur au développement, et quand ils ne font qu’embellir le fond psychologique :)"}],"it":[{"type":"video","vimeoId":"1141808936"},{"type":"text","markdown":"### Consiglio del giorno:\n\nLegalizzate le vostre fantasie. Le fantasie sessuali sono un gioco naturale della mente, la creatività della vostra energia sessuale. Non vergognatevene e non reprimetele. Riconoscete la loro esistenza, senza necessariamente realizzarle. Permettendo loro di esistere, liberate un’enorme quantità di energia che era rinchiusa dal senso di colpa e dalla paura. Ma comunque non diventate loro schiavi. E comprendete quando vi invitano dolcemente alla crescita e quando invece si limitano ad abbellire lo sfondo psicologico :)"}],"es":[{"type":"video","vimeoId":"1141808936"},{"type":"text","markdown":"### Consejo del día:\n\nLegalice sus fantasías. Las fantasías sexuales son un juego natural de la mente, la creatividad de su energía sexual. No se avergüence de ellas ni las reprima. Reconozca su existencia, sin necesidad de llevarlas a la práctica. Al permitir que existan, libera una enorme cantidad de energía que estaba encerrada por el sentimiento de culpa y el miedo. Pero, aun así, no se convierta en su esclavo. Y comprenda cuándo ellas lo invitan suavemente al desarrollo y cuándo solo decoran el fondo psicológico :)"}],"pt":[{"type":"video","vimeoId":"1141808936"},{"type":"text","markdown":"### Dica do dia:\n\nLegalize suas fantasias. Fantasias sexuais são um jogo natural da mente, a criatividade da sua energia sexual. Não sinta vergonha nem as reprima. Reconheça a existência delas, sem necessariamente trazê-las para a realidade. Ao permitir que existam, você libera uma enorme quantidade de energia que estava trancada pelo sentimento de culpa e medo. Mas, ainda assim, não se torne escravo delas. E compreenda - quando elas gentilmente convidam você ao desenvolvimento e quando apenas embelezam o fundo psicológico :)"}],"nl":[{"type":"video","vimeoId":"1141808936"},{"type":"text","markdown":"### Tip van de dag:\n\nLegaliseer je fantasieën. Seksuele fantasieën zijn een natuurlijk spel van de geest, de creativiteit van je seksuele energie. Schaam je er niet voor en onderdruk ze niet. Erken dat ze bestaan, zonder ze per se in de praktijk te brengen. Door ze te laten zijn, bevrijd je een enorme hoeveelheid energie die gevangen zat door schuldgevoel en angst. Maar word er toch geen slaaf van. En begrijp wanneer ze je zachtjes uitnodigen tot ontwikkeling, en wanneer ze slechts de psychologische achtergrond versieren :)"}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-04','intensive-pleasure',4,1,'День: 4','[{"type":"video","vimeoId":"1146307319"},{"type":"text","markdown":"### Совет дня:\n\nСпите в расслабленной позе. Обратите внимание, в какой позе вы засыпаете и просыпаетесь. Если тело скручено в узел, это говорит о дневном напряжении, которое вы несёте с собой в сон. Перед сном сознательно расслабьте глаза, лицо, плечи, грудь, грудь, живот... Возможно, вам помогут расслабляющие асаны. Чтобы не возбудиться, выполните буквально 2-3 асаны - именно на области напряжения. При этом дышите удлинняя выдохи - заодно и навязчивые мысли уйдут. А затем, вместо шавасаны, позвольте телу растечься по кровати. Качественное расслабление ночью - залог восстановления сил, и наполненной жизни в течение дня."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1146307319"},{"type":"text","markdown":"### Tip of the day:\n\nSleep in a relaxed pose. Notice in what pose you fall asleep and wake up. If the body is twisted into a knot, this speaks of daytime tension that you carry with you into sleep. Before sleep, consciously relax your eyes, face, shoulders, chest, chest, abdomen... Perhaps relaxing asanas will help you. In order not to get agitated, perform literally 2-3 asanas—specifically for the areas of tension. At the same time, breathe with lengthened exhalations—at the same time obsessive thoughts will go away. And then, instead of shavasana, allow the body to spread over the bed. Quality relaxation at night is the guarantee of restoring strength and a fulfilled life during the day."}],"de":[{"type":"video","vimeoId":"1146307319"},{"type":"text","markdown":"### Tipp des Tages:\n\nSchlafen Sie in einer entspannten Haltung. Achten Sie darauf, in welcher Haltung Sie einschlafen und aufwachen. Wenn der Körper zu einem Knoten verschlungen ist, spricht das für die Tagesanspannung, die Sie mit in den Schlaf nehmen. Entspannen Sie vor dem Schlaf bewusst die Augen, das Gesicht, die Schultern, die Brust, die Brust, den Bauch ... Vielleicht helfen Ihnen entspannende Asanas. Um nicht erregt zu werden, führen Sie buchstäblich 2-3 Asanas aus – genau für die Bereiche der Spannung. Atmen Sie dabei mit verlängerten Ausatmungen – nebenbei gehen auch aufdringliche Gedanken weg. Und dann lassen Sie, statt Shavasana, den Körper über das Bett zerrinnen. Hochwertige Entspannung in der Nacht ist die Grundlage für die Wiederherstellung der Kräfte und für ein erfülltes Leben im Laufe des Tages."}],"fr":[{"type":"video","vimeoId":"1146307319"},{"type":"text","markdown":"### Conseil du jour :\n\nDormez dans une posture détendue. Faites attention à la posture dans laquelle vous vous endormez et vous réveillez. Si le corps est noué, cela parle d’une tension diurne que vous emportez avec vous dans le sommeil. Avant de dormir, détendez consciemment les yeux, le visage, les épaules, la poitrine, la poitrine, le ventre... Peut-être que des asanas relaxantes vous aideront. Pour ne pas vous exciter, exécutez littéralement 2-3 asanas — précisément sur les zones de tension. En même temps, respirez en allongeant les expirations — et les pensées obsédantes partiront en même temps. Ensuite, au lieu de shavasana, permettez au corps de se fondre sur le lit. Une relaxation de qualité pendant la nuit est la garantie de la récupération des forces, et d’une vie remplie pendant la journée."}],"it":[{"type":"video","vimeoId":"1146307319"},{"type":"text","markdown":"### Consiglio del giorno:\n\nDormite in una posizione rilassata. Fate attenzione in quale posizione vi addormentate e vi svegliate. Se il corpo è annodato, questo indica una tensione diurna che vi portate nel sonno. Prima di dormire, rilassate consapevolmente gli occhi, il viso, le spalle, il petto, il petto, la pancia... Forse vi aiuteranno le asana rilassanti. Per non eccitarvi, eseguite letteralmente 2-3 asana, proprio sulle zone di tensione. Respirate allungando le espirazioni: così se ne andranno anche i pensieri ossessivi. E poi, invece della savasana, lasciate che il corpo si distenda sul letto. Un rilassamento di qualità durante la notte è garanzia di recupero delle forze e di una vita piena durante il giorno."}],"es":[{"type":"video","vimeoId":"1146307319"},{"type":"text","markdown":"### Consejo del día:\n\nDuerma en una postura relajada. Preste atención a la postura en la que se queda dormido y se despierta. Si el cuerpo está retorcido como un nudo, eso habla de la tensión diurna que usted se lleva consigo al sueño. Antes de dormir, relaje conscientemente los ojos, la cara, los hombros, el pecho, el pecho, el vientre… Quizá le ayuden las asanas relajantes. Para no excitarse, realice literalmente 2-3 asanas, justamente en las zonas de tensión. Al mismo tiempo, respire alargando las exhalaciones; de paso, también se irán los pensamientos obsesivos. Y después, en lugar de shavasana, permita que el cuerpo se derrita por la cama. Una relajación de calidad por la noche es la garantía de recuperación de fuerzas y de una vida plena durante el día."}],"pt":[{"type":"video","vimeoId":"1146307319"},{"type":"text","markdown":"### Dica do dia:\n\nDurma em uma posição relaxada. Observe em que posição você adormece e acorda. Se o corpo está torcido como um nó, isso fala de uma tensão diurna que você leva consigo para o sono. Antes de dormir, relaxe conscientemente os olhos, o rosto, os ombros, o peito, o peito, a barriga... Talvez as asanas relaxantes possam ajudar você. Para não se agitar, execute literalmente 2-3 asanas - justamente nas áreas de tensão. Enquanto isso, respire alongando as expirações - de quebra, os pensamentos obsessivos também irão embora. E então, em vez de savasana, permita que o corpo se espalhe pela cama. Um relaxamento de qualidade à noite é a garantia de recuperação das forças e de uma vida plena durante o dia."}],"nl":[{"type":"video","vimeoId":"1146307319"},{"type":"text","markdown":"### Tip van de dag:\n\nSlaap in een ontspannen houding. Let op in welke houding je in slaap valt en wakker wordt. Als het lichaam in een knoop is gedraaid, wijst dat op spanning overdag die je meeneemt je slaap in. Ontspan voor het slapen bewust je ogen, gezicht, schouders, borst, borst, buik... Misschien helpen ontspannende asana''s je. Om niet opgewonden te raken, doe letterlijk 2-3 asana''s - precies op de spanningsgebieden. Adem daarbij met verlengde uitademingen - dan verdwijnen ook de opdringerige gedachten. En laat daarna, in plaats van shavasana, je lichaam over het bed uitvloeien. Kwalitatieve ontspanning ''s nachts is de sleutel tot herstel van krachten en een vervuld leven overdag."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-05','intensive-pleasure',5,1,'День: 5','[{"type":"video","vimeoId":"1139929275"},{"type":"text","markdown":"### Совет дня:\n\nДышите животом. Большинство людей в стрессе дышат поверхностно. Это связано с психосоматическими напряжениями в груди и в животе. В свою очередь такое дыхание даёт психике сигнал о стрессе, приводя к усилению стресса. Возникает штопор, из которого сложно выйти, если нет осознанности. Хотя, выход прост - как только замечаете стресс, начинайте дышать животом, а точнее нижней его частью. Там находится вторая чакра, а в китайских страдициях - нижний даньтянь - основной резервуар, в котором накапливается и хранится жизненная сила Ци. Так вот, положите руку на эту область и почувствуйте, как она мягко поднимается на вдохе и опускается на выдохе. Даже без специальных эзотерических техних, такое действие посылает нервной системе сигнал безопасности, успокаивает и снимает напряжение в области таза."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1139929275"},{"type":"text","markdown":"### Tip of the day:\n\nBreathe with your belly. Most people under stress breathe shallowly. This is connected with psychosomatic tensions in the chest and abdomen. In turn, such breathing gives the psyche a signal of stress, leading to increased stress. A downward spiral arises from which it is difficult to get out if there is no awareness. Although the way out is simple—as soon as you notice stress, begin to breathe with your belly, or more precisely its lower part. There is the second chakra, and in Chinese traditions—the lower dantian—the main reservoir in which life force Qi accumulates and is stored. So, place your hand on this area and feel how it gently rises on the inhale and lowers on the exhale. Even without special esoteric techniques, such an action sends the nervous system a signal of safety, calms and removes tension in the pelvic area."}],"de":[{"type":"video","vimeoId":"1139929275"},{"type":"text","markdown":"### Tipp des Tages:\n\nAtmen Sie in den Bauch. Die meisten Menschen atmen unter Stress oberflächlich. Das hängt mit psychosomatischen Spannungen in der Brust und im Bauch zusammen. Wiederum gibt solche Atmung der Psyche ein Stresssignal, was zu verstärktem Stress führt. Es entsteht ein Korkenzieher, aus dem schwer herauszukommen ist, wenn es keine Achtsamkeit gibt. Obwohl der Ausweg einfach ist – sobald Sie Stress bemerken, beginnen Sie, in den Bauch zu atmen, genauer in seinen unteren Teil. Dort befindet sich das zweite Chakra, und in chinesischen Traditionen der untere Dantian – das Hauptreservoir, in dem die Lebenskraft Qi angesammelt und gespeichert wird. Also legen Sie die Hand auf diesen Bereich und spüren Sie, wie er sich beim Einatmen sanft hebt und beim Ausatmen senkt. Selbst ohne spezielle esoterische Techniken sendet eine solche Handlung dem Nervensystem ein Sicherheitssignal, beruhigt und löst Spannung im Beckenbereich."}],"fr":[{"type":"video","vimeoId":"1139929275"},{"type":"text","markdown":"### Conseil du jour :\n\nRespirez par le ventre. La plupart des gens en état de stress respirent superficiellement. Cela est lié à des tensions psychosomatiques dans la poitrine et le ventre. À son tour, cette respiration envoie à la psyché un signal de stress, ce qui conduit à renforcer le stress. Il se crée une spirale dont il est difficile de sortir sans conscience. Pourtant, la sortie est simple : dès que vous remarquez le stress, commencez à respirer par le ventre, ou plus précisément par sa partie inférieure. Là se trouve le deuxième chakra, et dans les traditions chinoises — le dantian inférieur — le réservoir principal où s’accumule et se conserve la force vitale Qi. Donc, placez la main sur cette zone et sentez comme elle monte doucement à l’inspiration et descend à l’expiration. Même sans techniques ésotériques spéciales, un tel geste envoie au système nerveux un signal de sécurité, calme et relâche la tension dans la région du bassin."}],"it":[{"type":"video","vimeoId":"1139929275"},{"type":"text","markdown":"### Consiglio del giorno:\n\nRespirate con la pancia. La maggior parte delle persone in condizioni di stress respira in modo superficiale. Ciò è legato a tensioni psicosomatiche nel petto e nella pancia. A sua volta, una tale respirazione invia alla psiche un segnale di stress, portando a un aumento dello stress. Si crea una spirale dalla quale è difficile uscire se manca la consapevolezza. Però la via d’uscita è semplice: appena notate lo stress, iniziate a respirare con la pancia, o più precisamente con la sua parte inferiore. Lì si trova il secondo chakra, e nelle tradizioni cinesi il dantian inferiore, il serbatoio principale in cui si accumula e si conserva la forza vitale Qi. Dunque, mettete una mano su questa zona e sentite come si solleva dolcemente all’inspirazione e si abbassa all’espirazione. Anche senza speciali tecniche esoteriche, un tale gesto invia al sistema nervoso un segnale di sicurezza, calma e allevia la tensione nella zona del bacino."}],"es":[{"type":"video","vimeoId":"1139929275"},{"type":"text","markdown":"### Consejo del día:\n\nRespire con el abdomen. La mayoría de las personas, bajo estrés, respiran superficialmente. Esto está relacionado con tensiones psicosomáticas en el pecho y en el abdomen. A su vez, esa respiración le da a la psique una señal de estrés, llevando a un aumento del estrés. Se forma una espiral de la que es difícil salir si no hay conciencia. Aunque la salida es simple: en cuanto note estrés, empiece a respirar con el abdomen, o más exactamente con su parte inferior. Allí se encuentra la segunda chakra, y en las tradiciones chinas, el dantian inferior, el depósito principal donde se acumula y se guarda la fuerza vital Qi. Así que ponga la mano en esa zona y sienta cómo se eleva suavemente al inhalar y desciende al exhalar. Incluso sin técnicas esotéricas especiales, tal acción envía al sistema nervioso una señal de seguridad, calma y libera la tensión en la zona de la pelvis."}],"pt":[{"type":"video","vimeoId":"1139929275"},{"type":"text","markdown":"### Dica do dia:\n\nRespire com a barriga. A maioria das pessoas, sob estresse, respira de forma superficial. Isso está relacionado a tensões psicossomáticas no peito e na barriga. Por sua vez, essa respiração envia à psique um sinal de estresse, levando ao aumento do estresse. Cria-se uma espiral da qual é difícil sair se não houver consciência. Embora a saída seja simples - assim que perceber o estresse, comece a respirar com a barriga, ou mais precisamente com a parte inferior dela. Ali está o segundo chakra e, nas tradições chinesas, o dantian inferior - o reservatório principal onde se acumula e se armazena a força vital Qi. Então, coloque a mão nessa região e sinta como ela suavemente sobe na inspiração e desce na expiração. Mesmo sem técnicas esotéricas especiais, essa ação envia ao sistema nervoso um sinal de segurança, acalma e alivia a tensão na região pélvica."}],"nl":[{"type":"video","vimeoId":"1139929275"},{"type":"text","markdown":"### Tip van de dag:\n\nAdem met je buik. De meeste mensen ademen onder stress oppervlakkig. Dat hangt samen met psychosomatische spanningen in de borst en de buik. Zulke ademhaling geeft de psyche op haar beurt een signaal van stress, wat tot versterking van de stress leidt. Er ontstaat een spiraal waar je moeilijk uitkomt als je niet bewust bent. Hoewel de uitweg eenvoudig is - zodra je stress opmerkt, begin je met je buik te ademen, preciezer gezegd met het onderste deel ervan. Daar bevindt zich de tweede chakra, en in Chinese tradities - de lagere dantian - het belangrijkste reservoir waarin de levenskracht Qi zich verzamelt en wordt opgeslagen. Dus, leg je hand op dat gebied en voel hoe het zachtjes omhoogkomt bij de inademing en omlaaggaat bij de uitademing. Zelfs zonder speciale esoterische technieken stuurt zo''n handeling de zenuwstelsel een veiligheidssignaal, kalmeert het en vermindert het de spanning in het bekkengebied."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-06','intensive-pleasure',6,1,'День: 6','[{"type":"video","vimeoId":"1138380424"},{"type":"text","markdown":"### Совет дня:\n\nОтличайте удовольствие-топливо от удовольствия-транквилизатора. Здоровое удовольствие наполняет вас энергией и вдохновением для дальнейших действий. Деструктивное удовольствие (переедание, запойный просмотр сериалов, бесцельный сёрфинг в сети) лишь на время глушит тревогу, оставляя после себя пустоту и усталость. Каждый раз, выбирая как отдохнуть, спрашивайте себя: «Это удовольствие даст мне силы или отнимет их?»"}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1138380424"},{"type":"text","markdown":"### Tip of the day:\n\nDistinguish pleasure-fuel from pleasure-tranquilizer. Healthy pleasure fills you with energy and inspiration for further actions. Destructive pleasure (overeating, binge-watching TV series, aimless surfing the web) only temporarily silences anxiety, leaving emptiness and fatigue behind. Each time, choosing how to rest, ask yourself: “Will this pleasure give me strength or take it away?”"}],"de":[{"type":"video","vimeoId":"1138380424"},{"type":"text","markdown":"### Tipp des Tages:\n\nUnterscheiden Sie Genuss als Treibstoff von Genuss als Tranquilizer. Gesunder Genuss erfüllt Sie mit Energie und Inspiration für weitere Handlungen. Destruktiver Genuss (Überessen, exzessives Serienschauen, zielloses Surfen im Netz) betäubt die Angst nur zeitweise und hinterlässt Leere und Müdigkeit. Fragen Sie sich jedes Mal, wenn Sie wählen, wie Sie sich erholen: „Gibt mir dieser Genuss Kraft oder nimmt er sie mir?“"}],"fr":[{"type":"video","vimeoId":"1138380424"},{"type":"text","markdown":"### Conseil du jour :\n\nDistinguez le plaisir-carburant du plaisir-tranquillisant. Le plaisir sain vous remplit d’énergie et d’inspiration pour les actions à venir. Le plaisir destructeur (manger à l’excès, regarder des séries en rafale, surfer sans but sur le Net) ne fait qu’étouffer l’anxiété pour un temps, laissant après lui un vide et de la fatigue. Chaque fois, en choisissant comment vous reposer, demandez-vous : « Ce plaisir me donnera-t-il des forces ou me les enlèvera-t-il ? »"}],"it":[{"type":"video","vimeoId":"1138380424"},{"type":"text","markdown":"### Consiglio del giorno:\n\nDistinguete il piacere-carburante dal piacere-tranquillante. Il piacere sano vi riempie di energia e ispirazione per ulteriori azioni. Il piacere distruttivo (abbuffarsi, guardare serie TV in modo compulsivo, navigare in rete senza scopo) attenua solo temporaneamente l’ansia, lasciando dietro di sé vuoto e stanchezza. Ogni volta, scegliendo come riposarvi, chiedetevi: «Questo piacere mi darà forza o me la toglierà?»"}],"es":[{"type":"video","vimeoId":"1138380424"},{"type":"text","markdown":"### Consejo del día:\n\nDistinga el placer-combustible del placer-tranquilizante. El placer saludable lo llena de energía e inspiración para acciones posteriores. El placer destructivo (comer en exceso, ver series de forma compulsiva, navegar sin objetivo por la red) solo silencia la ansiedad por un tiempo, dejando tras de sí vacío y cansancio. Cada vez que elija cómo descansar, pregúntese: «¿Este placer me dará fuerzas o me las quitará?»"}],"pt":[{"type":"video","vimeoId":"1138380424"},{"type":"text","markdown":"### Dica do dia:\n\nDistinga o prazer-combustível do prazer-tranquilizante. O prazer saudável enche você de energia e inspiração para ações futuras. O prazer destrutivo (comer em excesso, maratona compulsiva de séries, navegação sem propósito na internet) apenas abafa a ansiedade por um tempo, deixando depois de si vazio e cansaço. Cada vez, ao escolher como descansar, pergunte a si mesmo: «Esse prazer vai me dar forças ou vai tirá-las?»"}],"nl":[{"type":"video","vimeoId":"1138380424"},{"type":"text","markdown":"### Tip van de dag:\n\nOnderscheid plezier-als-brandstof van plezier-als-tranquillizer. Gezond plezier vervult je met energie en inspiratie voor verdere acties. Destructief plezier (overeten, binge-watching, doelloos surfen op het net) smoort de angst slechts tijdelijk en laat daarna leegte en vermoeidheid achter. Vraag je elke keer als je kiest hoe je uitrust af: «Geeft dit plezier me kracht of neemt het die af?»"}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-07','intensive-pleasure',7,1,'День: 7','[{"type":"video","vimeoId":"1151298926"},{"type":"text","markdown":"### Совет дня:\n\nИспользуйте дискомфорт как сигнальный светодиод. В жизни многих людей столько дискомфорта и одновременно запретов что-то менять, что они предпочитают перестать чувствовать своё тело. Но вы развиваетесь, а значит для вас дискомфорт - это честный советчик, указывающий но то, что что-то идёт не так. Даже очевидно, на уровне тела - неудобная поза, напряжения в каких-то участках - это сигналы, указывающие на необходимость перемен, а не терпения. Игнорировать их - значит предавать свою природу и идти в болезнь, то есть подсознательно выбирать смерть, а не жизнь. Но ваша цель - Жизнь!"}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1151298926"},{"type":"text","markdown":"### Tip of the day:\n\nUse discomfort as a signal LED. In the lives of many people there is so much discomfort and at the same time prohibition against changing something that they prefer to stop feeling their body. But you are developing, which means for you discomfort is an honest adviser pointing to the fact that something is going wrong. Even obviously, at the level of the body—an uncomfortable pose, tension in some areas—these are signals pointing to the need for change, not endurance. To ignore them means to betray your nature and go into illness, that is, subconsciously choose death, not life. But your goal is Life!"}],"de":[{"type":"video","vimeoId":"1151298926"},{"type":"text","markdown":"### Tipp des Tages:\n\nNutzen Sie Unbehagen als signalisierende Leuchtdiode. Im Leben vieler Menschen gibt es so viel Unbehagen und gleichzeitig Verbote, etwas zu ändern, dass sie es vorziehen, aufzuhören, ihren Körper zu spüren. Aber Sie entwickeln sich, und das bedeutet, dass Unbehagen für Sie ein ehrlicher Berater ist, der darauf hinweist, dass etwas nicht stimmt. Sogar offensichtlich auf der Ebene des Körpers – eine unbequeme Haltung, Spannungen in bestimmten Bereichen – sind das Signale, die auf die Notwendigkeit von Veränderungen hinweisen, nicht auf Geduld. Sie zu ignorieren bedeutet, seine Natur zu verraten und in die Krankheit zu gehen, also unbewusst den Tod zu wählen, nicht das Leben. Aber Ihr Ziel ist das Leben!"}],"fr":[{"type":"video","vimeoId":"1151298926"},{"type":"text","markdown":"### Conseil du jour :\n\nUtilisez l’inconfort comme un voyant LED. Dans la vie de nombreuses personnes, il y a tant d’inconfort et en même temps d’interdits de changer quoi que ce soit, qu’elles préfèrent cesser de sentir leur corps. Mais vous, vous vous développez, et donc pour vous l’inconfort est un conseiller honnête, indiquant que quelque chose ne va pas. Même de manière évidente, au niveau du corps — une posture inconfortable, des tensions dans certaines zones — ce sont des signaux indiquant la nécessité du changement, et non de la patience. Les ignorer, c’est trahir sa nature et aller vers la maladie, c’est-à-dire choisir inconsciemment la mort plutôt que la vie. Mais votre but, c’est la Vie !"}],"it":[{"type":"video","vimeoId":"1151298926"},{"type":"text","markdown":"### Consiglio del giorno:\n\nUsate il disagio come un LED di segnalazione. Nella vita di molte persone c’è così tanto disagio e allo stesso tempo così tanti divieti di cambiare qualcosa, che preferiscono smettere di sentire il proprio corpo. Ma voi vi state sviluppando, e quindi per voi il disagio è un consigliere onesto, che indica che qualcosa non va. Anche in modo evidente, a livello del corpo: una posizione scomoda, tensioni in alcune zone sono segnali che indicano la necessità di cambiare, non di pazientare. Ignorarli significa tradire la propria natura e andare verso la malattia, cioè scegliere inconsciamente la morte invece della vita. Ma il vostro obiettivo è la Vita!"}],"es":[{"type":"video","vimeoId":"1151298926"},{"type":"text","markdown":"### Consejo del día:\n\nUtilice el malestar como un led de señalización. En la vida de muchas personas hay tanto malestar y, al mismo tiempo, tantas prohibiciones para cambiar algo, que prefieren dejar de sentir su cuerpo. Pero usted se desarrolla, y eso significa que para usted el malestar es un consejero honesto que indica que algo no va bien. Incluso de forma evidente, a nivel del cuerpo: una postura incómoda, tensiones en algunas zonas son señales que indican la necesidad de cambio, no de paciencia. Ignorarlas significa traicionar su propia naturaleza e ir hacia la enfermedad, es decir, elegir subconscientemente la muerte y no la vida. Pero su objetivo es ¡la Vida!"}],"pt":[{"type":"video","vimeoId":"1151298926"},{"type":"text","markdown":"### Dica do dia:\n\nUse o desconforto como um LED de sinalização. Na vida de muitas pessoas há tanto desconforto e, ao mesmo tempo, tantas proibições de mudar algo, que elas preferem parar de sentir o próprio corpo. Mas você está se desenvolvendo, e isso significa que, para você, o desconforto é um conselheiro honesto, que indica que algo não está indo bem. Até mesmo de forma óbvia, no nível do corpo - uma posição incômoda, tensões em algumas áreas - são sinais que indicam a necessidade de mudança, e não de paciência. Ignorá-los significa trair a própria natureza e caminhar para a doença, ou seja, escolher inconscientemente a morte, e não a vida. Mas o seu objetivo é a Vida!"}],"nl":[{"type":"video","vimeoId":"1151298926"},{"type":"text","markdown":"### Tip van de dag:\n\nGebruik ongemak als een signaal-led. In het leven van veel mensen is er zoveel ongemak en tegelijk zoveel verbod om iets te veranderen, dat ze er de voorkeur aan geven hun lichaam niet meer te voelen. Maar jij ontwikkelt je, en dus is ongemak voor jou een eerlijke raadgever die erop wijst dat er iets niet klopt. Zelfs duidelijk, op lichaamsniveau - een ongemakkelijke houding, spanningen in bepaalde gebieden - zijn signalen die wijzen op de noodzaak van verandering, niet van verdragen. Ze negeren betekent je eigen aard verraden en richting ziekte gaan, dat wil zeggen onbewust de dood kiezen in plaats van het leven. Maar jouw doel is - Leven!"}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-08','intensive-pleasure',8,1,'День: 8','[{"type":"video","vimeoId":"1145500614"},{"type":"text","markdown":"### Совет дня:\n\nРазличайте этапы волны желания. Каждое желание проходит цикл: зарождение (лёгкий интерес) -> рост (возбуждение, действие) -> пик (получение плода) -> удовлетворение (насыщение) -> спад (расслабление). Научитесь распознавать эти фазы в ваших желаниях. Как времена года, желания - это энергии, которые проходят сквозь вас, пока вы живы. Наслаждайтесь не только летом, а каждым днём всех времён года!"}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1145500614"},{"type":"text","markdown":"### Tip of the day:\n\nDistinguish the stages of the wave of desire. Every desire goes through a cycle: origin (light interest) -> growth (excitation, action) -> peak (receiving the fruit) -> satisfaction (satiation) -> decline (relaxation). Learn to recognize these phases in your desires. Like seasons, desires are energies that pass through you while you are alive. Enjoy not only summer, but every day of all seasons of the year!"}],"de":[{"type":"video","vimeoId":"1145500614"},{"type":"text","markdown":"### Tipp des Tages:\n\nUnterscheiden Sie die Phasen der Welle des Verlangens. Jedes Verlangen durchläuft einen Zyklus: Entstehung (leichtes Interesse) -> Wachstum (Erregung, Handlung) -> Höhepunkt (Empfangen der Frucht) -> Befriedigung (Sättigung) -> Abfall (Entspannung). Lernen Sie, diese Phasen in Ihren Verlangen zu erkennen. Wie Jahreszeiten sind Verlangen Energien, die durch Sie hindurchgehen, solange Sie leben. Genießen Sie nicht nur den Sommer, sondern jeden Tag aller Jahreszeiten!"}],"fr":[{"type":"video","vimeoId":"1145500614"},{"type":"text","markdown":"### Conseil du jour :\n\nDistinguez les étapes de la vague du désir. Chaque désir passe par un cycle : naissance (léger intérêt) -> croissance (excitation, action) -> pic (obtention du fruit) -> satisfaction (satiété) -> déclin (relâchement). Apprenez à reconnaître ces phases dans vos désirs. Comme les saisons, les désirs sont des énergies qui passent à travers vous tant que vous êtes vivant. Savourez non seulement l’été, mais chaque jour de toutes les saisons de l’année !"}],"it":[{"type":"video","vimeoId":"1145500614"},{"type":"text","markdown":"### Consiglio del giorno:\n\nDistinguete le fasi dell’onda del desiderio. Ogni desiderio attraversa un ciclo: nascita (leggero interesse) -> crescita (eccitazione, azione) -> picco (ottenimento del frutto) -> soddisfazione (sazietà) -> calo (rilassamento). Imparate a riconoscere queste fasi nei vostri desideri. Come le stagioni, i desideri sono energie che passano attraverso di voi finché siete vivi. Godetevi non solo l’estate, ma ogni giorno di tutte le stagioni!"}],"es":[{"type":"video","vimeoId":"1145500614"},{"type":"text","markdown":"### Consejo del día:\n\nDiferencie las etapas de la ola del deseo. Cada deseo pasa por un ciclo: nacimiento (interés ligero) -> crecimiento (excitación, acción) -> pico (obtención del fruto) -> satisfacción (saciedad) -> descenso (relajación). Aprenda a reconocer estas fases en sus deseos. Como las estaciones del año, los deseos son energías que pasan a través de usted mientras está vivo. ¡Disfrute no solo del verano, sino de cada día de todas las estaciones del año!"}],"pt":[{"type":"video","vimeoId":"1145500614"},{"type":"text","markdown":"### Dica do dia:\n\nDistinga as etapas da onda do desejo. Cada desejo passa por um ciclo: surgimento (interesse leve) -> crescimento (excitação, ação) -> pico (obtenção do fruto) -> satisfação (saciedade) -> declínio (relaxamento). Aprenda a reconhecer essas fases nos seus desejos. Como as estações do ano, os desejos são energias que passam através de você enquanto você está vivo. Aproveite não apenas o verão, mas cada dia de todas as estações do ano!"}],"nl":[{"type":"video","vimeoId":"1145500614"},{"type":"text","markdown":"### Tip van de dag:\n\nOnderscheid de fasen van de golf van verlangen. Elk verlangen doorloopt een cyclus: ontstaan (lichte interesse) -> groei (opwinding, actie) -> piek (de vrucht ontvangen) -> bevrediging (verzadiging) -> afname (ontspanning). Leer deze fasen in je verlangens herkennen. Zoals de seizoenen zijn verlangens energieën die door je heen gaan zolang je leeft. Geniet niet alleen van de zomer, maar van elke dag van alle seizoenen!"}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-09','intensive-pleasure',9,1,'День: 9','[{"type":"video","vimeoId":"1141025937"},{"type":"text","markdown":"### Совет дня:\n\nДобавьте в жизнь ярких красок. Буквально. Носите одежду ярких, сочных цветов. Купите домой яркий плед или картину. Ешьте разноцветные овощи и фрукты. Цвет напрямую влияет на наше эмоциональное состояние, и сознательное добавление ярких пятен в серую рутину помогает пробудить внутреннюю палитру."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1141025937"},{"type":"text","markdown":"### Tip of the day:\n\nAdd bright colors to life. Literally. Wear clothes of bright, juicy colors. Buy a bright blanket or painting for home. Eat multicolored vegetables and fruits. Color directly influences our emotional state, and consciously adding bright spots to the gray routine helps awaken the inner palette."}],"de":[{"type":"video","vimeoId":"1141025937"},{"type":"text","markdown":"### Tipp des Tages:\n\nFügen Sie dem Leben leuchtende Farben hinzu. Buchstäblich. Tragen Sie Kleidung in leuchtenden, satten Farben. Kaufen Sie sich für zu Hause eine leuchtende Decke oder ein Bild. Essen Sie verschiedenfarbiges Gemüse und Obst. Farbe beeinflusst direkt unseren emotionalen Zustand, und das bewusste Hinzufügen leuchtender Flecken in den grauen Alltag hilft, die innere Palette zu erwecken."}],"fr":[{"type":"video","vimeoId":"1141025937"},{"type":"text","markdown":"### Conseil du jour :\n\nAjoutez des couleurs vives à la vie. Littéralement. Portez des vêtements de couleurs vives et éclatantes. Achetez pour la maison un plaid ou un tableau coloré. Mangez des légumes et des fruits de couleurs variées. La couleur influence directement notre état émotionnel, et l’ajout conscient de taches lumineuses dans la grisaille du quotidien aide à éveiller la palette intérieure."}],"it":[{"type":"video","vimeoId":"1141025937"},{"type":"text","markdown":"### Consiglio del giorno:\n\nAggiungete colore alla vita. Letteralmente. Indossate abiti dai colori vivaci e intensi. Comprate per casa una coperta o un quadro colorato. Mangiate verdure e frutta di colori diversi. Il colore influisce direttamente sul nostro stato emotivo, e l’aggiunta consapevole di macchie vivaci alla grigia routine aiuta a risvegliare la tavolozza interiore."}],"es":[{"type":"video","vimeoId":"1141025937"},{"type":"text","markdown":"### Consejo del día:\n\nAñada colores vivos a la vida. Literalmente. Use ropa de colores vivos y jugosos. Compre para casa una manta o un cuadro colorido. Coma verduras y frutas de diversos colores. El color influye directamente en nuestro estado emocional, y añadir conscientemente manchas brillantes a la gris rutina ayuda a despertar la paleta interior."}],"pt":[{"type":"video","vimeoId":"1141025937"},{"type":"text","markdown":"### Dica do dia:\n\nAdicione cores vivas à vida. Literalmente. Use roupas de cores vivas e suculentas. Compre para casa uma manta ou um quadro colorido. Coma vegetais e frutas de cores variadas. A cor influencia diretamente nosso estado emocional, e adicionar conscientemente manchas de cor à rotina cinzenta ajuda a despertar a paleta interior."}],"nl":[{"type":"video","vimeoId":"1141025937"},{"type":"text","markdown":"### Tip van de dag:\n\nVoeg heldere kleuren toe aan je leven. Letterlijk. Draag kleding in felle, sappige kleuren. Koop een felle deken of een schilderij voor thuis. Eet veelkleurige groenten en fruit. Kleur beïnvloedt direct onze emotionele toestand, en het bewust toevoegen van heldere accenten aan de grijze routine helpt het innerlijke palet te wekken."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-10','intensive-pleasure',10,1,'День: 10','[{"type":"video","vimeoId":"1133450832"},{"type":"text","markdown":"### Совет дня:\n\nДелайте \"глупости\" намеренно. Станцуйте странный танец, пока вас никто не видит, скорчите рожицу своему отражению в зеркале, спойте вслух непристойным голосом... Эти маленькие акты спонтанности разрушают броню \"взрослости\" и возвращают доступ к живой, детской энергии. Развивайте способность находиться на волне игривости. Это состояние помогает жить счастливо, избегая ненужных напрягов, и без конфликтов поддерживая личные границы."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1133450832"},{"type":"text","markdown":"### Tip of the day:\n\nDo “silly things” intentionally. Dance a strange dance while no one sees you, make a grimace at your reflection in the mirror, sing aloud in an indecent voice... These small acts of spontaneity destroy the armor of “adulthood” and restore access to living, childlike energy. Develop the ability to be on the wave of playfulness. This state helps to live happily, avoiding unnecessary tensions, and without conflicts maintaining personal boundaries."}],"de":[{"type":"video","vimeoId":"1133450832"},{"type":"text","markdown":"### Tipp des Tages:\n\nMachen Sie absichtlich „Dummheiten“. Tanzen Sie einen seltsamen Tanz, während Sie niemand sieht, schneiden Sie Ihrem Spiegelbild eine Grimasse, singen Sie laut mit einer unanständigen Stimme ... Diese kleinen Akte der Spontaneität zerstören die Rüstung der „Erwachsenheit“ und geben den Zugang zur lebendigen, kindlichen Energie zurück. Entwickeln Sie die Fähigkeit, auf der Welle der Verspieltheit zu sein. Dieser Zustand hilft, glücklich zu leben, unnötigen Stress zu vermeiden und persönliche Grenzen ohne Konflikte zu wahren."}],"fr":[{"type":"video","vimeoId":"1133450832"},{"type":"text","markdown":"### Conseil du jour :\n\nFaites des « bêtises » volontairement. Dansez une danse étrange pendant que personne ne vous voit, faites une grimace à votre reflet dans le miroir, chantez à voix haute d’une voix indécente... Ces petits actes de spontanéité brisent l’armure de l’« âge adulte » et redonnent accès à l’énergie vivante, enfantine. Développez la capacité à rester sur la vague du jeu. Cet état aide à vivre heureux, en évitant les tensions inutiles, et en maintenant ses limites personnelles sans conflits."}],"it":[{"type":"video","vimeoId":"1133450832"},{"type":"text","markdown":"### Consiglio del giorno:\n\nFate «sciocchezze» di proposito. Ballate una danza strana mentre nessuno vi vede, fate una smorfia al vostro riflesso nello specchio, cantate ad alta voce con una voce indecente... Questi piccoli atti di spontaneità distruggono l’armatura dell’«adultità» e restituiscono l’accesso all’energia viva e infantile. Sviluppate la capacità di stare sull’onda della giocosità. Questo stato aiuta a vivere felicemente, evitando tensioni inutili e mantenendo i confini personali senza conflitti."}],"es":[{"type":"video","vimeoId":"1133450832"},{"type":"text","markdown":"### Consejo del día:\n\nHaga «tonterías» a propósito. Baile un baile extraño mientras nadie lo ve, póngale una mueca a su reflejo en el espejo, cante en voz alta con una voz indecente… Estos pequeños actos de espontaneidad destruyen la armadura de la «adultez» y devuelven el acceso a la energía viva e infantil. Desarrolle la capacidad de estar en la ola de la juguetividad. Este estado ayuda a vivir feliz, evitando tensiones innecesarias y manteniendo los límites personales sin conflictos."}],"pt":[{"type":"video","vimeoId":"1133450832"},{"type":"text","markdown":"### Dica do dia:\n\nFaça \"tolices\" de propósito. Dance uma dança estranha enquanto ninguém vê, faça careta para o seu reflexo no espelho, cante em voz alta com uma voz indecente... Esses pequenos atos de espontaneidade quebram a armadura da \"maturidade\" e devolvem o acesso à energia viva e infantil. Desenvolva a capacidade de permanecer na onda da ludicidade. Esse estado ajuda a viver feliz, evitando tensões desnecessárias e mantendo os limites pessoais sem conflitos."}],"nl":[{"type":"video","vimeoId":"1133450832"},{"type":"text","markdown":"### Tip van de dag:\n\nDoe «domme dingen» met opzet. Dans een vreemde dans terwijl niemand je ziet, trek een gek gezicht naar je spiegelbeeld, zing hardop met een onfatsoenlijke stem... Deze kleine daden van spontaniteit breken het pantser van de «volwassenheid» en geven weer toegang tot levende, kinderlijke energie. Ontwikkel het vermogen om op de golf van speelsheid te zijn. Die toestand helpt gelukkig te leven, onnodige spanning te vermijden en persoonlijke grenzen zonder conflicten te handhaven."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-11','intensive-pleasure',11,1,'День: 11','[{"type":"video","vimeoId":"1143370142"},{"type":"text","markdown":"### Совет дня:\n\nЧаще задавайте себе вопрос: \"Чего прямо сейчас я хочу? Какого именно удовольствия?\". Не \"Что ещё я должен успеть сделать сегодня?\", и даже не \"Как провести этот вечер?\", а именно «Чего хочет моё тело для удовольствия?». Хочу попить чаю? Хочу зевнуть и потянуться? Хочу расслабить лоб и погладить лицо ладошками? На уровне второй чакры желания очень просты. Осознавайте их и удовлетворяйте. Ну а то, что \"сложно\" - то в данном случае \"ложно\". Направляйте внимание на эти простые телесные желания. Признавая и удовлетворяя их, вы тренируете свою способность находиться на \"волне хотения\" :)"}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1143370142"},{"type":"text","markdown":"### Tip of the day:\n\nMore often ask yourself: “What do I want right now? What kind of pleasure exactly?” Not “What else must I manage to do today?”, and not even “How to spend this evening?”, but precisely “What does my body want for pleasure?”. Do I want to drink tea? Do I want to yawn and stretch? Do I want to relax my forehead and stroke my face with my palms? At the level of the second chakra desires are very simple. Become aware of them and satisfy them. Well, and what is “difficult”—in this case is “false.” Direct attention to these simple bodily desires. By acknowledging and satisfying them, you train your ability to be on the “wave of wanting” :)"}],"de":[{"type":"video","vimeoId":"1143370142"},{"type":"text","markdown":"### Tipp des Tages:\n\nStellen Sie sich öfter die Frage: „Was will ich genau jetzt? Welchen Genuss genau?“ Nicht „Was muss ich heute noch alles schaffen?“ und auch nicht „Wie verbringe ich diesen Abend?“, sondern genau „Was will mein Körper zum Genuss?“. Will ich Tee trinken? Will ich gähnen und mich strecken? Will ich die Stirn entspannen und das Gesicht mit den Handflächen streicheln? Auf der Ebene des zweiten Chakras sind die Wünsche sehr einfach. Werden Sie sich ihrer bewusst und erfüllen Sie sie. Nun, und das, was „schwierig“ ist, ist in diesem Fall „falsch“. Richten Sie die Aufmerksamkeit auf diese einfachen körperlichen Wünsche. Indem Sie sie anerkennen und erfüllen, trainieren Sie Ihre Fähigkeit, auf der „Welle des Wollens“ zu sein :)"}],"fr":[{"type":"video","vimeoId":"1143370142"},{"type":"text","markdown":"### Conseil du jour :\n\nDemandez-vous plus souvent : « Que veux-je là, tout de suite ? Quel plaisir exactement ? » Pas « Qu’est-ce que je dois encore réussir à faire aujourd’hui ? », et même pas « Comment passer cette soirée ? », mais précisément « Que veut mon corps pour le plaisir ? ». Je veux boire du thé ? Je veux bâiller et m’étirer ? Je veux détendre mon front et caresser mon visage avec mes paumes ? Au niveau du deuxième chakra, les désirs sont très simples. Prenez-en conscience et satisfaites-les. Eh bien, ce qui est « difficile » est dans ce cas « faux ». Dirigez votre attention vers ces simples désirs corporels. En les reconnaissant et en les satisfaisant, vous entraînez votre capacité à rester sur la « vague du vouloir » :)"}],"it":[{"type":"video","vimeoId":"1143370142"},{"type":"text","markdown":"### Consiglio del giorno:\n\nPonetevi più spesso la domanda: «Che cosa voglio proprio adesso? Quale piacere esattamente?». Non «Che cos’altro devo riuscire a fare oggi?», e nemmeno «Come passare questa sera?», ma precisamente «Che cosa vuole il mio corpo per piacere?». Voglio bere un tè? Voglio sbadigliare e stirarmi? Voglio rilassare la fronte e accarezzarmi il viso con i palmi? A livello del secondo chakra i desideri sono molto semplici. Prendetene coscienza e soddisfateli. Ebbene, ciò che è «difficile» in questo caso è «falso». Dirigete l’attenzione verso questi semplici desideri del corpo. Riconoscendoli e soddisfacendoli, allenate la vostra capacità di stare sull’«onda del volere» :)"}],"es":[{"type":"video","vimeoId":"1143370142"},{"type":"text","markdown":"### Consejo del día:\n\nPregúntese más a menudo: «¿Qué quiero ahora mismo? ¿Qué placer exactamente?». No «¿Qué más debo alcanzar a hacer hoy?», ni siquiera «¿Cómo pasar esta tarde?», sino precisamente «¿Qué quiere mi cuerpo para el placer?». ¿Quiero tomar té? ¿Quiero bostezar y estirarme? ¿Quiero relajar la frente y acariciar la cara con las palmas? En el nivel de la segunda chakra los deseos son muy simples. Tome conciencia de ellos y satisfágalos. Y eso que es «difícil», en este caso es «falso». Dirija la atención a esos simples deseos corporales. Al reconocerlos y satisfacerlos, usted entrena su capacidad de estar en la «ola del querer» :)"}],"pt":[{"type":"video","vimeoId":"1143370142"},{"type":"text","markdown":"### Dica do dia:\n\nPergunte-se com mais frequência: \"O que eu quero agora mesmo? Que prazer exatamente?\". Não \"O que mais eu ainda preciso conseguir fazer hoje?\", e nem mesmo \"Como passar esta noite?\", mas sim «O que meu corpo quer para o prazer?». Quero beber um chá? Quero bocejar e me alongar? Quero relaxar a testa e acariciar o rosto com as palmas das mãos? No nível do segundo chakra, os desejos são muito simples. Tome consciência deles e satisfaça-os. E aquilo que é \"difícil\" - neste caso é \"falso\". Direcione a atenção para esses simples desejos corporais. Ao reconhecê-los e satisfazê-los, você treina sua capacidade de permanecer na \"onda do querer\" :)"}],"nl":[{"type":"video","vimeoId":"1143370142"},{"type":"text","markdown":"### Tip van de dag:\n\nStel jezelf vaker de vraag: «Wat wil ik nu meteen? Welk plezier precies?». Niet «Wat moet ik vandaag nog allemaal voor elkaar krijgen?», en zelfs niet «Hoe breng ik deze avond door?», maar precies «Wat wil mijn lichaam voor plezier?». Wil ik thee drinken? Wil ik gapen en strekken? Wil ik mijn voorhoofd ontspannen en mijn gezicht met mijn handpalmen strelen? Op het niveau van de tweede chakra zijn verlangens heel eenvoudig. Word je ze bewust en vervul ze. En wat «moeilijk» is - is in dit geval «onwaar». Richt je aandacht op deze eenvoudige lichamelijke verlangens. Door ze te erkennen en te vervullen, train je je vermogen om op de «golf van willen» te zijn :)"}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-12','intensive-pleasure',12,1,'День: 12','[{"type":"video","vimeoId":"1113808968"},{"type":"text","markdown":"### Совет дня:\n\nДвигайтесь из центра удовольствия. Когда вы идёте,  позвольте своим движениям стать более пластичными и как бы идущими из таза. Это не про вульгарное виляние бёдрами, а про ваше внимание в области таза - на ощущении удовольствия, которое там всегда присутствует, и динамику движения именно от области таза - не от живота, груди, рук или ног - а именно от таза - как бы переливая и усиливая базовое ощущение удовольствия. Освоив такую походку, учитесь все движения выполнять также - движение руки, подъём глаз, поворот головы..."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1113808968"},{"type":"text","markdown":"### Tip of the day:\n\nMove from the center of pleasure. When you walk, allow your movements to become more plastic and as if coming from the pelvis. This is not about vulgar swaying of the hips, but about your attention in the pelvic area—on the sensation of pleasure that is always present there, and the dynamics of movement precisely from the pelvic area—not from the abdomen, chest, arms or legs—but precisely from the pelvis—as if pouring over and amplifying the basic sensation of pleasure. Having mastered such a gait, learn to perform all movements in the same way—the movement of a hand, the raising of the eyes, the turn of the head..."}],"de":[{"type":"video","vimeoId":"1113808968"},{"type":"text","markdown":"### Tipp des Tages:\n\nBewegen Sie sich aus dem Zentrum des Genusses. Wenn Sie gehen, lassen Sie Ihre Bewegungen plastischer werden und gleichsam aus dem Becken kommen. Es geht nicht um vulgäres Hüftwackeln, sondern um Ihre Aufmerksamkeit im Beckenbereich – auf das Gefühl des Genusses, das dort immer gegenwärtig ist, und um die Dynamik der Bewegung genau aus dem Beckenbereich – nicht aus dem Bauch, der Brust, den Armen oder Beinen – sondern genau aus dem Becken – gleichsam das basische Genussgefühl umgießend und verstärkend. Wenn Sie einen solchen Gang beherrschen, lernen Sie, auch alle Bewegungen so auszuführen – die Bewegung der Hand, das Heben der Augen, das Drehen des Kopfes ..."}],"fr":[{"type":"video","vimeoId":"1113808968"},{"type":"text","markdown":"### Conseil du jour :\n\nBougez depuis le centre du plaisir. Lorsque vous marchez, permettez à vos mouvements de devenir plus souples et comme provenant du bassin. Il ne s’agit pas d’un déhanchement vulgaire, mais de votre attention dans la région du bassin — sur la sensation de plaisir qui y est toujours présente, et sur la dynamique du mouvement précisément depuis la région du bassin — pas depuis le ventre, la poitrine, les bras ou les jambes — mais précisément depuis le bassin — comme en faisant refluer et en amplifiant la sensation de base du plaisir. Après avoir maîtrisé une telle démarche, apprenez à exécuter tous les mouvements de la même manière — le mouvement d’un bras, le lever des yeux, le tour de la tête..."}],"it":[{"type":"video","vimeoId":"1113808968"},{"type":"text","markdown":"### Consiglio del giorno:\n\nMuovetevi dal centro del piacere. Quando camminate,  lasciate che i vostri movimenti diventino più plastici e come provenienti dal bacino. Non si tratta di una volgare oscillazione dei fianchi, ma della vostra attenzione nella zona del bacino: sulla sensazione di piacere che è sempre presente lì, e sulla dinamica del movimento proprio dalla zona del bacino, non dalla pancia, dal petto, dalle braccia o dalle gambe, ma proprio dal bacino, come se riversaste e amplificaste la sensazione di base del piacere. Avendo acquisito una tale andatura, imparate a eseguire allo stesso modo tutti i movimenti: il movimento di una mano, il sollevamento degli occhi, il girare della testa..."}],"es":[{"type":"video","vimeoId":"1113808968"},{"type":"text","markdown":"### Consejo del día:\n\nMuévase desde el centro del placer. Cuando camine, permita que sus movimientos se vuelvan más plásticos y como si vinieran de la pelvis. No se trata de un contoneo vulgar de caderas, sino de su atención en la zona de la pelvis: en la sensación de placer que allí siempre está presente, y en la dinámica del movimiento precisamente desde la zona de la pelvis, no desde el abdomen, el pecho, los brazos o las piernas, sino precisamente desde la pelvis, como si derramara y amplificara la sensación básica de placer. Habiendo dominado esa forma de caminar, aprenda a realizar todos los movimientos también así: el movimiento de la mano, el levantar los ojos, el giro de la cabeza…"}],"pt":[{"type":"video","vimeoId":"1113808968"},{"type":"text","markdown":"### Dica do dia:\n\nMova-se a partir do centro do prazer. Quando você caminha, permita que seus movimentos se tornem mais plásticos e como que vindos da pelve. Não se trata de um rebolado vulgar dos quadris, mas da sua atenção na região pélvica - na sensação de prazer que sempre está ali presente, e da dinâmica do movimento justamente a partir da região pélvica - não da barriga, do peito, dos braços ou das pernas - mas justamente da pelve - como que transbordando e intensificando a sensação básica de prazer. Depois de dominar esse modo de andar, aprenda a realizar todos os movimentos também assim - o movimento do braço, o erguer dos olhos, o virar da cabeça..."}],"nl":[{"type":"video","vimeoId":"1113808968"},{"type":"text","markdown":"### Tip van de dag:\n\nBeweeg vanuit het centrum van plezier. Wanneer je loopt, laat je bewegingen dan plastischer worden en als het ware vanuit het bekken komen. Het gaat niet om vulgair wiegen met de heupen, maar om je aandacht in het bekkengebied - op het gevoel van plezier dat daar altijd aanwezig is, en om de dynamiek van de beweging precies vanuit het bekkengebied - niet vanuit de buik, borst, armen of benen - maar precies vanuit het bekken - als het ware het basisgevoel van plezier laten overvloeien en versterken. Als je zo''n loop onder de knie hebt, leer dan alle bewegingen ook zo uit te voeren - de beweging van een arm, het optillen van de ogen, het draaien van het hoofd..."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-13','intensive-pleasure',13,1,'День: 13','[{"type":"video","vimeoId":"1133509635"},{"type":"text","markdown":"### Совет дня:\n\nОтделяйтете сексуальность от секса. Ваша сексуальная энергия - это жизненная сила, а не просто инструмент для секса или деторождения. Позвольте ей просто быть, течь в теле, не требуя немедленной реализации. Ощущайте её как тепло, вибрацию, удовольствие, творческий подъём. Когда вы перестаёте гнаться за сексом, за оргазмом как за целью, вы можете наслаждаться океаном чувственности."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1133509635"},{"type":"text","markdown":"### Tip of the day:\n\nSeparate sexuality from sex. Your sexual energy is life force, and not merely an instrument for sex or childbearing. Allow it simply to be, to flow in the body, without demanding immediate realization. Feel it as warmth, vibration, pleasure, creative upsurge. When you stop chasing sex, chasing orgasm as a goal, you can enjoy the ocean of sensuality."}],"de":[{"type":"video","vimeoId":"1133509635"},{"type":"text","markdown":"### Tipp des Tages:\n\nTrennen Sie Sexualität vom Sex. Ihre sexuelle Energie ist Lebenskraft, nicht bloß ein Werkzeug für Sex oder Fortpflanzung. Erlauben Sie ihr, einfach zu sein, im Körper zu fließen, ohne unmittelbare Verwirklichung zu verlangen. Spüren Sie sie als Wärme, Vibration, Genuss, kreativen Aufschwung. Wenn Sie aufhören, dem Sex, dem Orgasmus als Ziel nachzujagen, können Sie den Ozean der Sinnlichkeit genießen."}],"fr":[{"type":"video","vimeoId":"1133509635"},{"type":"text","markdown":"### Conseil du jour :\n\nSéparez la sexualité du sexe. Votre énergie sexuelle est une force vitale, et non simplement un instrument pour le sexe ou la procréation. Permettez-lui simplement d’être, de couler dans le corps, sans exiger de réalisation immédiate. Sentez-la comme une chaleur, une vibration, un plaisir, une montée créative. Lorsque vous cessez de courir après le sexe, après l’orgasme comme après un but, vous pouvez savourer l’océan de sensualité."}],"it":[{"type":"video","vimeoId":"1133509635"},{"type":"text","markdown":"### Consiglio del giorno:\n\nSeparate la sessualità dal sesso. La vostra energia sessuale è forza vitale, non semplicemente uno strumento per il sesso o per la procreazione. Permettetele semplicemente di essere, di scorrere nel corpo, senza richiedere un’immediata realizzazione. Sentitela come calore, vibrazione, piacere, slancio creativo. Quando smettete di inseguire il sesso, l’orgasmo come obiettivo, potete godervi l’oceano della sensualità."}],"es":[{"type":"video","vimeoId":"1133509635"},{"type":"text","markdown":"### Consejo del día:\n\nSepare la sexualidad del sexo. Su energía sexual es fuerza vital, y no simplemente un instrumento para el sexo o la reproducción. Permítale simplemente ser, fluir en el cuerpo, sin exigir una realización inmediata. Sienta esa energía como calor, vibración, placer, impulso creativo. Cuando usted deja de perseguir el sexo, el orgasmo como objetivo, puede disfrutar del océano de la sensualidad."}],"pt":[{"type":"video","vimeoId":"1133509635"},{"type":"text","markdown":"### Dica do dia:\n\nSepare a sexualidade do sexo. Sua energia sexual é a força vital, e não apenas um instrumento para o sexo ou a reprodução. Permita que ela simplesmente seja, flua no corpo, sem exigir realização imediata. Sinta-a como calor, vibração, prazer, impulso criativo. Quando você para de correr atrás do sexo, do orgasmo como objetivo, pode desfrutar do oceano da sensualidade."}],"nl":[{"type":"video","vimeoId":"1133509635"},{"type":"text","markdown":"### Tip van de dag:\n\nScheid seksualiteit van seks. Je seksuele energie is levenskracht, niet slechts een instrument voor seks of voortplanting. Laat haar gewoon zijn, door het lichaam stromen, zonder onmiddellijke verwezenlijking te eisen. Voel haar als warmte, vibratie, plezier, creatieve opwelling. Wanneer je ophoudt te jagen op seks, op een orgasme als doel, kun je genieten van de oceaan van sensualiteit."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-14','intensive-pleasure',14,1,'День: 14','[{"type":"video","vimeoId":"1132592522"},{"type":"text","markdown":"### Совет дня:\n\nПостоянно расслабляйте тазовое дно. Хронические напряжения в области таза, и особенно тазового дна, указывают на попытки удержать жизнь под контролем, замереть в обороне, страх стыда. Позвольте области таза дышать, двигаться, быть живой. Следите за состоянием этой области в различных жизненных ситуациях - звонок друга, разговор с родителями или ребёнком, конфликт на работе... Ваше тело постоянно реагирует, давая вам чёткие сигналы о блокировках энергии. Расслабляйте блоки, как только их замечаете. Не получается расслабить? Используйте техники йоги - асаны и пранаяму..."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1132592522"},{"type":"text","markdown":"### Tip of the day:\n\nConstantly relax the pelvic floor. Chronic tensions in the pelvic area, and especially the pelvic floor, indicate attempts to keep life under control, to freeze in defense, fear of shame. Allow the pelvic area to breathe, move, be alive. Watch the state of this area in various life situations—a friend’s call, a conversation with parents or a child, a conflict at work... Your body constantly reacts, giving you clear signals about energy blocks. Relax the blocks as soon as you notice them. Not able to relax? Use yoga techniques—asanas and pranayama..."}],"de":[{"type":"video","vimeoId":"1132592522"},{"type":"text","markdown":"### Tipp des Tages:\n\nEntspannen Sie ständig den Beckenboden. Chronische Spannungen im Beckenbereich und besonders im Beckenboden weisen auf Versuche hin, das Leben unter Kontrolle zu halten, in der Abwehr zu erstarren, auf Angst vor Scham. Erlauben Sie dem Beckenbereich, zu atmen, sich zu bewegen, lebendig zu sein. Achten Sie auf den Zustand dieses Bereichs in verschiedenen Lebenssituationen – ein Anruf eines Freundes, ein Gespräch mit Eltern oder Kind, ein Konflikt bei der Arbeit ... Ihr Körper reagiert ständig und gibt Ihnen klare Signale über Energieblockaden. Lockern Sie die Blockaden, sobald Sie sie bemerken. Es gelingt nicht, zu entspannen? Nutzen Sie Yoga-Techniken – Asanas und Pranayama ..."}],"fr":[{"type":"video","vimeoId":"1132592522"},{"type":"text","markdown":"### Conseil du jour :\n\nRelâchez constamment le plancher pelvien. Les tensions chroniques dans la région du bassin, et surtout du plancher pelvien, indiquent des tentatives de garder la vie sous contrôle, de se figer en défense, la peur de la honte. Permettez à la région du bassin de respirer, de bouger, d’être vivante. Surveillez l’état de cette zone dans diverses situations de vie — un appel d’un ami, une conversation avec les parents ou l’enfant, un conflit au travail... Votre corps réagit constamment, vous donnant des signaux clairs sur les blocages d’énergie. Relâchez les blocages dès que vous les remarquez. Vous n’arrivez pas à relâcher ? Utilisez les techniques du yoga — les asanas et le pranayama..."}],"it":[{"type":"video","vimeoId":"1132592522"},{"type":"text","markdown":"### Consiglio del giorno:\n\nRilassate costantemente il pavimento pelvico. Le tensioni croniche nella zona del bacino, e in particolare del pavimento pelvico, indicano tentativi di tenere la vita sotto controllo, di irrigidirsi in difesa, paura della vergogna. Permettete alla zona del bacino di respirare, muoversi, essere viva. Osservate lo stato di questa zona in diverse situazioni della vita: la telefonata di un amico, una conversazione con i genitori o con un figlio, un conflitto al lavoro... Il vostro corpo reagisce costantemente, dandovi segnali chiari sui blocchi energetici. Rilassate i blocchi non appena li notate. Non riuscite a rilassare? Usate le tecniche dello yoga: asana e pranayama..."}],"es":[{"type":"video","vimeoId":"1132592522"},{"type":"text","markdown":"### Consejo del día:\n\nRelaje constantemente el suelo pélvico. Las tensiones crónicas en la zona de la pelvis, y especialmente en el suelo pélvico, indican intentos de mantener la vida bajo control, quedarse inmóvil en la defensa, miedo a la vergüenza. Permita que la zona de la pelvis respire, se mueva, esté viva. Siga el estado de esta zona en diversas situaciones vitales: una llamada de un amigo, una conversación con los padres o con el hijo, un conflicto en el trabajo… Su cuerpo reacciona constantemente, dándole señales claras sobre los bloqueos de energía. Relaje los bloqueos en cuanto los note. ¿No logra relajarlos? Utilice técnicas de yoga: asanas y pranayama…"}],"pt":[{"type":"video","vimeoId":"1132592522"},{"type":"text","markdown":"### Dica do dia:\n\nRelaxe constantemente o assoalho pélvico. Tensões crônicas na região pélvica, e especialmente no assoalho pélvico, indicam tentativas de manter a vida sob controle, de ficar paralisado na defensiva, medo da vergonha. Permita que a região pélvica respire, se mova, esteja viva. Observe o estado dessa região em diversas situações da vida - um telefonema de um amigo, uma conversa com os pais ou com a criança, um conflito no trabalho... Seu corpo reage constantemente, dando a você sinais claros sobre bloqueios de energia. Relaxe os bloqueios assim que os perceber. Não consegue relaxar? Use as técnicas do yoga - asanas e pranayama..."}],"nl":[{"type":"video","vimeoId":"1132592522"},{"type":"text","markdown":"### Tip van de dag:\n\nOntspan voortdurend je bekkenbodem. Chronische spanningen in het bekkengebied, en vooral de bekkenbodem, wijzen op pogingen het leven onder controle te houden, in de verdediging te verstijven, angst voor schaamte. Laat het bekkengebied ademen, bewegen, levend zijn. Let op de toestand van dit gebied in verschillende levenssituaties - een telefoontje van een vriend, een gesprek met ouders of een kind, een conflict op het werk... Je lichaam reageert voortdurend en geeft je duidelijke signalen over energieblokkades. Ontspan de blokkades zodra je ze opmerkt. Lukt het niet om te ontspannen? Gebruik yogatechnieken - asana''s en pranayama..."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-15','intensive-pleasure',15,1,'День: 15','[{"type":"video","vimeoId":"1130421599"},{"type":"text","markdown":"### Совет дня:\n\nВозвращайте внимание в тело. Вместо того чтобы думать о том, насколько приятный чай вы пьёте, почувствуйте его тепло, вкус и аромат. Практикуйте это с каждым действием. Не анализируйте, а именно чувствуйте: воду на коже в душе, текстуру одежды, твёрдость земли под ногами. Это первый шаг к выходу из головы и возвращению в живую Жизнь. Вторым шагом - идите навстречу этому чувству до растворения на атомы, до волны эмоционального оргазма от переполняющего вас чувства - настолько мощного, что в это мгновение знакомая вам Вселенная перестаёт существовать."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1130421599"},{"type":"text","markdown":"### Tip of the day:\n\nReturn your attention to the body. Instead of thinking about how pleasant the tea you are drinking is, feel its warmth, taste, and aroma. Practice this with every action. Do not analyze, but actually feel: the water on your skin in the shower, the texture of your clothes, the firmness of the ground under your feet. This is the first step to coming out of the head and returning to living Life. As a second step, move toward this feeling until you dissolve into atoms, until a wave of emotional orgasm from the feeling that fills you—so powerful that in that instant the Universe familiar to you ceases to exist."}],"de":[{"type":"video","vimeoId":"1130421599"},{"type":"text","markdown":"### Tipp des Tages:\n\nRichten Sie Ihre Aufmerksamkeit wieder auf den Körper. Statt darüber nachzudenken, wie angenehm der Tee ist, den Sie trinken, spüren Sie seine Wärme, seinen Geschmack und sein Aroma. Üben Sie dies bei jeder Handlung. Analysieren Sie nicht, sondern fühlen Sie: das Wasser auf der Haut unter der Dusche, die Textur der Kleidung, die Festigkeit des Bodens unter Ihren Füßen. Das ist der erste Schritt, aus dem Kopf herauszukommen und ins lebendige Leben zurückzukehren. Der zweite Schritt - gehen Sie diesem Gefühl entgegen bis zur Auflösung in Atome, bis zur Welle eines emotionalen Orgasmus durch das Sie überflutende Gefühl - so mächtig, dass in diesem Augenblick das Ihnen bekannte Universum aufhört zu existieren."}],"fr":[{"type":"video","vimeoId":"1130421599"},{"type":"text","markdown":"### Conseil du jour :\n\nRamenez l’attention dans le corps. Au lieu de penser à quel point le thé que vous buvez est agréable, ressentez sa chaleur, son goût et son arôme. Pratiquez cela à chaque action. N’analysez pas, mais ressentez précisément : l’eau sur la peau sous la douche, la texture des vêtements, la dureté de la terre sous vos pieds. C’est le premier pas pour sortir de la tête et revenir dans la Vie vivante. Deuxième pas – allez à la rencontre de cette sensation jusqu’à la dissolution en atomes, jusqu’à une vague d’orgasme émotionnel provoquée par le sentiment qui vous submerge – si puissante qu’en cet instant l’Univers qui vous est familier cesse d’exister."}],"it":[{"type":"video","vimeoId":"1130421599"},{"type":"text","markdown":"### Consiglio del giorno:\n\nRiporta l''attenzione nel corpo. Invece di pensare a quanto è piacevole il tè che stai bevendo, sentine il calore, il gusto e l''aroma. Praticalo con ogni azione. Non analizzare, ma senti davvero: l''acqua sulla pelle nella doccia, la texture dei vestiti, la durezza della terra sotto i piedi. Questo è il primo passo per uscire dalla testa e tornare nella Vita viva. Il secondo passo: vai incontro a questa sensazione fino a dissolverti in atomi, fino a un''onda di orgasmo emotivo per il sentimento che ti inonda — così potente che in quell''istante l''Universo a te familiare smette di esistere."}],"es":[{"type":"video","vimeoId":"1130421599"},{"type":"text","markdown":"### Consejo del día:\n\nDevuelve la atención al cuerpo. En lugar de pensar en lo agradable que es el té que bebes, siente su calor, su sabor y su aroma. Practica esto con cada acción. No analices, sino siente: el agua sobre la piel en la ducha, la textura de la ropa, la dureza de la tierra bajo los pies. Este es el primer paso para salir de la cabeza y regresar a la Vida viva. Segundo paso: ve al encuentro de esa sensación hasta disolverte en átomos, hasta una ola de orgasmo emocional por el sentimiento que te desborda, tan poderoso que en ese instante el Universo que conoces deja de existir."}],"pt":[{"type":"video","vimeoId":"1130421599"},{"type":"text","markdown":"### Dica do dia:\n\nTraga a atenção de volta ao corpo. Em vez de pensar em quão agradável é o chá que você está bebendo, sinta o seu calor, sabor e aroma. Pratique isso com cada ação. Não analise, mas sinta de fato: a água na pele no chuveiro, a textura da roupa, a solidez da terra sob os pés. Este é o primeiro passo para sair da cabeça e voltar à Vida viva. O segundo passo - vá ao encontro desse sentimento até a dissolução em átomos, até uma onda de orgasmo emocional pelo sentimento que transborda em você - tão poderoso que, nesse instante, o Universo que você conhece deixa de existir."}],"nl":[{"type":"video","vimeoId":"1130421599"},{"type":"text","markdown":"### Tip van de dag:\n\nBreng je aandacht terug naar je lichaam. In plaats van te denken aan hoe lekker de thee is die je drinkt, voel de warmte, de smaak en het aroma ervan. Beoefen dit bij elke handeling. Analyseer niet, maar voel juist: het water op je huid in de douche, de textuur van je kleding, de hardheid van de grond onder je voeten. Dit is de eerste stap om uit je hoofd te komen en terug te keren naar het levende Leven. Als tweede stap: ga dat gevoel tegemoet tot je oplost in atomen, tot een golf van emotioneel orgasme door het gevoel dat je overspoelt – zo krachtig dat het universum dat je kent op dat moment ophoudt te bestaan."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-16','intensive-pleasure',16,1,'День: 16','[{"type":"video","vimeoId":"1133373850"},{"type":"text","markdown":"### Совет дня:\n\nНаслаждайтесь предвкушением. Фаза голода и зарождающегося желания - это не мучение, а самостоятельное удовольствие. Наслаждайтесь предвкушением свидания, отпуска, вкусного ужина. Растягивая эту фазу, смакуя её, вы делаете последующее насыщение более глубоким и ярким. В предвкушении содержится не меньше магии, чем в самом событии. Имейте в виду, что это не имеет никакого отношения к привычке откладывать наслаждение \"на потом\". Многие люди живут по принципу \"вот доделаю проект/похудею/заработаю денег - тогда и наслажусь\". Эта ловушка ума крадёт реальное настоящее. Дорога ложка к обеду. И самая лучшая - та, которая у вас в руках :)"}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1133373850"},{"type":"text","markdown":"### Tip of the day:\n\nEnjoy anticipation. The phase of hunger and incipient desire is not torment but a pleasure in its own right. Enjoy the anticipation of a date, a vacation, a delicious dinner. By stretching out this phase and savoring it, you make the subsequent satiation deeper and more vivid. Anticipation contains no less magic than the event itself. Keep in mind that this has nothing to do with the habit of postponing pleasure “for later.” Many people live by the principle “once I finish this project / lose weight / earn money—then I’ll enjoy myself.” This trap of the mind steals the real present. A spoon is precious at dinnertime. And the best one is the one in your hands :)"}],"de":[{"type":"video","vimeoId":"1133373850"},{"type":"text","markdown":"### Tipp des Tages:\n\nGenießen Sie die Vorfreude. Die Phase des Hungers und des entstehenden Verlangens ist keine Qual, sondern ein eigenständiges Vergnügen. Genießen Sie die Vorfreude auf ein Date, einen Urlaub, ein köstliches Abendessen. Indem Sie diese Phase ausdehnen und auskosten, machen Sie die anschließende Sättigung tiefer und intensiver. In der Vorfreude steckt nicht weniger Magie als im Ereignis selbst. Beachten Sie, dass dies nichts mit der Gewohnheit zu tun hat, Genuss „auf später“ zu verschieben. Viele Menschen leben nach dem Prinzip „Wenn ich erst das Projekt fertigstelle/abnehme/Geld verdiene - dann genieße ich“. Diese Falle des Geistes stiehlt die reale Gegenwart. Der Löffel ist zum Mittagessen kostbar. Und die allerbeste - die, die Sie in der Hand halten :)"}],"fr":[{"type":"video","vimeoId":"1133373850"},{"type":"text","markdown":"### Conseil du jour :\n\nSavourez l’anticipation. La phase de faim et de désir naissant n’est pas une torture, mais un plaisir autonome. Savourez l’anticipation d’un rendez-vous, de vacances, d’un dîner délicieux. En étirant cette phase, en la dégustant, vous rendez la satiété qui suit plus profonde et plus vive. L’anticipation contient autant de magie que l’événement lui-même. Gardez à l’esprit que cela n’a aucun rapport avec l’habitude de remettre le plaisir « à plus tard ». Beaucoup de gens vivent selon le principe « dès que je finirai ce projet/que je maigrirai/que je gagnerai de l’argent – alors je me réjouirai ». Ce piège de l’esprit vole le présent réel. Chaque chose en son temps. Et la meilleure – celle que vous avez entre les mains :)"}],"it":[{"type":"video","vimeoId":"1133373850"},{"type":"text","markdown":"### Consiglio del giorno:\n\nGodetevi l''anticipazione. La fase della fame e del desiderio nascente non è un tormento, ma un piacere autonomo. Godetevi l''anticipazione di un appuntamento, di una vacanza, di una cena gustosa. Allungando questa fase, assaporandola, rendete la successiva sazietà più profonda e vivida. Nell''anticipazione c''è non meno magia che nell''evento stesso. Tenete presente che ciò non ha nulla a che fare con l''abitudine di rimandare il piacere \"a dopo\". Molte persone vivono secondo il principio \"appena finisco il progetto/dimagrisco/guadagno soldi — allora sì che me la godrò\". Questa trappola della mente ruba il presente reale. La posata è preziosa quando arriva il pasto. E la migliore è quella che avete in mano :)"}],"es":[{"type":"video","vimeoId":"1133373850"},{"type":"text","markdown":"### Consejo del día:\n\nDisfruta de la anticipación. La fase de hambre y deseo incipiente no es un tormento, sino un placer en sí mismo. Disfruta de la anticipación de una cita, de las vacaciones, de una cena deliciosa. Al alargar esta fase, saboreándola, haces que la saciedad posterior sea más profunda y vívida. En la anticipación hay tanta magia como en el acontecimiento mismo. Ten en cuenta que esto no tiene nada que ver con el hábito de posponer el placer «para después». Muchas personas viven según el principio «cuando termine el proyecto/adelgace/game dinero, entonces disfrutaré». Esta trampa de la mente roba el presente real. Cada cosa a su tiempo. Y la mejor es la que tienes en tus manos :)"}],"pt":[{"type":"video","vimeoId":"1133373850"},{"type":"text","markdown":"### Dica do dia:\n\nAproveite a antecipação. A fase da fome e do desejo nascente não é um tormento, mas um prazer autônomo. Aproveite a antecipação de um encontro, de férias, de um jantar delicioso. Ao alongar essa fase, saboreando-a, você torna a saciação seguinte mais profunda e intensa. Na antecipação há tanta magia quanto no próprio acontecimento. Tenha em mente que isso não tem nenhuma relação com o hábito de adiar o prazer \"para depois\". Muitas pessoas vivem segundo o princípio \"bom, termino o projeto/emagreço/ganho dinheiro - aí sim vou aproveitar\". Essa armadilha da mente rouba o presente real. A colher é preciosa na hora da refeição. E a melhor de todas é a que está nas suas mãos :)"}],"nl":[{"type":"video","vimeoId":"1133373850"},{"type":"text","markdown":"### Tip van de dag:\n\nGeniet van de verwachting. De fase van honger en ontluikend verlangen is geen kwelling, maar een zelfstandig genot. Geniet van de verwachting van een date, een vakantie, een heerlijk diner. Door deze fase te rekken en ervan te smaken, maak je de daaropvolgende verzadiging dieper en levendiger. In de verwachting schuilt niet minder magie dan in de gebeurtenis zelf. Bedenk dat dit niets te maken heeft met de gewoonte om genot \"voor later\" uit te stellen. Veel mensen leven volgens het principe \"eerst dit project afmaken/afvallen/geld verdienen – dan ga ik genieten\". Deze valstrik van de geest steelt het werkelijke heden. Een lepel is het meest waard op etenstijd. En de allerbeste is degene die je in je handen hebt :)"}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-17','intensive-pleasure',17,1,'День: 17','[{"type":"video","vimeoId":"1131966705"},{"type":"text","markdown":"### Совет дня:\n\nДвигайтесь как вода, а не как механизм. Вода - стихия второй чакры. В каждом движении проявляйте плавность. Ходите, танцуйте, занимайтесь любовью, работайте, позволяя импульсу рождаться в нижней части живота - в области таза, и волной расходиться по телу. Избегайте роботизированных, отрывистых движений. Они указывают на психологические автоматизмы, энергетические блоки, зашоренность, костность..."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1131966705"},{"type":"text","markdown":"### Tip of the day:\n\nMove like water, not like a mechanism. Water is the element of the second chakra. Express smoothness in every movement. Walk, dance, make love, work, allowing the impulse to be born in the lower abdomen—in the pelvic area—and spread through the body like a wave. Avoid robotic, jerky movements. They indicate psychological automatisms, energy blocks, blinkeredness, rigidity..."}],"de":[{"type":"video","vimeoId":"1131966705"},{"type":"text","markdown":"### Tipp des Tages:\n\nBewegen Sie sich wie Wasser, nicht wie ein Mechanismus. Wasser ist das Element des zweiten Chakras. Zeigen Sie in jeder Bewegung Flüssigkeit. Gehen, tanzen, lieben, arbeiten Sie, indem Sie den Impuls im Unterbauch - im Bereich des Beckens - entstehen und als Welle durch den Körper fließen lassen. Vermeiden Sie roboterhafte, abgehackte Bewegungen. Sie weisen auf psychologische Automatismen, Energieblockaden, Scheuklappen, Starrheit hin..."}],"fr":[{"type":"video","vimeoId":"1131966705"},{"type":"text","markdown":"### Conseil du jour :\n\nBougez comme l’eau, et non comme un mécanisme. L’eau est l’élément du deuxième chakra. Dans chaque mouvement, manifestez la fluidité. Marchez, dansez, faites l’amour, travaillez, en laissant l’impulsion naître dans le bas du ventre – dans la région du bassin – et se diffuser en vague dans le corps. Évitez les mouvements robotisés, saccadés. Ils indiquent des automatismes psychologiques, des blocages énergétiques, des œillères, de la rigidité..."}],"it":[{"type":"video","vimeoId":"1131966705"},{"type":"text","markdown":"### Consiglio del giorno:\n\nMuovetevi come l''acqua, non come un meccanismo. L''acqua è l''elemento del secondo chakra. In ogni movimento manifestate fluidità. Camminate, ballate, fate l''amore, lavorate, lasciando che l''impulso nasca nella parte inferiore della pancia — nella zona del bacino — e si diffonda per il corpo come un''onda. Evitate movimenti robotizzati e spezzati. Indicano automatismi psicologici, blocchi energetici, ristrettezza mentale, rigidità..."}],"es":[{"type":"video","vimeoId":"1131966705"},{"type":"text","markdown":"### Consejo del día:\n\nMuévete como el agua, no como un mecanismo. El agua es el elemento del segundo chakra. En cada movimiento manifiesta fluidez. Camina, baila, haz el amor, trabaja, permitiendo que el impulso nazca en la parte baja del abdomen, en la zona de la pelvis, y se expanda por el cuerpo como una ola. Evita los movimientos robotizados y entrecortados. Indican automatismos psicológicos, bloqueos energéticos, estrechez de miras, rigidez..."}],"pt":[{"type":"video","vimeoId":"1131966705"},{"type":"text","markdown":"### Dica do dia:\n\nMova-se como água, e não como um mecanismo. A água é o elemento do segundo chakra. Em cada movimento, manifeste fluidez. Caminhe, dance, faça amor, trabalhe, permitindo que o impulso nasça na parte inferior da barriga - na região da pelve - e se espalhe pelo corpo como uma onda. Evite movimentos robotizados e entrecortados. Eles indicam automatismos psicológicos, bloqueios energéticos, visão estreita, rigidez..."}],"nl":[{"type":"video","vimeoId":"1131966705"},{"type":"text","markdown":"### Tip van de dag:\n\nBeweeg als water, niet als een mechanisme. Water is het element van de tweede chakra. Laat in elke beweging vloeiendheid zien. Loop, dans, bedrijf de liefde, werk, en laat de impuls ontstaan in het onderste deel van je buik – in het bekkengebied – en als een golf door je lichaam uitwaaieren. Vermijd robotachtige, schokkerige bewegingen. Ze wijzen op psychologische automatismen, energieblokkades, bekrompenheid, starheid..."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-18','intensive-pleasure',18,1,'День: 18','[{"type":"video","vimeoId":"1134820277"},{"type":"text","markdown":"### Совет дня:\n\nРазвивайте гибкость. Когда рушатся планы, не упирайтесь рогом. Представьте, что вы река, которая встречает на пути валун. Река не пытается его сломать, она просто обтекает его. Вода - стихия второй чакры. Гибкость тела, ума, характера - это единое качество. Умение легко менять курс в ответ на внешние обстоятельства - признак молодости и ключевой навык социальной адаптации и процветания. Начинайте саморазвитие с асан на гибкость - так проще и логично :)"}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1134820277"},{"type":"text","markdown":"### Tip of the day:\n\nDevelop flexibility. When plans fall apart, don’t dig in your heels. Imagine that you are a river encountering a boulder on its path. The river does not try to break it; it simply flows around it. Water is the element of the second chakra. Flexibility of body, mind, and character is a single quality. The ability to easily change course in response to external circumstances is a sign of youth and a key skill for social adaptation and prosperity. Begin self-development with asanas for flexibility—it’s simpler and logical that way :)"}],"de":[{"type":"video","vimeoId":"1134820277"},{"type":"text","markdown":"### Tipp des Tages:\n\nEntwickeln Sie Flexibilität. Wenn Pläne scheitern, stemmen Sie sich nicht stur dagegen. Stellen Sie sich vor, Sie seien ein Fluss, der auf seinem Weg einen Felsbrocken trifft. Der Fluss versucht nicht, ihn zu zerbrechen, er fließt einfach um ihn herum. Wasser ist das Element des zweiten Chakras. Flexibilität des Körpers, des Geistes, des Charakters ist eine einzige Eigenschaft. Die Fähigkeit, den Kurs leicht als Reaktion auf äußere Umstände zu ändern, ist ein Zeichen von Jugend und eine Schlüsselfertigkeit sozialer Anpassung und des Gedeihens. Beginnen Sie die Selbstentwicklung mit Asanas für Flexibilität - so ist es einfacher und logisch :)"}],"fr":[{"type":"video","vimeoId":"1134820277"},{"type":"text","markdown":"### Conseil du jour :\n\nDéveloppez la souplesse. Quand les plans s’effondrent, ne vous entêtez pas. Imaginez que vous êtes une rivière qui rencontre un rocher sur son chemin. La rivière n’essaie pas de le casser, elle le contourne simplement. L’eau est l’élément du deuxième chakra. La souplesse du corps, de l’esprit, du caractère est une seule et même qualité. La capacité de changer facilement de cap en réponse aux circonstances extérieures est un signe de jeunesse et une compétence clé d’adaptation sociale et de prospérité. Commencez le développement personnel par des asanas de souplesse – c’est plus simple et logique :)"}],"it":[{"type":"video","vimeoId":"1134820277"},{"type":"text","markdown":"### Consiglio del giorno:\n\nSviluppate la flessibilità. Quando i piani crollano, non impuntatevi. Immaginate di essere un fiume che incontra un masso. Il fiume non cerca di spezzarlo, semplicemente lo aggira. L''acqua è l''elemento del secondo chakra. La flessibilità del corpo, della mente, del carattere è un''unica qualità. La capacità di cambiare facilmente rotta in risposta alle circostanze esterne è un segno di giovinezza e un''abilità chiave di adattamento sociale e prosperità. Iniziate lo sviluppo personale con le asana per la flessibilità — è più semplice e logico :)"}],"es":[{"type":"video","vimeoId":"1134820277"},{"type":"text","markdown":"### Consejo del día:\n\nDesarrolla la flexibilidad. Cuando los planes se derrumban, no te aferres con terquedad. Imagina que eres un río que encuentra una roca en su camino. El río no intenta romperla, simplemente la rodea. El agua es el elemento del segundo chakra. La flexibilidad del cuerpo, de la mente y del carácter son una sola cualidad. La capacidad de cambiar de rumbo con facilidad en respuesta a las circunstancias externas es señal de juventud y una habilidad clave para la adaptación social y la prosperidad. Comienza el autodesarrollo con asanas de flexibilidad: así es más fácil y lógico :)"}],"pt":[{"type":"video","vimeoId":"1134820277"},{"type":"text","markdown":"### Dica do dia:\n\nDesenvolva a flexibilidade. Quando os planos desmoronam, não se obstine. Imagine que você é um rio que encontra um rochedo no caminho. O rio não tenta quebrá-lo, apenas contorna-o. A água é o elemento do segundo chakra. A flexibilidade do corpo, da mente, do caráter - é uma qualidade única. A capacidade de mudar de curso facilmente em resposta às circunstâncias externas - é um sinal de juventude e uma habilidade-chave de adaptação social e prosperidade. Comece o autodesenvolvimento com asanas de flexibilidade - assim é mais simples e lógico :)"}],"nl":[{"type":"video","vimeoId":"1134820277"},{"type":"text","markdown":"### Tip van de dag:\n\nOntwikkel flexibiliteit. Wanneer plannen in duigen vallen, zet je niet koppig schrap. Stel je voor dat je een rivier bent die onderweg een rotsblok tegenkomt. De rivier probeert het niet te breken, ze stroomt er eenvoudig omheen. Water is het element van de tweede chakra. Flexibiliteit van lichaam, geest en karakter is één kwaliteit. Het vermogen om gemakkelijk van koers te veranderen in reactie op externe omstandigheden is een teken van jeugdigheid en een sleutelvaardigheid voor sociale aanpassing en voorspoed. Begin je zelfontwikkeling met asana''s voor flexibiliteit – zo is het eenvoudiger en logisch :)"}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-19','intensive-pleasure',19,1,'День: 19','[{"type":"video","vimeoId":"1127056090"},{"type":"text","markdown":"### Совет дня:\n\nУчитесь чувствовать когда вам достаточно. Процесс наслаждения имеет начало, пик и завершение. Учитесь распознавать точку, где \"приятно\" переходит в \"слишком много\". Это касается еды, отдыха, общения, работы, и конечно же секса. Вовремя остановиться - это не самозапрет, а форма уважения к себе и к источнику удовольствия, позволяющая избежать пресыщения, зависимости, \"ожирения\", отвращения... На более глубоком уровне понимания речь идёт о практике (принципе) йоги под названием Брахмачарья. Эта практика ведёт к освобождению от желаний. То есть желания остаются, но уже не они управляют вами, а вы управляете ими, как упряжкой лошадей."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1127056090"},{"type":"text","markdown":"### Tip of the day:\n\nLearn to feel when you have had enough. The process of enjoyment has a beginning, a peak, and a completion. Learn to recognize the point where “pleasant” turns into “too much.” This applies to food, rest, communication, work, and of course sex. Stopping in time is not self-prohibition but a form of respect for yourself and for the source of pleasure, allowing you to avoid surfeit, dependence, “obesity,” disgust... At a deeper level of understanding, this is about the yoga practice (principle) called Brahmacharya. This practice leads to liberation from desires. That is, desires remain, but it is no longer they who control you; you control them, like a team of horses."}],"de":[{"type":"video","vimeoId":"1127056090"},{"type":"text","markdown":"### Tipp des Tages:\n\nLernen Sie zu spüren, wann es Ihnen genug ist. Der Prozess des Genießens hat einen Anfang, einen Höhepunkt und ein Ende. Lernen Sie den Punkt zu erkennen, an dem „angenehm“ in „zu viel“ übergeht. Das betrifft Essen, Erholung, Kommunikation, Arbeit und natürlich Sex. Rechtzeitig innezuhalten ist kein Selbstverbot, sondern eine Form des Respekts vor sich selbst und vor der Quelle der Freude, die Übersättigung, Abhängigkeit, „Fettleibigkeit“, Ekel vermeiden hilft... Auf einer tieferen Verständnisebene geht es um die Yogapraxis (das Prinzip) namens Brahmacharya. Diese Praxis führt zur Befreiung von Wünschen. Das heißt, die Wünsche bleiben, aber nicht sie beherrschen Sie, sondern Sie beherrschen sie wie ein Gespann Pferde."}],"fr":[{"type":"video","vimeoId":"1127056090"},{"type":"text","markdown":"### Conseil du jour :\n\nApprenez à sentir quand vous en avez assez. Le processus de jouissance a un début, un pic et une fin. Apprenez à reconnaître le point où « agréable » passe à « trop ». Cela concerne la nourriture, le repos, la communication, le travail et, bien sûr, le sexe. S’arrêter à temps n’est pas une auto-interdiction, mais une forme de respect envers soi-même et envers la source du plaisir, permettant d’éviter la satiété, la dépendance, l’« obésité », le dégoût... À un niveau de compréhension plus profond, il s’agit de la pratique (du principe) du yoga appelée Brahmacharya. Cette pratique mène à la libération des désirs. C’est-à-dire que les désirs restent, mais ce n’est plus eux qui vous gouvernent, c’est vous qui les gouvernez, comme un attelage de chevaux."}],"it":[{"type":"video","vimeoId":"1127056090"},{"type":"text","markdown":"### Consiglio del giorno:\n\nImparate a sentire quando ne avete abbastanza. Il processo del godimento ha un inizio, un picco e una conclusione. Imparate a riconoscere il punto in cui \"piacevole\" diventa \"troppo\". Questo vale per il cibo, il riposo, la comunicazione, il lavoro e, naturalmente, il sesso. Fermarsi in tempo non è un''autoproibizione, ma una forma di rispetto verso se stessi e verso la fonte del piacere, che permette di evitare sazietà eccessiva, dipendenza, \"obesità\", disgusto... A un livello di comprensione più profondo si tratta della pratica (principio) dello yoga chiamata Brahmacharya. Questa pratica conduce alla liberazione dai desideri. Cioè i desideri restano, ma non sono più loro a controllare voi: siete voi a controllarli, come una pariglia di cavalli."}],"es":[{"type":"video","vimeoId":"1127056090"},{"type":"text","markdown":"### Consejo del día:\n\nAprende a sentir cuándo ya tienes suficiente. El proceso de disfrute tiene un inicio, un pico y un final. Aprende a reconocer el punto en el que «agradable» pasa a «demasiado». Esto se aplica a la comida, el descanso, la comunicación, el trabajo y, por supuesto, al sexo. Detenerse a tiempo no es una autoprohibición, sino una forma de respeto hacia ti y hacia la fuente de placer, que permite evitar la saciedad excesiva, la dependencia, la «obesidad», la repulsión... En un nivel más profundo de comprensión se trata de la práctica (principio) de yoga llamada Brahmacharya. Esta práctica conduce a la liberación de los deseos. Es decir, los deseos permanecen, pero ya no son ellos los que te gobiernan, sino que tú los gobiernas a ellos, como a una yunta de caballos."}],"pt":[{"type":"video","vimeoId":"1127056090"},{"type":"text","markdown":"### Dica do dia:\n\nAprenda a sentir quando você já tem o suficiente. O processo de prazer tem início, pico e conclusão. Aprenda a reconhecer o ponto em que \"agradável\" passa a \"demais\". Isso vale para comida, descanso, convivência, trabalho e, é claro, sexo. Parar a tempo não é uma autoproibição, mas uma forma de respeito por si mesmo e pela fonte de prazer, que permite evitar a saturação, a dependência, a \"obesidade\", a aversão... Em um nível mais profundo de compreensão, trata-se da prática (princípio) de yoga chamada Brahmacharya. Essa prática leva à libertação dos desejos. Ou seja, os desejos permanecem, mas não são mais eles que governam você, e sim você que os governa, como uma parelha de cavalos."}],"nl":[{"type":"video","vimeoId":"1127056090"},{"type":"text","markdown":"### Tip van de dag:\n\nLeer voelen wanneer je genoeg hebt. Het proces van genieten heeft een begin, een piek en een einde. Leer het punt herkennen waar \"aangenaam\" overgaat in \"te veel\". Dit geldt voor eten, rust, contact, werk en natuurlijk ook seks. Op tijd stoppen is geen zelfverbod, maar een vorm van respect voor jezelf en voor de bron van genot, waardoor je oververzadiging, afhankelijkheid, \"obesitas\", walging... voorkomt. Op een dieper niveau van begrip gaat het om de yogapraktijk (het principe) die Brahmacharya heet. Deze praktijk leidt tot bevrijding van verlangens. Dat wil zeggen: de verlangens blijven, maar niet langer besturen zij jou; jij bestuurt hen, als een span paarden."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-20','intensive-pleasure',20,1,'День: 20','[{"type":"video","vimeoId":"1144405376"},{"type":"text","markdown":"### Совет дня:\n\nОсваивайте искусство смакования! Превратите каждый приём пищи в ритуал. Не ешьте автоматически, проглатывая куски под ленту новостей. Отложите телефон, полностью переключите внимание на еду, и чувствуйте каждый оттенок вкуса, каждую нотку аромата... Этот принцип распространяется на всё: смакуйте момент тишины, интересную беседу, выполняемую работу. Жизнь, которую не смакуют, проходит мимо!"}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1144405376"},{"type":"text","markdown":"### Tip of the day:\n\nMaster the art of savoring! Turn every meal into a ritual. Don’t eat automatically, swallowing pieces to the news feed. Put the phone aside, switch your attention completely to the food, and feel every shade of taste, every note of aroma... This principle applies to everything: savor a moment of silence, an interesting conversation, the work you are doing. Life that is not savored passes by!"}],"de":[{"type":"video","vimeoId":"1144405376"},{"type":"text","markdown":"### Tipp des Tages:\n\nMeistern Sie die Kunst des Auskostens! Verwandeln Sie jede Mahlzeit in ein Ritual. Essen Sie nicht automatisch, indem Sie Brocken zum Nachrichtenstrom hinunterschlucken. Legen Sie das Telefon weg, richten Sie Ihre Aufmerksamkeit vollständig auf das Essen und spüren Sie jede Geschmacksnuance, jede Aromanote... Dieses Prinzip gilt für alles: Kosten Sie den Moment der Stille, ein interessantes Gespräch, die ausgeführte Arbeit aus. Das Leben, das man nicht auskostet, zieht vorbei!"}],"fr":[{"type":"video","vimeoId":"1144405376"},{"type":"text","markdown":"### Conseil du jour :\n\nMaîtrisez l’art de la dégustation ! Transformez chaque repas en rituel. Ne mangez pas automatiquement, en avalant des morceaux devant le fil d’actualité. Posez le téléphone, basculez complètement l’attention sur la nourriture, et sentez chaque nuance de goût, chaque note d’arôme... Ce principe s’étend à tout : savourez un moment de silence, une conversation intéressante, le travail en cours. La vie que l’on ne savoure pas passe à côté !"}],"it":[{"type":"video","vimeoId":"1144405376"},{"type":"text","markdown":"### Consiglio del giorno:\n\nPadroneggiate l''arte di assaporare! Trasformate ogni pasto in un rituale. Non mangiate automaticamente, inghiottendo bocconi sotto il notiziario. Mettete via il telefono, spostate completamente l''attenzione sul cibo e sentite ogni sfumatura di gusto, ogni nota di aroma... Questo principio si estende a tutto: assaporate il momento di silenzio, una conversazione interessante, il lavoro che svolgete. La vita che non si assapora passa accanto!"}],"es":[{"type":"video","vimeoId":"1144405376"},{"type":"text","markdown":"### Consejo del día:\n\n¡Domina el arte de saborear! Convierte cada comida en un ritual. No comas de forma automática, tragando bocados mientras ves el torrente de noticias. Deja el teléfono, cambia por completo la atención a la comida y siente cada matiz del sabor, cada nota del aroma... Este principio se extiende a todo: saborea el momento de silencio, una conversación interesante, el trabajo que realizas. ¡La vida que no se saborea pasa de largo!"}],"pt":[{"type":"video","vimeoId":"1144405376"},{"type":"text","markdown":"### Dica do dia:\n\nDomine a arte de saborear! Transforme cada refeição em um ritual. Não coma automaticamente, engolindo pedaços ao som do feed de notícias. Deixe o telefone de lado, mude completamente a atenção para a comida e sinta cada matiz de sabor, cada nota de aroma... Esse princípio se estende a tudo: saboreie o momento de silêncio, uma conversa interessante, o trabalho que está sendo feito. A vida que não é saboreada passa ao lado!"}],"nl":[{"type":"video","vimeoId":"1144405376"},{"type":"text","markdown":"### Tip van de dag:\n\nBeheers de kunst van het smaken! Maak van elke maaltijd een ritueel. Eet niet automatisch, terwijl je stukken doorslikt bij een nieuwsfeed. Leg je telefoon weg, richt je aandacht volledig op het eten en voel elke tint van de smaak, elke noot van het aroma... Dit principe geldt voor alles: geniet met aandacht van een moment van stilte, een interessant gesprek, het werk dat je doet. Een leven waarvan niet met aandacht genoten wordt, gaat aan je voorbij!"}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-21','intensive-pleasure',21,1,'День: 21','[{"type":"video","vimeoId":"1114592896"},{"type":"text","markdown":"### Совет дня:\n\nВерните удовольствие с \"территории греха\". Многие культуры и религии веками демонизировали удовольствие, связывая его с виной и наказанием. Прямо сейчас сознательно разорвите эту нейронную связь в своём уме. Отныне удовольствие для вас - это то, что вы получили вместе с рождением. Теперь ваше тело целиком - это сплошная эрогенная зона. Только установки в голове ранее ограничивали её несколькими точками, а порой и вовсе запрещали. Теперь наслаждение всегда с вами! Это божественный дар! Это язык, на котором клеточки вашего тела общаются друг с другом!\n\nА ещё хочу напомнить известное стихотворение:\n\nЯ пришёл к тебе с приветом,\nРассказать, что солнце встало,\nЧто оно горячим светом\nПо листам затрепетало;\n\nРассказать, что лес проснулся,\nВесь проснулся, веткой каждой,\nКаждой птицей встрепенулся\nИ весенней полон жаждой;\n\nРассказать, что с той же страстью,\nКак вчера, пришёл я снова,\nЧто душа всё так же счастью\nИ тебе служить готова;\n\nРассказать, что отовсюду\nНа меня весельем веет,\nЧто не знаю сам, что буду\nПеть - но только песня зреет.\n \nАфанасий Фет"}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1114592896"},{"type":"text","markdown":"### Tip of the day:\n\nBring pleasure back from “the territory of sin.” For centuries, many cultures and religions demonized pleasure, linking it with guilt and punishment. Right now, consciously break this neural connection in your mind. From now on, pleasure for you is what you received along with birth. Now your whole body is one continuous erogenous zone. Only the attitudes in your head previously limited it to a few points, and sometimes forbade it altogether. Now enjoyment is always with you! It is a divine gift! It is the language in which the cells of your body communicate with each other!\n\nAnd I also want to remind you of a well-known poem:\n\nI came to you with a greeting,\nTo tell you that the sun has risen,\nThat with its hot light\nIt has begun to tremble over the leaves;\n\nTo tell you that the forest has awakened,\nHas all awakened, with every branch,\nHas stirred with every bird\nAnd is full of spring thirst;\n\nTo tell you that with the same passion,\nAs yesterday, I have come again,\nThat the soul is still as ready for happiness\nAnd to serve you;\n\nTo tell you that from everywhere\nA cheerfulness blows upon me,\nThat I do not know myself what I will\nSing—but the song is only ripening.\n \nAfanasy Fet"}],"de":[{"type":"video","vimeoId":"1114592896"},{"type":"text","markdown":"### Tipp des Tages:\n\nHolen Sie das Vergnügen vom „Territorium der Sünde“ zurück. Viele Kulturen und Religionen haben das Vergnügen jahrhundertelang dämonisiert und es mit Schuld und Strafe verbunden. Trennen Sie genau jetzt bewusst diese neuronale Verbindung in Ihrem Geist. Von nun an ist Vergnügen für Sie etwas, das Sie mit der Geburt erhalten haben. Jetzt ist Ihr Körper ganz und gar eine durchgängige erogene Zone. Nur die Einstellungen im Kopf beschränkten sie früher auf einige wenige Punkte und verboten sie mitunter sogar ganz. Jetzt ist der Genuss immer bei Ihnen! Das ist ein göttliches Geschenk! Das ist die Sprache, in der die Zellen Ihres Körpers miteinander kommunizieren!\n\nUnd ich möchte noch an ein bekanntes Gedicht erinnern:\n\nIch kam zu dir mit einem Gruß,\nZu erzählen, dass die Sonne aufgegangen ist,\nDass sie mit heißem Licht\nAuf den Blättern zu zittern begann;\n\nZu erzählen, dass der Wald erwacht ist,\nGanz erwacht ist, mit jedem Zweig,\nMit jedem Vogel aufgeschreckt,\nUnd von Frühlingsdurst erfüllt;\n\nZu erzählen, dass ich mit derselben Leidenschaft,\nWie gestern, wieder gekommen bin,\nDass die Seele ebenso dem Glück\nUnd dir zu dienen bereit ist;\n\nZu erzählen, dass von überall\nMir Fröhlichkeit entgegenweht,\nDass ich selbst nicht weiß, was ich\nSingen werde - aber nur das Lied reift.\n \nAfanassi Fet"}],"fr":[{"type":"video","vimeoId":"1114592896"},{"type":"text","markdown":"### Conseil du jour :\n\nRamenez le plaisir depuis le « territoire du péché ». Pendant des siècles, de nombreuses cultures et religions ont diabolisé le plaisir, l’associant à la culpabilité et au châtiment. Ici et maintenant, rompez consciemment cette connexion neuronale dans votre esprit. Désormais, le plaisir est pour vous ce que vous avez reçu avec la naissance. Maintenant, votre corps tout entier est une zone érogène continue. Seuls les conditionnements dans la tête la limitaient auparavant à quelques points, et parfois l’interdisaient même complètement. Maintenant, la jouissance est toujours avec vous ! C’est un don divin ! C’est la langue avec laquelle les cellules de votre corps communiquent entre elles !\n\nEt je veux aussi rappeler un poème célèbre :\n\nJe suis venu à toi avec un salut,\nTe dire que le soleil s’est levé,\nQu’il a d’un éclat brûlant\nFait frémir les feuilles ;\n\nTe dire que la forêt s’est réveillée,\nToute réveillée, à chaque branche,\nÀ chaque oiseau a tressailli\nEt est pleine de soif printanière ;\n\nTe dire qu’avec la même passion,\nComme hier, je suis revenu,\nQue l’âme est toujours prête au bonheur\nEt à te servir ;\n\nTe dire que de partout\nSouffle sur moi la gaieté,\nQue je ne sais moi-même ce que je vais\nChanter - mais seule la chanson mûrit.\n \nAfanassi Fet"}],"it":[{"type":"video","vimeoId":"1114592896"},{"type":"text","markdown":"### Consiglio del giorno:\n\nRiportate il piacere dal territorio del peccato. Molte culture e religioni per secoli hanno demonizzato il piacere, legandolo a colpa e punizione. Proprio ora spezzate consapevolmente questa connessione neurale nella vostra mente. D''ora in poi il piacere per voi è ciò che avete ricevuto insieme alla nascita. Ora il vostro corpo intero è un''unica zona erogena. Solo i condizionamenti nella testa in precedenza la limitavano a pochi punti, e talvolta la vietavano del tutto. Ora il godimento è sempre con voi! È un dono divino! È il linguaggio con cui le cellule del vostro corpo comunicano tra loro!\n\nE inoltre voglio ricordare una poesia famosa:\n\nSono venuto da te con un saluto,\nPer dirti che il sole è sorto,\nChe con la sua luce calda\nSulle foglie ha tremato;\n\nPer dirti che il bosco si è svegliato,\nTutto si è svegliato, in ogni ramo,\nIn ogni uccello si è scosso\nEd è pieno di sete primaverile;\n\nPer dirti che con la stessa passione,\nCome ieri, sono venuto di nuovo,\nChe l''anima è ancora pronta alla felicità\nE a servire te;\n\nPer dirti che da ogni parte\nMi soffia addosso un''allegria,\nChe non so io stesso che cosa\nCanterò — ma solo la canzone matura.\n \nAfanasij Fet"}],"es":[{"type":"video","vimeoId":"1114592896"},{"type":"text","markdown":"### Consejo del día:\n\nDevuelve el placer desde el «territorio del pecado». Muchas culturas y religiones demonizaron el placer durante siglos, asociándolo con la culpa y el castigo. Ahora mismo, rompe conscientemente esa conexión neuronal en tu mente. De ahora en adelante, el placer para ti es lo que recibiste junto con el nacimiento. Ahora todo tu cuerpo es una zona erógena continua. Solo que las creencias en la cabeza antes la limitaban a unos pocos puntos y, a veces, incluso la prohibían por completo. ¡Ahora el disfrute está siempre contigo! ¡Es un regalo divino! ¡Es el lenguaje con el que las células de tu cuerpo se comunican entre sí!\n\nY además quiero recordar un conocido poema:\n\nVine a ti con un saludo,\npara contarte que el sol ha salido,\nque con su luz ardiente\nha temblado sobre las hojas;\n\npara contarte que el bosque ha despertado,\nque ha despertado entero, con cada rama,\nque se ha estremecido con cada pájaro\ny está lleno de sed primaveral;\n\npara contarte que con la misma pasión,\ncomo ayer, he venido de nuevo,\nque el alma sigue igual de dispuesta\na servir a la felicidad y a ti;\n\npara contarte que de todas partes\nme llega un soplo de alegría,\nque yo mismo no sé qué voy\na cantar, pero la canción está madurando.\n \nAfanasi Fet"}],"pt":[{"type":"video","vimeoId":"1114592896"},{"type":"text","markdown":"### Dica do dia:\n\nTraga o prazer de volta do \"território do pecado\". Muitas culturas e religiões, durante séculos, demonizaram o prazer, associando-o à culpa e ao castigo. Agora mesmo, conscientemente, rompa essa conexão neural em sua mente. De agora em diante, o prazer para você é aquilo que você recebeu junto com o nascimento. Agora seu corpo inteiro é uma zona erógena contínua. Apenas as crenças na cabeça antes a limitavam a alguns pontos e, por vezes, até a proibiam por completo. Agora o prazer está sempre com você! É um dom divino! É a linguagem na qual as células do seu corpo se comunicam entre si!\n\nE também quero lembrar um poema conhecido:\n\nEu vim até você com um cumprimento,\nDizer que o sol nasceu,\nQue com sua luz quente\nTremulou sobre as folhas;\n\nDizer que a floresta despertou,\nDespertou inteira, com cada ramo,\nCom cada pássaro estremeceu\nE está plena de sede primaveril;\n\nDizer que com a mesma paixão,\nComo ontem, vim de novo,\nQue a alma continua igualmente à felicidade\nE a você servir pronta;\n\nDizer que de todos os lados\nSopra sobre mim uma alegria,\nQue não sei eu mesmo o que vou\nCantar - mas a canção apenas amadurece.\n \nAfanássi Fét"}],"nl":[{"type":"video","vimeoId":"1114592896"},{"type":"text","markdown":"### Tip van de dag:\n\nHaal plezier terug van \"het terrein van de zonde\". Veel culturen en religies hebben plezier eeuwenlang gedemoniseerd en het aan schuld en straf gekoppeld. Verbreek nu bewust deze neurale verbinding in je geest. Voortaan is plezier voor jou iets dat je bij je geboorte hebt gekregen. Nu is je hele lichaam één doorlopende erogene zone. Alleen de overtuigingen in je hoofd beperkten die voorheen tot een paar punten en verboden haar soms zelfs helemaal. Nu is genot altijd bij je! Het is een goddelijke gave! Het is de taal waarmee de cellen van je lichaam met elkaar communiceren!\n\nEn ik wil ook nog een bekend gedicht in herinnering brengen:\n\nIk ben naar je gekomen met een groet,\nOm te vertellen dat de zon is opgestaan,\nDat zij met heet licht\nOver de bladeren is gaan trillen;\n\nOm te vertellen dat het bos is ontwaakt,\nHelemaal ontwaakt, met elke tak,\nMet elke vogel opgeschrikt\nEn vol van lentedorst;\n\nOm te vertellen dat ik met dezelfde hartstocht,\nZoals gisteren, opnieuw ben gekomen,\nDat de ziel nog steeds aan het geluk\nEn aan jou dienstbaar wil zijn;\n\nOm te vertellen dat van overal\nVrolijkheid mij tegemoet waait,\nDat ik zelf niet weet, wat ik zal\nZingen – maar alleen het lied rijpt.\n \nAfanasi Fet"}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-22','intensive-pleasure',22,1,'День: 22','[{"type":"video","vimeoId":"1128566486"},{"type":"text","markdown":"### Совет дня:\n\nДайте себе право на удовольствие. Удовольствие - это не награда за страдания и не грех, который нужно искупить. Это ваше неотъемлемое право по факту рождения, базовое топливо для жизни. Перестаньте извиняться за свою радость или искать ей оправдания. Позволяя себе наслаждаться, вы сообщаете миру, что достойны его даров."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1128566486"},{"type":"text","markdown":"### Tip of the day:\n\nGive yourself the right to pleasure. Pleasure is not a reward for suffering and not a sin that must be atoned for. It is your inalienable right by the fact of birth, the basic fuel for life. Stop apologizing for your joy or seeking justifications for it. By allowing yourself to enjoy, you tell the world that you are worthy of its gifts."}],"de":[{"type":"video","vimeoId":"1128566486"},{"type":"text","markdown":"### Tipp des Tages:\n\nGeben Sie sich das Recht auf Vergnügen. Vergnügen ist keine Belohnung für Leiden und keine Sünde, die gesühnt werden muss. Es ist Ihr unveräußerliches Recht durch die Tatsache der Geburt, der Grundbrennstoff fürs Leben. Hören Sie auf, sich für Ihre Freude zu entschuldigen oder Rechtfertigungen für sie zu suchen. Indem Sie sich erlauben zu genießen, teilen Sie der Welt mit, dass Sie ihrer Gaben würdig sind."}],"fr":[{"type":"video","vimeoId":"1128566486"},{"type":"text","markdown":"### Conseil du jour :\n\nDonnez-vous le droit au plaisir. Le plaisir n’est pas une récompense pour les souffrances, ni un péché qu’il faut expier. C’est votre droit inaliénable du fait de la naissance, le carburant de base pour la vie. Cessez de vous excuser pour votre joie ou de lui chercher des justifications. En vous permettant de jouir, vous signalez au monde que vous êtes digne de ses dons."}],"it":[{"type":"video","vimeoId":"1128566486"},{"type":"text","markdown":"### Consiglio del giorno:\n\nDatevi il diritto al piacere. Il piacere non è una ricompensa per le sofferenze né un peccato da espiare. È il vostro diritto inalienabile per il fatto stesso della nascita, il carburante di base per la vita. Smettete di scusarvi per la vostra gioia o di cercare giustificazioni. Permettendovi di godere, comunicate al mondo che siete degni dei suoi doni."}],"es":[{"type":"video","vimeoId":"1128566486"},{"type":"text","markdown":"### Consejo del día:\n\nDate el derecho al placer. El placer no es una recompensa por el sufrimiento ni un pecado que haya que expiar. Es tu derecho inalienable por el hecho de nacer, el combustible básico para la vida. Deja de disculparte por tu alegría o de buscar justificaciones para ella. Al permitirte disfrutar, le comunicas al mundo que eres digno de sus dones."}],"pt":[{"type":"video","vimeoId":"1128566486"},{"type":"text","markdown":"### Dica do dia:\n\nDê a si mesmo o direito ao prazer. O prazer não é uma recompensa pelo sofrimento nem um pecado que precisa ser expiado. É o seu direito inalienável pelo fato de ter nascido, o combustível básico para a vida. Pare de se desculpar pela sua alegria ou de buscar justificativas para ela. Ao permitir-se desfrutar, você comunica ao mundo que é digno dos seus dons."}],"nl":[{"type":"video","vimeoId":"1128566486"},{"type":"text","markdown":"### Tip van de dag:\n\nGeef jezelf het recht op plezier. Plezier is geen beloning voor lijden en geen zonde die moet worden uitgeboet. Het is je onvervreemdbare recht op grond van je geboorte, de basisbrandstof voor het leven. Stop met je te verontschuldigen voor je vreugde of er rechtvaardiging voor te zoeken. Door jezelf toe te staan te genieten, laat je de wereld weten dat je zijn gaven waard bent."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-23','intensive-pleasure',23,1,'День: 23','[{"type":"video","vimeoId":"1133381433"},{"type":"text","markdown":"### Совет дня:\n\nРазрешите сексуальной энергии не иметь партнёра. Ваша сексуальная энергия - это творческая жизненная сила. Если у вас нет партнёра, не подавляйте её и не считайте её ненужной. Напротив, с благодарностью принимайте возможность исследовать разные уровни возбуждения и сексуального желания. Учитесь наслаждаться ими, при невозможности \"сбросить\" их, торопясь быстрее заняться сексом - отбросить, как горячий пирожок, который жжёт руки. Вы заметите, что когда вы не запрещаете себе наслаждаться этой энергией, оставаясь с вами она делает ваше тело более чувственным, психику более живой, а жизнь - яркой."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1133381433"},{"type":"text","markdown":"### Tip of the day:\n\nAllow your sexual energy not to have a partner. Your sexual energy is creative life force. If you do not have a partner, do not suppress it and do not consider it unnecessary. On the contrary, gratefully accept the opportunity to explore different levels of arousal and sexual desire. Learn to enjoy them when you cannot “discharge” them by hurrying to have sex—to toss them aside like a hot pie that burns your hands. You will notice that when you do not forbid yourself to enjoy this energy, its remaining with you makes your body more sensual, your psyche more alive, and your life bright."}],"de":[{"type":"video","vimeoId":"1133381433"},{"type":"text","markdown":"### Tipp des Tages:\n\nErlauben Sie der sexuellen Energie, keinen Partner zu haben. Ihre sexuelle Energie ist schöpferische Lebenskraft. Wenn Sie keinen Partner haben, unterdrücken Sie sie nicht und halten Sie sie nicht für unnötig. Im Gegenteil, nehmen Sie mit Dankbarkeit die Möglichkeit an, verschiedene Ebenen der Erregung und des sexuellen Verlangens zu erforschen. Lernen Sie, sie zu genießen, wenn es unmöglich ist, sie „abzulassen“, indem Sie sich beeilen, schnell Sex zu haben - sie wegzuwerfen wie ein heißes Pastetchen, das die Hände verbrennt. Sie werden bemerken, dass, wenn Sie sich nicht verbieten, diese Energie zu genießen, sie, während sie bei Ihnen bleibt, Ihren Körper sinnlicher, Ihre Psyche lebendiger und Ihr Leben strahlender macht."}],"fr":[{"type":"video","vimeoId":"1133381433"},{"type":"text","markdown":"### Conseil du jour :\n\nPermettez à l’énergie sexuelle de ne pas avoir de partenaire. Votre énergie sexuelle est une force vitale créatrice. Si vous n’avez pas de partenaire, ne la réprimez pas et ne la considérez pas comme inutile. Au contraire, acceptez avec gratitude la possibilité d’explorer différents niveaux d’excitation et de désir sexuel. Apprenez à en jouir lorsqu’il est impossible de les « évacuer » en se dépêchant de faire l’amour – de les jeter comme un petit pain chaud qui vous brûle les mains. Vous remarquerez que, lorsque vous ne vous interdisez pas de jouir de cette énergie, en restant avec vous, elle rend votre corps plus sensuel, votre psychisme plus vivant et votre vie plus lumineuse."}],"it":[{"type":"video","vimeoId":"1133381433"},{"type":"text","markdown":"### Consiglio del giorno:\n\nPermettete all''energia sessuale di non avere un partner. La vostra energia sessuale è forza vitale creativa. Se non avete un partner, non sopprimetela e non consideratela inutile. Al contrario, accogliete con gratitudine la possibilità di esplorare diversi livelli di eccitazione e desiderio sessuale. Imparate a goderne, quando non potete \"scaricarli\" affrettandovi a fare sesso — gettarli via come un pasticcino caldo che brucia le mani. Noterete che, quando non vi vietate di godere di questa energia, restando con voi essa rende il vostro corpo più sensuale, la psiche più viva e la vita luminosa."}],"es":[{"type":"video","vimeoId":"1133381433"},{"type":"text","markdown":"### Consejo del día:\n\nPermite que tu energía sexual no tenga pareja. Tu energía sexual es fuerza vital creativa. Si no tienes pareja, no la reprimas ni la consideres innecesaria. Al contrario, acepta con gratitud la posibilidad de explorar distintos niveles de excitación y deseo sexual. Aprende a disfrutarlos cuando no sea posible «descargarlos» apresurándote a tener sexo para desecharlos como un pastelito caliente que quema las manos. Notarás que, cuando no te prohíbes disfrutar de esta energía, al permanecer contigo ella hace tu cuerpo más sensual, tu psique más viva y tu vida más brillante."}],"pt":[{"type":"video","vimeoId":"1133381433"},{"type":"text","markdown":"### Dica do dia:\n\nPermita que a energia sexual não tenha parceiro. Sua energia sexual é a força vital criativa. Se você não tem parceiro, não a reprima e não a considere inútil. Ao contrário, aceite com gratidão a possibilidade de explorar diferentes níveis de excitação e desejo sexual. Aprenda a desfrutar deles, quando não for possível \"descartá-los\", apressando-se para fazer sexo mais rápido - jogá-los fora como um pastel quente que queima as mãos. Você notará que, quando você não se proíbe de desfrutar dessa energia, permanecendo com você, ela torna seu corpo mais sensível, sua psique mais viva e sua vida mais intensa."}],"nl":[{"type":"video","vimeoId":"1133381433"},{"type":"text","markdown":"### Tip van de dag:\n\nSta toe dat seksuele energie geen partner heeft. Je seksuele energie is een creatieve levenskracht. Als je geen partner hebt, onderdruk haar dan niet en beschouw haar niet als onnodig. Integendeel, aanvaard met dankbaarheid de mogelijkheid om verschillende niveaus van opwinding en seksueel verlangen te onderzoeken. Leer ervan te genieten, als je ze niet kunt \"afvoeren\" door haastig seks te gaan hebben – ze weg te gooien als een heet pasteitje dat je handen brandt. Je zult merken dat wanneer je jezelf niet verbiedt van deze energie te genieten, zij, terwijl ze bij je blijft, je lichaam sensueler maakt, je psyche levendiger en je leven stralend."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-24','intensive-pleasure',24,1,'День: 24','[{"type":"video","vimeoId":"1153853898"},{"type":"text","markdown":"### Совет дня:\n\nПереформатируйте \"надо\" в \"хочу\". Постарайтесь находить в каждом \"надо\" элемент своего \"хочу\". Вам \"надо\" идти на работу? А что вы \"хотите\" получить от неё - деньги, самореализацию, общение? Всего лишь смещая фокус с долга на желание, вы меняете биохимию процесса: вместо гормонов стресса вырабатываются гормоны мотивации и удовольствия."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1153853898"},{"type":"text","markdown":"### Tip of the day:\n\nReformat “must” into “want.” Try to find an element of your “want” in every “must.” Do you “must” go to work? And what do you “want” to get from it—money, self-realization, communication? Merely by shifting the focus from duty to desire, you change the biochemistry of the process: instead of stress hormones, hormones of motivation and pleasure are produced."}],"de":[{"type":"video","vimeoId":"1153853898"},{"type":"text","markdown":"### Tipp des Tages:\n\nFormatieren Sie das „Müssen“ in ein „Wollen“ um. Versuchen Sie, in jedem „Müssen“ ein Element Ihres „Wollens“ zu finden. Sie „müssen“ zur Arbeit gehen? Und was „wollen“ Sie davon bekommen - Geld, Selbstverwirklichung, Kommunikation? Allein durch die Verschiebung des Fokus von Pflicht auf Verlangen verändern Sie die Biochemie des Prozesses: Statt Stresshormonen werden Motivations- und Glückshormone produziert."}],"fr":[{"type":"video","vimeoId":"1153853898"},{"type":"text","markdown":"### Conseil du jour :\n\nReformatez le « il faut » en « je veux ». Efforcez-vous de trouver dans chaque « il faut » un élément de votre « je veux ». Vous « devez » aller au travail ? Mais qu’est-ce que vous « voulez » en obtenir – de l’argent, une réalisation de soi, de la communication ? Rien qu’en déplaçant le focus du devoir vers le désir, vous changez la biochimie du processus : au lieu des hormones du stress, se produisent les hormones de la motivation et du plaisir."}],"it":[{"type":"video","vimeoId":"1153853898"},{"type":"text","markdown":"### Consiglio del giorno:\n\nRiformattate il \"devo\" in \"voglio\". Cercate di trovare in ogni \"devo\" un elemento del vostro \"voglio\". Dovete andare al lavoro? E cosa volete ottenere da esso — denaro, autorealizzazione, comunicazione? Solo spostando il focus dal dovere al desiderio, cambiate la biochimica del processo: invece degli ormoni dello stress vengono prodotti ormoni della motivazione e del piacere."}],"es":[{"type":"video","vimeoId":"1153853898"},{"type":"text","markdown":"### Consejo del día:\n\nReformatea el «tengo que» en «quiero». Procura encontrar en cada «tengo que» un elemento de tu «quiero». ¿Tienes que ir al trabajo? ¿Y qué quieres obtener de él: dinero, autorrealización, comunicación? Tan solo desplazando el foco del deber al deseo, cambias la bioquímica del proceso: en lugar de hormonas de estrés se producen hormonas de motivación y placer."}],"pt":[{"type":"video","vimeoId":"1153853898"},{"type":"text","markdown":"### Dica do dia:\n\nReformate o \"preciso\" em \"quero\". Tente encontrar em cada \"preciso\" um elemento do seu \"quero\". Você \"precisa\" ir ao trabalho? E o que você \"quer\" obter dele - dinheiro, autorrealização, convivência? Apenas deslocando o foco do dever para o desejo, você muda a bioquímica do processo: em vez de hormônios do estresse, são produzidos hormônios da motivação e do prazer."}],"nl":[{"type":"video","vimeoId":"1153853898"},{"type":"text","markdown":"### Tip van de dag:\n\nHerformateer \"moeten\" naar \"willen\". Probeer in elke \"moeten\" een element van je eigen \"willen\" te vinden. Je \"moet\" naar je werk? En wat \"wil\" je ervan krijgen – geld, zelfrealisatie, contact? Alleen al door de focus te verschuiven van plicht naar verlangen, verander je de biochemie van het proces: in plaats van stresshormonen worden motivatie- en plezierhormonen aangemaakt."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-25','intensive-pleasure',25,1,'День: 25','[{"type":"video","vimeoId":"1133368787"},{"type":"text","markdown":"### Совет дня:\n\nИспользуйте игру при решении проблем. Когда вы зашли в тупик в рабочем проекте или в отношениях, попробуйте сменить серьёзный подход на игровой. Задайте себе вопрос: «А как бы я решил эту задачу, если бы это была игра?». Игровой подход активирует творческое мышление и помогает найти нестандартные выходы."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1133368787"},{"type":"text","markdown":"### Tip of the day:\n\nUse play when solving problems. When you have reached a dead end in a work project or in a relationship, try changing your serious approach to a playful one. Ask yourself: “How would I solve this task if it were a game?” A playful approach activates creative thinking and helps find unconventional ways out."}],"de":[{"type":"video","vimeoId":"1133368787"},{"type":"text","markdown":"### Tipp des Tages:\n\nNutzen Sie das Spiel beim Lösen von Problemen. Wenn Sie in einem Arbeitsprojekt oder in einer Beziehung in eine Sackgasse geraten sind, versuchen Sie, den ernsten Ansatz durch einen spielerischen zu ersetzen. Stellen Sie sich die Frage: „Wie würde ich diese Aufgabe lösen, wenn es ein Spiel wäre?“ Der spielerische Ansatz aktiviert kreatives Denken und hilft, unkonventionelle Auswege zu finden."}],"fr":[{"type":"video","vimeoId":"1133368787"},{"type":"text","markdown":"### Conseil du jour :\n\nUtilisez le jeu pour résoudre les problèmes. Lorsque vous êtes dans une impasse dans un projet professionnel ou dans une relation, essayez de remplacer l’approche sérieuse par une approche ludique. Posez-vous la question : « Comment résoudrais-je cette tâche si c’était un jeu ? ». L’approche ludique active la pensée créative et aide à trouver des issues non standard."}],"it":[{"type":"video","vimeoId":"1133368787"},{"type":"text","markdown":"### Consiglio del giorno:\n\nUsate il gioco nella risoluzione dei problemi. Quando siete in un vicolo cieco in un progetto di lavoro o in una relazione, provate a sostituire l''approccio serio con quello ludico. Chiedetevi: «Come risolverei questo compito se fosse un gioco?». L''approccio ludico attiva il pensiero creativo e aiuta a trovare vie d''uscita non standard."}],"es":[{"type":"video","vimeoId":"1133368787"},{"type":"text","markdown":"### Consejo del día:\n\nUsa el juego para resolver problemas. Cuando hayas llegado a un callejón sin salida en un proyecto de trabajo o en una relación, prueba a cambiar el enfoque serio por uno lúdico. Pregúntate: «¿Cómo resolvería esta tarea si fuera un juego?». El enfoque lúdico activa el pensamiento creativo y ayuda a encontrar salidas no convencionales."}],"pt":[{"type":"video","vimeoId":"1133368787"},{"type":"text","markdown":"### Dica do dia:\n\nUse o jogo na resolução de problemas. Quando você chegar a um impasse em um projeto de trabalho ou em um relacionamento, tente trocar a abordagem séria pela lúdica. Faça a si mesmo a pergunta: «E como eu resolveria esta tarefa se isto fosse um jogo?». A abordagem lúdica ativa o pensamento criativo e ajuda a encontrar saídas não padronizadas."}],"nl":[{"type":"video","vimeoId":"1133368787"},{"type":"text","markdown":"### Tip van de dag:\n\nGebruik spel bij het oplossen van problemen. Wanneer je vastloopt in een werkproject of in een relatie, probeer dan de serieuze aanpak te verruilen voor een speelse. Stel jezelf de vraag: \"En hoe zou ik deze taak oplossen als het een spel was?\" De speelse aanpak activeert creatief denken en helpt niet-standaardoplossingen te vinden."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-26','intensive-pleasure',26,1,'День: 26','[{"type":"video","vimeoId":"1107653291"},{"type":"text","markdown":"### Совет дня:\n\nПрисушивайтесь к шёпоту тела, чтобы не услышать его крик. Тело всегда предупреждает о проблемах заранее - лёгкой усталостью, тянущей болью, дискомфортом. Если игнорировать этот шёпот, он превратится в крик - в болезнь. Развивайте чувствительность к тонким ощущениям и реагируйте на них сразу. Как же реагировать? Так как мы говорим о  сигналах тела, то и реакция в первую очередь должна быть на уровне тела. Что-то сжалось в животе? Сделайте несколько амплитудных вдохов выдохов в полумосте. Выбирайте очевидные решения. Дальше ниточка может потянуться к психологической или поведенческой коррекции. Она тоже очевидна в большинстве случаев, но пойти против якобы \"собственной природы\" значительно сложнее, чем отреагировать на уровне тела."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1107653291"},{"type":"text","markdown":"### Tip of the day:\n\nListen to the whisper of the body so as not to hear its scream. The body always warns about problems in advance—with slight fatigue, a nagging pain, discomfort. If you ignore this whisper, it will turn into a scream—into illness. Develop sensitivity to subtle sensations and react to them immediately. How should you react? Since we are talking about signals of the body, the reaction should first of all be at the level of the body. Something has tightened in your abdomen? Do several full-amplitude inhales and exhales in a half-bridge. Choose obvious solutions. Further, the thread may lead to psychological or behavioral correction. It too is obvious in most cases, but going against supposedly “one’s own nature” is significantly harder than responding at the level of the body."}],"de":[{"type":"video","vimeoId":"1107653291"},{"type":"text","markdown":"### Tipp des Tages:\n\nHören Sie auf das Flüstern des Körpers, um seinen Schrei nicht zu hören. Der Körper warnt immer im Voraus vor Problemen - mit leichter Müdigkeit, ziehendem Schmerz, Unbehagen. Wenn Sie dieses Flüstern ignorieren, wird es zu einem Schrei - zur Krankheit. Entwickeln Sie die Empfindlichkeit für feine Empfindungen und reagieren Sie sofort auf sie. Wie aber reagieren? Da wir über Signale des Körpers sprechen, sollte die Reaktion in erster Linie auf der Ebene des Körpers erfolgen. Etwas hat sich im Bauch zusammengezogen? Machen Sie in der Halbbrücke einige Ein- und Ausatmungen mit großer Amplitude. Wählen Sie offensichtliche Lösungen. Weiter kann der Faden zu einer psychologischen oder verhaltensbezogenen Korrektur führen. Sie ist in den meisten Fällen ebenfalls offensichtlich, aber gegen die sogenannte „eigene Natur“ zu handeln ist deutlich schwieriger, als auf der Ebene des Körpers zu reagieren."}],"fr":[{"type":"video","vimeoId":"1107653291"},{"type":"text","markdown":"### Conseil du jour :\n\nÉcoutez le chuchotement du corps pour ne pas entendre son cri. Le corps prévient toujours des problèmes à l’avance – par une légère fatigue, une douleur sourde, un inconfort. Si vous ignorez ce chuchotement, il se transformera en cri – en maladie. Développez la sensibilité aux sensations subtiles et réagissez-y immédiatement. Comment réagir ? Puisque nous parlons de signaux du corps, la réaction doit d’abord se faire au niveau du corps. Quelque chose s’est serré dans le ventre ? Faites quelques inspirations-expirations amples dans le demi-pont. Choisissez des solutions évidentes. Ensuite, le fil peut conduire à une correction psychologique ou comportementale. Elle est elle aussi évidente dans la plupart des cas, mais aller contre ce qui est prétendument « sa propre nature » est bien plus difficile que de réagir au niveau du corps."}],"it":[{"type":"video","vimeoId":"1107653291"},{"type":"text","markdown":"### Consiglio del giorno:\n\nAscoltate il sussurro del corpo per non doverne udire il grido. Il corpo avverte sempre in anticipo dei problemi — con una leggera stanchezza, un dolore sordo, un disagio. Se ignorate questo sussurro, si trasformerà in un grido — in malattia. Sviluppate la sensibilità alle sensazioni sottili e reagite subito a esse. Come reagire? Dato che parliamo di segnali del corpo, anche la reazione dovrebbe essere innanzitutto a livello del corpo. Qualcosa si è contratto nella pancia? Fate alcuni ampi respiri, inspirazioni ed espirazioni, nel mezzo ponte. Scegliete soluzioni ovvie. Poi il filo può tendersi verso una correzione psicologica o comportamentale. Anche quella è ovvia nella maggior parte dei casi, ma andare contro la presunta \"propria natura\" è molto più difficile che reagire a livello del corpo."}],"es":[{"type":"video","vimeoId":"1107653291"},{"type":"text","markdown":"### Consejo del día:\n\nEscucha el susurro del cuerpo para no oír su grito. El cuerpo siempre advierte sobre los problemas de antemano: con un ligero cansancio, un dolor sordo, una incomodidad. Si ignoras ese susurro, se convertirá en un grito: en enfermedad. Desarrolla la sensibilidad a las sensaciones sutiles y reacciona a ellas de inmediato. ¿Cómo reaccionar? Puesto que hablamos de señales del cuerpo, la reacción debe ser ante todo a nivel del cuerpo. ¿Se contrajo algo en el abdomen? Haz varias inhalaciones y exhalaciones amplias en medio puente. Elige soluciones obvias. Después, el hilo puede llevarte a una corrección psicológica o conductual. Ella también es obvia en la mayoría de los casos, pero ir contra la supuesta «propia naturaleza» es mucho más difícil que reaccionar a nivel del cuerpo."}],"pt":[{"type":"video","vimeoId":"1107653291"},{"type":"text","markdown":"### Dica do dia:\n\nEscute o sussurro do corpo para não ouvir o seu grito. O corpo sempre avisa sobre problemas com antecedência - com um leve cansaço, uma dor persistente, um desconforto. Se você ignorar esse sussurro, ele se transformará em grito - em doença. Desenvolva a sensibilidade a sensações sutis e reaja a elas imediatamente. Como reagir? Já que estamos falando de sinais do corpo, a reação, em primeiro lugar, deve ser no nível do corpo. Algo se contraiu na barriga? Faça algumas inspirações e expirações amplas na meia-ponte. Escolha soluções óbvias. Depois, o fio pode levar a uma correção psicológica ou comportamental. Ela também é óbvia na maioria dos casos, mas ir contra a suposta \"própria natureza\" é significativamente mais difícil do que reagir no nível do corpo."}],"nl":[{"type":"video","vimeoId":"1107653291"},{"type":"text","markdown":"### Tip van de dag:\n\nLuister naar het gefluister van je lichaam, zodat je zijn schreeuw niet hoeft te horen. Het lichaam waarschuwt altijd van tevoren voor problemen – met lichte vermoeidheid, een zeurende pijn, ongemak. Als je dit gefluister negeert, verandert het in een schreeuw – in ziekte. Ontwikkel gevoeligheid voor subtiele sensaties en reageer er meteen op. Hoe dan te reageren? Omdat we het over signalen van het lichaam hebben, moet de reactie in de eerste plaats op lichaamsniveau plaatsvinden. Is er iets in je buik samengetrokken? Doe een paar ruime in- en uitademingen in de halve brug. Kies voor de hand liggende oplossingen. Daarna kan het draadje zich uitstrekken naar psychologische of gedragscorrectie. Die is in de meeste gevallen ook voor de hand liggend, maar tegen zogenaamde \"eigen natuur\" ingaan is aanzienlijk moeilijker dan op lichaamsniveau reageren."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-27','intensive-pleasure',27,1,'День: 27','[{"type":"video","vimeoId":"1111560203"},{"type":"text","markdown":"### Совет дня:\n\nБольше общайтесь с \"сочными\" людьми. Окружите себя людьми, которые любят жизнь, умеют радоваться, полны энергии и страсти. Их жизненная сила заразительна. Избегайте хронических нытиков и циников - они, как энергетические вампиры, могут высосать вашу \"сочность\" до капли."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1111560203"},{"type":"text","markdown":"### Tip of the day:\n\nSpend more time with “juicy” people. Surround yourself with people who love life, know how to rejoice, and are full of energy and passion. Their vitality is contagious. Avoid chronic whiners and cynics—like energy vampires, they can suck out your “juiciness” to the last drop."}],"de":[{"type":"video","vimeoId":"1111560203"},{"type":"text","markdown":"### Tipp des Tages:\n\nVerkehren Sie mehr mit „saftigen“ Menschen. Umgeben Sie sich mit Menschen, die das Leben lieben, sich freuen können, voller Energie und Leidenschaft sind. Ihre Lebenskraft ist ansteckend. Meiden Sie chronische Nörgler und Zyniker - sie können wie energetische Vampire Ihre „Saftigkeit“ bis auf den letzten Tropfen aussaugen."}],"fr":[{"type":"video","vimeoId":"1111560203"},{"type":"text","markdown":"### Conseil du jour :\n\nFréquentez davantage de personnes « juteuses ». Entourez-vous de gens qui aiment la vie, savent se réjouir, sont pleins d’énergie et de passion. Leur force vitale est contagieuse. Évitez les râleurs chroniques et les cyniques – tels des vampires énergétiques, ils peuvent aspirer votre « jutosité » jusqu’à la dernière goutte."}],"it":[{"type":"video","vimeoId":"1111560203"},{"type":"text","markdown":"### Consiglio del giorno:\n\nFrequentate di più le persone \"succose\". Circondatevi di persone che amano la vita, sanno gioire, sono piene di energia e passione. La loro forza vitale è contagiosa. Evitate i lamentosi cronici e i cinici — come vampiri energetici, possono succhiarvi tutta la vostra \"succosità\" fino all''ultima goccia."}],"es":[{"type":"video","vimeoId":"1111560203"},{"type":"text","markdown":"### Consejo del día:\n\nRelaciónate más con personas «jugosas». Rodéate de personas que aman la vida, saben alegrarse, están llenas de energía y pasión. Su fuerza vital es contagiosa. Evita a los quejumbrosos crónicos y a los cínicos: ellos, como vampiros energéticos, pueden chuparte hasta la última gota de tu «jugosidad»."}],"pt":[{"type":"video","vimeoId":"1111560203"},{"type":"text","markdown":"### Dica do dia:\n\nConverse mais com pessoas \"suculentas\". Cerque-se de pessoas que amam a vida, sabem se alegrar, são cheias de energia e paixão. A força vital delas é contagiosa. Evite queixosos crônicos e cínicos - eles, como vampiros energéticos, podem sugar a sua \"suculência\" até a última gota."}],"nl":[{"type":"video","vimeoId":"1111560203"},{"type":"text","markdown":"### Tip van de dag:\n\nGa meer om met \"sappige\" mensen. Omring jezelf met mensen die van het leven houden, zich kunnen verheugen, vol energie en passie zitten. Hun levenskracht is besmettelijk. Vermijd chronische klagers en cynici – zij kunnen als energievampieren je \"sappigheid\" tot de laatste druppel opzuigen."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-28','intensive-pleasure',28,1,'День: 28','[{"type":"video","vimeoId":"1121764346"},{"type":"text","markdown":"### Совет дня:\n\nСделайте что-то впервые. Рутина и предсказуемость убивают вкус к жизни. Сделайте что-то, чего вы никогда не делали: попробуйте экзотическое блюдо, пойдите на работу другой дорогой, заговорите с незнакомцем, запишитесь на пробный урок танго... Новый опыт - это инъекция жизни в вашу нервную систему."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1121764346"},{"type":"text","markdown":"### Tip of the day:\n\nDo something for the first time. Routine and predictability kill the taste for life. Do something you have never done: try an exotic dish, take a different route to work, strike up a conversation with a stranger, sign up for a trial tango lesson... New experience is an injection of life into your nervous system."}],"de":[{"type":"video","vimeoId":"1121764346"},{"type":"text","markdown":"### Tipp des Tages:\n\nMachen Sie etwas zum ersten Mal. Routine und Vorhersehbarkeit töten den Geschmack am Leben. Machen Sie etwas, das Sie noch nie getan haben: Probieren Sie ein exotisches Gericht, gehen Sie zur Arbeit einen anderen Weg, sprechen Sie einen Fremden an, melden Sie sich zu einer Probestunde Tango an... Neue Erfahrung ist eine Injektion von Leben in Ihr Nervensystem."}],"fr":[{"type":"video","vimeoId":"1121764346"},{"type":"text","markdown":"### Conseil du jour :\n\nFaites quelque chose pour la première fois. La routine et la prévisibilité tuent le goût de vivre. Faites quelque chose que vous n’avez jamais fait : essayez un plat exotique, allez au travail par un autre chemin, parlez à un inconnu, inscrivez-vous à un cours d’essai de tango... Une nouvelle expérience est une injection de vie dans votre système nerveux."}],"it":[{"type":"video","vimeoId":"1121764346"},{"type":"text","markdown":"### Consiglio del giorno:\n\nFate qualcosa per la prima volta. La routine e la prevedibilità uccidono il gusto della vita. Fate qualcosa che non avete mai fatto: provate un piatto esotico, andate al lavoro per un''altra strada, parlate con uno sconosciuto, iscrivetevi a una lezione di prova di tango... La nuova esperienza è un''iniezione di vita nel vostro sistema nervoso."}],"es":[{"type":"video","vimeoId":"1121764346"},{"type":"text","markdown":"### Consejo del día:\n\nHaz algo por primera vez. La rutina y la previsibilidad matan el gusto por la vida. Haz algo que nunca hayas hecho: prueba un plato exótico, ve al trabajo por otro camino, habla con un desconocido, inscríbete en una clase de prueba de tango... La nueva experiencia es una inyección de vida en tu sistema nervioso."}],"pt":[{"type":"video","vimeoId":"1121764346"},{"type":"text","markdown":"### Dica do dia:\n\nFaça algo pela primeira vez. A rotina e a previsibilidade matam o gosto pela vida. Faça algo que você nunca fez: experimente um prato exótico, vá ao trabalho por outro caminho, converse com um estranho, inscreva-se em uma aula experimental de tango... A nova experiência é uma injeção de vida no seu sistema nervoso."}],"nl":[{"type":"video","vimeoId":"1121764346"},{"type":"text","markdown":"### Tip van de dag:\n\nDoe iets voor het eerst. Routine en voorspelbaarheid doden de smaak van het leven. Doe iets wat je nog nooit hebt gedaan: probeer een exotisch gerecht, ga via een andere route naar je werk, spreek een onbekende aan, schrijf je in voor een proefles tango... Nieuwe ervaring is een injectie van leven in je zenuwstelsel."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-29','intensive-pleasure',29,1,'День: 29','[{"type":"video","vimeoId":"1123090371"},{"type":"text","markdown":"### Совет дня:\n\nДвигайтесь ради удовольствия, а не ради результата. Найдите вид физической активности, который приносит вам радость в процессе: танцы, плавание, йога, прогулки. Перестаньте мучить себя в спортзале, если вы это ненавидите. Мир и без того наполнен насилием. Есть ли смысл его увеличивать? Движение, совершаемое из удовольствия, оздоравливает и тело, и психику."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1123090371"},{"type":"text","markdown":"### Tip of the day:\n\nMove for pleasure, not for the result. Find a type of physical activity that brings you joy in the process: dancing, swimming, yoga, walks. Stop tormenting yourself in the gym if you hate it. The world is already filled with violence. Is there any sense in increasing it? Movement done out of pleasure heals both the body and the psyche."}],"de":[{"type":"video","vimeoId":"1123090371"},{"type":"text","markdown":"### Tipp des Tages:\n\nBewegen Sie sich um des Vergnügens willen, nicht um des Ergebnisses willen. Finden Sie eine Form körperlicher Aktivität, die Ihnen im Prozess Freude bereitet: Tanzen, Schwimmen, Yoga, Spaziergänge. Hören Sie auf, sich im Fitnessstudio zu quälen, wenn Sie es hassen. Die Welt ist ohnehin voller Gewalt. Macht es Sinn, sie zu vermehren? Bewegung aus Vergnügen heilt sowohl Körper als auch Psyche."}],"fr":[{"type":"video","vimeoId":"1123090371"},{"type":"text","markdown":"### Conseil du jour :\n\nBougez pour le plaisir, et non pour le résultat. Trouvez un type d’activité physique qui vous apporte de la joie pendant le processus : danse, natation, yoga, promenades. Cessez de vous torturer à la salle de sport si vous détestez cela. Le monde est déjà rempli de violence. Y a-t-il un sens à l’augmenter ? Le mouvement accompli par plaisir assainit le corps et le psychisme."}],"it":[{"type":"video","vimeoId":"1123090371"},{"type":"text","markdown":"### Consiglio del giorno:\n\nMuovetevi per il piacere, non per il risultato. Trovate un tipo di attività fisica che vi dia gioia nel processo: danza, nuoto, yoga, passeggiate. Smettete di torturarvi in palestra se lo odiate. Il mondo è già pieno di violenza. Ha senso aumentarla? Il movimento fatto per piacere fa bene sia al corpo sia alla psiche."}],"es":[{"type":"video","vimeoId":"1123090371"},{"type":"text","markdown":"### Consejo del día:\n\nMuévete por placer, no por resultado. Encuentra un tipo de actividad física que te aporte alegría durante el proceso: bailar, nadar, yoga, caminar. Deja de torturarte en el gimnasio si lo odias. El mundo ya está lleno de violencia. ¿Tiene sentido aumentarla? El movimiento realizado por placer sana tanto el cuerpo como la psique."}],"pt":[{"type":"video","vimeoId":"1123090371"},{"type":"text","markdown":"### Dica do dia:\n\nMova-se pelo prazer, e não pelo resultado. Encontre um tipo de atividade física que lhe traga alegria no processo: dança, natação, yoga, caminhadas. Pare de se torturar na academia se você odeia isso. O mundo já está cheio de violência. Faz sentido aumentá-la? O movimento feito por prazer traz saúde tanto ao corpo quanto à psique."}],"nl":[{"type":"video","vimeoId":"1123090371"},{"type":"text","markdown":"### Tip van de dag:\n\nBeweeg voor je plezier, niet voor het resultaat. Zoek een vorm van lichamelijke activiteit die je tijdens het proces vreugde brengt: dansen, zwemmen, yoga, wandelen. Stop met jezelf te kwellen in de sportschool als je daar een hekel aan hebt. De wereld is toch al vol geweld. Heeft het zin dat te vergroten? Beweging die uit plezier wordt gedaan, maakt zowel het lichaam als de psyche gezonder."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-pleasure-30','intensive-pleasure',30,1,'День: 30','[{"type":"video","vimeoId":"1124547375"},{"type":"text","markdown":"### Что дальше?\n\nЯ надеюсь, что этот месяц практик принёс вам ощутимые результаты, и после выполнения этой практики у вас может возникнуть вопрос - «Что дальше?»… И тут перед вами большой выбор практикумов, интенсивов и курсов, которые я подготовил для гармонизации самых разных сфер жизни и внутренних психологических состояний. Чтобы сориентироваться, сначала определитесь с направлением - что сейчас вас более всего трогает, то есть вызывает дискомфорт, тревожит, воодушевляет… (где есть яркие эмоции - там есть энергия для развития), а затем подумайте сколько времени вы готовы посвятить урокам и практикам. Если сложно определиться, напишите мне или задайте вопрос на вебинаре. Ниже я перечислил практикумы и курсы, которые могут вас заинтересовать:\n\n\nПРАКТИКУМЫ:\n - Месяц здоровья: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Месяц наслаждений: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Месяц силы: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Месяц любви: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Месяц свободы: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Месяц мудрости: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Месяц святости: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nКУРСЫ:\n - Йога и здоровье: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Йога и женственность: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Тантра - мистерия взаимоотношений: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Осуществи мечту: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Планета любви: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Источник творческой силы: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 шагов йоги: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Путь души: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1124547375"},{"type":"text","markdown":"### What''s next?\n\nI hope this month of practices has brought you tangible results, and after completing this practice you may have a question — “What’s next?”… And here before you is a large choice of workshops, intensives, and courses that I have prepared for harmonizing a wide variety of areas of life and inner psychological states. To get your bearings, first decide on the direction — what touches you most right now, that is, causes discomfort, worries, inspires… (where there are vivid emotions, there is energy for development), and then think about how much time you are ready to devote to lessons and practices. If it is difficult to decide, write to me or ask a question at the webinar. Below I have listed the workshops and courses that may interest you:\n\n\nWORKSHOPS:\n - Month of Health: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Month of Pleasures: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Month of Strength: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Month of Love: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Month of Freedom: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Month of Wisdom: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Month of Holiness: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCOURSES:\n - Yoga and Health: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga and Femininity: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - the mystery of relationships: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Fulfill the Dream: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planet of Love: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Source of Creative Power: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 Steps of Yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Path of the Soul: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"de":[{"type":"video","vimeoId":"1124547375"},{"type":"text","markdown":"### Was kommt als Nächstes?\n\nIch hoffe, dass dieser Monat der Praktiken Ihnen spürbare Ergebnisse gebracht hat, und nach der Ausführung dieser Praxis kann bei Ihnen die Frage aufkommen - „Was kommt als Nächstes?“… Und hier haben Sie eine große Auswahl an Praxisprogrammen, Intensivkursen und Kursen, die ich zur Harmonisierung der verschiedensten Lebensbereiche und inneren psychologischen Zustände vorbereitet habe. Zur Orientierung bestimmen Sie zuerst die Richtung - was Sie gerade am meisten berührt, also Unbehagen auslöst, beunruhigt, begeistert… (wo starke Emotionen sind, dort ist Energie für Entwicklung), und dann überlegen Sie, wie viel Zeit Sie bereit sind, den Lektionen und Praktiken zu widmen. Wenn es schwerfällt, sich zu entscheiden, schreiben Sie mir oder stellen Sie eine Frage im Webinar. Unten habe ich Praxisprogramme und Kurse aufgelistet, die Sie interessieren könnten:\n\n\nPRAKTIKA:\n - Monat der Gesundheit: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Monat der Genüsse: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Monat der Kraft: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Monat der Liebe: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Monat der Freiheit: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Monat der Weisheit: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Monat der Heiligkeit: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nKURSE:\n - Yoga und Gesundheit: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga und Weiblichkeit: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - Mysterium der Beziehungen: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Verwirkliche den Traum: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planet der Liebe: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Quelle schöpferischer Kraft: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 Schritte des Yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Weg der Seele: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"fr":[{"type":"video","vimeoId":"1124547375"},{"type":"text","markdown":"### Et ensuite ?\n\nJ''espère que ce mois de pratiques vous a apporté des résultats sensibles, et qu''après avoir réalisé cette pratique, une question peut surgir : « Et ensuite ? »... Et ici s''ouvre devant vous un grand choix de séminaires pratiques, d''intensifs et de cours que j''ai préparés pour harmoniser les domaines les plus divers de la vie et les états psychologiques intérieurs. Pour vous orienter, déterminez d''abord la direction : ce qui vous touche le plus actuellement, c''est-à-dire provoque de l''inconfort, inquiète, inspire... (là où il y a des émotions vives, il y a de l''énergie pour le développement), puis réfléchissez au temps que vous êtes prêt à consacrer aux leçons et aux pratiques. S''il est difficile de vous décider, écrivez-moi ou posez une question lors du webinaire. Ci-dessous, j''ai énuméré les séminaires pratiques et les cours qui peuvent vous intéresser :\n\n\nATELIERS :\n - Mois de la santé : [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Mois des plaisirs : [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Mois de la force : [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Mois de l’amour : [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Mois de la liberté : [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Mois de la sagesse : [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Mois de la sainteté : [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCOURS :\n - Yoga et santé: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga et féminité: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - mystère des relations: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Réalise ton rêve: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planète de l''amour: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Source de force créatrice: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 pas de yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Chemin de l''âme: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"it":[{"type":"video","vimeoId":"1124547375"},{"type":"text","markdown":"### E adesso?\n\nSpero che questo mese di pratiche vi abbia portato risultati tangibili, e dopo aver completato questa pratica possa sorgervi la domanda: «E adesso?»… E qui davanti a voi c''è una grande scelta di laboratori pratici, intensivi e corsi che ho preparato per armonizzare le più diverse sfere della vita e gli stati psicologici interiori. Per orientarvi, prima definite la direzione: ciò che adesso vi tocca di più, cioè vi crea disagio, vi preoccupa, vi ispira… (dove ci sono emozioni vive, lì c''è energia per lo sviluppo), e poi pensate a quanto tempo siete pronti a dedicare alle lezioni e alle pratiche. Se è difficile decidere, scrivetemi o fate una domanda al webinar. Qui sotto ho elencato i laboratori pratici e i corsi che potrebbero interessarvi:\n\n\nPRATICUM:\n - Mese della salute: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Mese dei piaceri: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Mese della forza: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Mese dell''amore: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Mese della libertà: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Mese della saggezza: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Mese della santità: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCORSI:\n - Yoga e salute: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga e femminilità: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - mistero delle relazioni: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Realizza il sogno: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Pianeta dell''amore: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Fonte di forza creativa: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 passi di yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Il cammino dell''anima: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"es":[{"type":"video","vimeoId":"1124547375"},{"type":"text","markdown":"### ¿Qué sigue?\n\nEspero que este mes de prácticas le haya traído resultados tangibles, y que después de realizar esta práctica pueda surgirle la pregunta: «¿Qué sigue?»… Y aquí tiene ante usted una gran elección de talleres prácticos, intensivos y cursos que he preparado para armonizar las más diversas esferas de la vida y estados psicológicos internos. Para orientarse, primero defina la dirección: qué es lo que ahora más lo toca, es decir, le causa malestar, le preocupa, le inspira… (donde hay emociones vivas, allí hay energía para el desarrollo), y luego piense cuánto tiempo está dispuesto a dedicar a las lecciones y prácticas. Si le resulta difícil decidirse, escríbame o haga la pregunta en el webinar. A continuación he enumerado los talleres prácticos y cursos que pueden interesarle:\n\n\nTALLERES:\n - Mes de la salud: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Mes de los placeres: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Mes de la fuerza: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Mes del amor: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Mes de la libertad: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Mes de la sabiduría: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Mes de la santidad: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCURSOS:\n - Yoga y salud: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga y feminidad: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - misterio de las relaciones: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Haz realidad tu sueño: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planeta del amor: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Fuente de la fuerza creativa: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 pasos del yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Camino del alma: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"pt":[{"type":"video","vimeoId":"1124547375"},{"type":"text","markdown":"### O que vem a seguir?\n\nEspero que este mês de práticas tenha trazido a você resultados perceptíveis, e, após realizar esta prática, pode surgir em você a pergunta - «O que vem a seguir?»… E aqui você tem uma grande escolha de práticas, intensivos e cursos que preparei para harmonizar as mais diversas áreas da vida e estados psicológicos internos. Para se orientar, primeiro defina a direção - o que agora mais toca você, ou seja, causa desconforto, o preocupa, o inspira… (onde há emoções intensas, ali há energia para o desenvolvimento), e depois pense quanto tempo você está disposto a dedicar às aulas e práticas. Se for difícil decidir, escreva para mim ou faça uma pergunta no webinar. Abaixo listei as práticas e cursos que podem interessar a você:\n\n\nPRATICUNS:\n - Mês da saúde: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Mês dos prazeres: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Mês da força: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Mês do amor: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Mês da liberdade: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Mês da sabedoria: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Mês da santidade: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCURSOS:\n - Yoga e saúde: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga e feminilidade: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - mistério das relações: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Realize o sonho: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planeta do amor: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Fonte da força criativa: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 passos de yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Caminho da alma: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"nl":[{"type":"video","vimeoId":"1124547375"},{"type":"text","markdown":"### Wat nu?\n\nIk hoop dat deze maand van praktijken je voelbare resultaten heeft gebracht, en dat na het uitvoeren van deze praktijk bij je de vraag kan opkomen - «Wat nu?»… En hier heb je een grote keuze aan prakticums, intensives en cursussen die ik heb voorbereid voor het harmoniseren van de meest uiteenlopende levensgebieden en innerlijke psychologische toestanden. Om je te oriënteren, bepaal eerst de richting - wat je nu het meest raakt, dat wil zeggen ongemak veroorzaakt, je bezighoudt, inspireert… (waar levendige emoties zijn - daar is energie voor ontwikkeling), en bedenk daarna hoeveel tijd je bereid bent aan lessen en praktijken te besteden. Als het moeilijk is om te kiezen, schrijf me of stel een vraag tijdens het webinar. Hieronder heb ik de prakticums en cursussen opgesomd die je mogelijk interesseren:\n\n\nPRAKTIJKEN:\n - Maand van gezondheid: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Maand van genot: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Maand van kracht: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Maand van liefde: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Maand van vrijheid: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Maand van wijsheid: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Maand van heiligheid: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCURSUSSEN:\n - Yoga en gezondheid: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga en vrouwelijkheid: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - mysterie van relaties: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Verwezenlijk je droom: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planeet van de liefde: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Bron van creatieve kracht: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 stappen van yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Pad van de ziel: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}]}'::jsonb,null) on conflict(id) do nothing;
